/*
-----------------------------------------------
Blogger Tema Bilgileri
Name:     Manowa Manga, Manhwa & Novel Teması
Version:  1.1.0
-----------------------------------------------

<Variable name="keycolor" description="Ana Renk Teması" type="color" default="#6366f1" value="#6366f1"/>
<Variable name="body.background" description="Arka Plan Resmi" color="$(body.background.color)" type="background" default="$(color) none repeat scroll top left" value="$(color) none repeat scroll top left"/>

<Group description="1. Koyu Tema Arka Plan Renkleri" selector="body">
  <Variable name="body.background.color" description="Birincil Arka Plan (--bg-primary)" type="color" default="#0f1117" value="#0f1117"/>
  <Variable name="theme.bg.secondary" description="İkincil Panel Arka Planı (--bg-secondary)" type="color" default="#181b24" value="#181b24"/>
  <Variable name="theme.bg.card" description="Kart ve Kutu Arka Planı (--bg-card)" type="color" default="#1f2330" value="#1f2330"/>
  <Variable name="theme.border.color" description="Kenarlık Rengi (--border-color)" type="color" default="#2e3446" value="#2e3446"/>
</Group>

<Group description="2. Metin ve Vurgu Renkleri" selector=".site-main">
  <Variable name="theme.text.primary" description="Birincil Metin Rengi (--text-primary)" type="color" default="#f1f5f9" value="#f1f5f9"/>
  <Variable name="theme.text.secondary" description="İkincil Açıklama Metni (--text-secondary)" type="color" default="#94a3b8" value="#94a3b8"/>
  <Variable name="theme.accent.primary" description="Ana Vurgu Rengi (--accent-primary)" type="color" default="#6366f1" value="#6366f1"/>
  <Variable name="theme.accent.hover" description="Vurgu Üzerine Gelme Rengi (--accent-hover)" type="color" default="#818cf8" value="#818cf8"/>
</Group>

<Group description="3. Açık (Light) Tema Renkleri" selector="[data-theme='light']">
  <Variable name="light.bg.primary" description="Açık Tema Birincil Arka Plan" type="color" default="#f8fafc" value="#f8fafc"/>
  <Variable name="light.bg.secondary" description="Açık Tema İkincil Arka Plan" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="light.bg.card" description="Açık Tema Kart Arka Planı" type="color" default="#f1f5f9" value="#f1f5f9"/>
  <Variable name="light.text.primary" description="Açık Tema Birincil Metin" type="color" default="#0f172a" value="#0f172a"/>
  <Variable name="light.text.secondary" description="Açık Tema İkincil Metin" type="color" default="#475569" value="#475569"/>
  <Variable name="light.accent.primary" description="Açık Tema Vurgu Rengi" type="color" default="#4f46e5" value="#4f46e5"/>
  <Variable name="light.accent.hover" description="Açık Tema Vurgu Hover" type="color" default="#4338ca" value="#4338ca"/>
  <Variable name="light.border.color" description="Açık Tema Kenarlık Rengi" type="color" default="#e2e8f0" value="#e2e8f0"/>
</Group>

<Group description="4. Tür Rozeti Renkleri (Manhwa, Manga, Manhua, Novel)" selector=".catalog-grid">
  <Variable name="badge.kr.color" description="Manhwa (KR) Rozet Rengi" type="color" default="#ef4444" value="#ef4444"/>
  <Variable name="badge.jp.color" description="Manga (JP) Rozet Rengi" type="color" default="#ec4899" value="#ec4899"/>
  <Variable name="badge.cn.color" description="Manhua (CN) Rozet Rengi" type="color" default="#f59e0b" value="#f59e0b"/>
  <Variable name="badge.en.color" description="Novel / Diğer Rozet Rengi" type="color" default="#3b82f6" value="#3b82f6"/>
</Group>

<Group description="5. Tipografi ve Yazı Tipi" selector="body">
  <Variable name="body.font" description="Site Ana Yazı Tipi" type="font" default="normal normal 16px 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" value="normal normal 16px 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"/>
</Group>

<Variable name="disqus.shortname" description="Disqus Forum Shortname" type="string" default="" value=""/>
<Variable name="theme.default.mode" description="Varsayılan Tema Modu (dark veya light)" type="string" default="dark" value="dark"/>
*/
/* === MODULE: styles/variables.css === */
/**
 * @fileoverview Manowa Blogger Temasi - Temel CSS degiskenleri ve sifirlama kurallari.
 * Koyu (Dark) ve Acik (Light) tema renk paletlerini tanimlar.
 */

:root {
  --bg-primary: #0f1117;
  --bg-secondary: #181b24;
  --bg-card: #1f2330;
  --text-primary: #f1f5f9;
  --text-secondary: #94a3b8;
  --accent-primary: #6366f1;
  --accent-hover: #818cf8;
  --badge-kr: #ef4444;
  --badge-jp: #ec4899;
  --badge-cn: #f59e0b;
  --badge-en: #3b82f6;
  --border-color: #2e3446;
  --radius-md: 10px;
  --radius-lg: 16px;
  --font-main: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

[data-theme="light"] {
  --bg-primary: #f8fafc;
  --bg-secondary: #ffffff;
  --bg-card: #f1f5f9;
  --text-primary: #0f172a;
  --text-secondary: #475569;
  --accent-primary: #4f46e5;
  --accent-hover: #4338ca;
  --border-color: #e2e8f0;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

body {
  background-color: var(--bg-primary);
  color: var(--text-primary);
  font-family: var(--font-main);
  line-height: 1.6;
  overflow-x: clip;
}

/* === MODULE: styles/cards.css === */
/**
 * @fileoverview Katalog izgara kartlari, seri detay sayfasi, bolum listesi ve Disqus stilleri.
 */

.catalog-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(210px, 1fr));
  gap: 1.25rem;
  margin-bottom: 2.5rem;
}

.series-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform 0.22s ease, border-color 0.22s ease, box-shadow 0.22s ease;
}

.series-card:hover {
  transform: translateY(-4px);
  border-color: var(--accent-primary);
  box-shadow: 0 10px 24px rgba(0, 0, 0, 0.28);
}

.card-cover-wrap {
  display: block;
  position: relative;
  aspect-ratio: 3 / 4;
  background: var(--bg-card);
  overflow: hidden;
  cursor: pointer;
  text-decoration: none;
}

.card-cover {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.35s ease;
}

.series-card:hover .card-cover {
  transform: scale(1.05);
}

.lang-badge {
  position: absolute;
  top: 0.6rem;
  left: 0.6rem;
  padding: 0.2rem 0.55rem;
  border-radius: 6px;
  font-size: 0.72rem;
  font-weight: 700;
  color: #ffffff;
  text-transform: uppercase;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.35);
}

.lang-badge.lang-KR {
  background: var(--badge-kr);
}

.lang-badge.lang-JP {
  background: var(--badge-jp);
}

.lang-badge.lang-CN {
  background: var(--badge-cn);
}

.lang-badge.lang-EN {
  background: var(--badge-en);
}

.type-badge {
  position: absolute;
  top: 0.6rem;
  right: 0.6rem;
  padding: 0.2rem 0.5rem;
  border-radius: 6px;
  font-size: 0.7rem;
  font-weight: 700;
  background: rgba(15, 17, 23, 0.82);
  color: #f8fafc;
  backdrop-filter: blur(4px);
}

.card-body {
  padding: 0.85rem;
  display: flex;
  flex-direction: column;
  flex: 1;
  gap: 0.5rem;
}

.card-title {
  font-size: 0.98rem;
  font-weight: 700;
  color: var(--text-primary);
  cursor: pointer;
  text-decoration: none;
  display: -webkit-box;
  -webkit-line-clamp: 1;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.card-title:hover {
  color: var(--accent-primary);
}

.card-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.78rem;
  color: var(--text-secondary);
}

.card-chapters {
  margin-top: auto;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  padding-top: 0.5rem;
  border-top: 1px solid var(--border-color);
}

.chapter-mini-btn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--bg-card);
  color: var(--text-primary);
  border: 1px solid transparent;
  padding: 0.35rem 0.6rem;
  border-radius: 6px;
  font-size: 0.78rem;
  font-weight: 600;
  cursor: pointer;
  text-decoration: none;
  transition: all 0.18s ease;
}

.chapter-mini-btn:hover {
  border-color: var(--accent-primary);
  color: var(--accent-primary);
}

.series-nav-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 1rem;
  flex-wrap: wrap;
}

.breadcrumb-trail {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.88rem;
  color: var(--text-secondary);
}

.breadcrumb-link {
  color: var(--accent-hover);
  text-decoration: none;
  font-weight: 600;
  cursor: pointer;
}

.breadcrumb-link:hover {
  text-decoration: underline;
}

.series-detail-box {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  margin-bottom: 2rem;
}

.series-detail-header {
  display: grid;
  grid-template-columns: 220px 1fr;
  gap: 1.75rem;
  align-items: start;
}

.detail-cover {
  width: 100%;
  aspect-ratio: 3 / 4;
  object-fit: cover;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
}

.detail-info h1 {
  font-size: 2.55rem;
  font-weight: 800;
  margin-bottom: 0;
}

.detail-alt-title {
  color: var(--text-secondary);
  font-size: 0.9rem;
  margin-bottom: 0.85rem;
}

.detail-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 0;
}

.meta-tag {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  padding: 0.28rem 0.65rem;
  border-radius: 6px;
  font-size: 0.8rem;
  font-weight: 600;
}

.detail-synopsis {
  color: var(--text-secondary);
  font-size: 0.94rem;
  margin-bottom: 1.25rem;
  line-height: 1.65;
}

.detail-actions {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.primary-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  background: var(--accent-primary);
  color: #ffffff;
  border: none;
  padding: 0.65rem 1.25rem;
  border-radius: var(--radius-md);
  font-weight: 700;
  font-size: 0.9rem;
  cursor: pointer;
  text-decoration: none;
  transition: background 0.2s ease;
}

.primary-btn:hover {
  background: var(--accent-hover);
}

.chapter-list-box {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1.25rem;
  margin-bottom: 2rem;
}

.chapter-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 0.7rem;
  max-height: 480px;
  overflow-y: auto;
  padding: 4px 0.25rem 4px 0;
}

.chapter-item-btn {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: stretch;
  gap: 0.45rem;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  padding: 0.75rem 0.9rem;
  border-radius: var(--radius-md);
  cursor: pointer;
  text-align: left;
  text-decoration: none;
  transition: all 0.2s ease;
}

.chapter-item-btn:hover {
  border-color: var(--accent-primary);
}

.chapter-item-btn.is-read {
  opacity: 1;
  border-color: rgba(16, 185, 129, 0.42);
  border-left: 3px solid #10b981;
  background: rgba(16, 185, 129, 0.06);
}

.disqus-container {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  margin-top: 2rem;
}

.disqus-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.disqus-status-note {
  color: var(--text-secondary);
  font-size: 0.88rem;
  padding: 1rem;
  background: var(--bg-card);
  border-radius: var(--radius-md);
  border: 1px dashed var(--border-color);
}

.fav-card-btn {
  position: absolute;
  bottom: 0.6rem;
  right: 0.6rem;
  z-index: 3;
  background: rgba(15, 17, 23, 0.85);
  color: #ffffff;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 999px;
  width: 34px;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 0.95rem;
  transition: transform 0.2s ease, background 0.2s ease;
}

.fav-card-btn:hover,
.fav-card-btn.is-fav {
  transform: scale(1.1);
  border-color: #ec4899;
}

.continue-reading-box,
.latest-chapters-box {
  margin-bottom: 1.75rem;
}

.continue-reading-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 0.85rem;
}

.continue-card,
.latest-chapter-card {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 0.65rem 0.85rem;
  text-decoration: none;
  color: var(--text-primary);
  transition: border-color 0.2s ease, transform 0.2s ease;
}

.continue-card:hover,
.latest-chapter-card:hover {
  border-color: var(--accent-primary);
  transform: translateY(-2px);
}

.continue-thumb,
.latest-chapter-thumb {
  width: 48px;
  height: 64px;
  object-fit: cover;
  border-radius: 6px;
  flex-shrink: 0;
  background: var(--bg-card);
}

.continue-info,
.latest-chapter-info {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  flex: 1;
  min-width: 0;
}

.continue-title,
.latest-series-name {
  font-size: 0.9rem;
  font-weight: 700;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.continue-meta,
.latest-chapter-date {
  font-size: 0.76rem;
  color: var(--text-secondary);
}

.latest-chapter-badge {
  display: inline-block;
  align-self: flex-start;
  background: rgba(99, 102, 241, 0.16);
  color: var(--accent-hover);
  font-size: 0.74rem;
  font-weight: 700;
  padding: 0.12rem 0.5rem;
  border-radius: 4px;
}

.continue-play {
  color: var(--accent-primary);
  font-size: 0.9rem;
  font-weight: 700;
}

.latest-chapters-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 0.85rem;
}

@media (max-width: 768px) {
  .catalog-grid {
    grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
    gap: 0.85rem;
    margin-bottom: 1.75rem;
  }

  .continue-reading-grid,
  .latest-chapters-grid {
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 0.65rem;
  }

  .series-detail-header {
    grid-template-columns: 1fr;
  }

  .detail-cover {
    max-width: 200px;
    margin: 0 auto;
  }

  .disqus-container {
    padding: 1rem;
    margin-top: 1.25rem;
  }
}

@media (max-width: 540px) {
  .catalog-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.65rem;
  }

  .card-body {
    padding: 0.6rem;
    gap: 0.38rem;
  }

  .card-title {
    font-size: 0.86rem;
  }

  .card-meta {
    font-size: 0.72rem;
  }

  .chapter-mini-btn {
    padding: 0.3rem 0.45rem;
    font-size: 0.72rem;
  }

  .lang-badge,
  .type-badge {
    font-size: 0.64rem;
    padding: 0.15rem 0.42rem;
    top: 0.4rem;
  }

  .lang-badge {
    left: 0.4rem;
  }

  .type-badge {
    right: 0.4rem;
  }

  .fav-card-btn {
    width: 30px;
    height: 30px;
    bottom: 0.4rem;
    right: 0.4rem;
    font-size: 0.82rem;
  }

  .continue-reading-grid,
  .latest-chapters-grid {
    grid-template-columns: 1fr;
  }
}

/* === MODULE: styles/series-page.css === */
/**
 * @fileoverview Baştan tasarlanan Seri Bilgileri Sayfası (#view-series) stilleri.
 * Bulanık arka planlı vitrin, yapılandırılmış meta veri ızgarası, bölüm arama çubuğu,
 * numaralı bölüm kartları ve benzer seriler öneri şeridini kapsar.
 */

.series-detail-box {
  background: transparent;
  border: none;
  padding: 0;
  margin-bottom: 1.75rem;
}

.series-hero-card {
  position: relative;
  overflow: hidden;
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 2rem;
  box-shadow: var(--shadow-card);
  isolation: isolate;
}

.series-backdrop {
  position: absolute;
  inset: -24px;
  background-size: cover;
  background-position: center 25%;
  filter: blur(28px) saturate(1.2);
  opacity: 0.24;
  transform: scale(1.08);
  z-index: -2;
}

html[data-theme="light"] .series-backdrop {
  opacity: 0.14;
}

.series-backdrop-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    115deg,
    rgba(11, 15, 25, 0.94) 0%,
    rgba(15, 23, 42, 0.86) 55%,
    rgba(17, 24, 39, 0.78) 100%
  );
  z-index: -1;
}

html[data-theme="light"] .series-backdrop-overlay {
  background: linear-gradient(
    115deg,
    rgba(255, 255, 255, 0.95) 0%,
    rgba(248, 250, 252, 0.9) 60%,
    rgba(241, 245, 249, 0.85) 100%
  );
}

.series-detail-header {
  display: grid;
  grid-template-columns: 240px minmax(0, 1fr) 420px;
  gap: 1.75rem;
  align-items: center;
}

.series-poster-col {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
}

.series-poster-frame {
  position: relative;
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.16);
  box-shadow: 0 14px 32px rgba(0, 0, 0, 0.38);
  background: var(--bg-card);
}

.series-poster-frame .detail-cover {
  display: block;
  width: 100%;
  aspect-ratio: 3 / 4;
  object-fit: cover;
  border: none;
  border-radius: 0;
}

.series-poster-quick-actions {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 0.5rem;
}

.series-poster-quick-actions .icon-btn {
  justify-content: center;
}

.series-fav-btn.is-fav {
  border-color: rgba(239, 68, 68, 0.55);
  background: rgba(239, 68, 68, 0.14);
  color: #f87171;
}

html[data-theme="light"] .series-fav-btn.is-fav {
  color: #dc2626;
}

.series-info-col {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.series-top-pills {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.series-status-pill,
.series-format-pill,
.series-year-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.76rem;
  font-weight: 700;
  padding: 0.24rem 0.7rem;
  border-radius: 999px;
  border: 1px solid var(--border-color);
}

.series-status-pill {
  background: rgba(16, 185, 129, 0.16);
  border-color: rgba(16, 185, 129, 0.4);
  color: #34d399;
}

html[data-theme="light"] .series-status-pill {
  color: #059669;
}

.series-format-pill {
  background: rgba(99, 102, 241, 0.18);
  border-color: rgba(99, 102, 241, 0.4);
  color: var(--accent-hover);
}

html[data-theme="light"] .series-format-pill {
  color: var(--accent-primary);
}

.series-year-pill {
  background: var(--bg-card);
  color: var(--text-secondary);
}

.detail-info .series-main-title,
.series-main-title {
  font-size: 2.55rem;
  font-weight: 800;
  line-height: 1.12;
  letter-spacing: -0.02em;
  margin: -0.25rem 0 0;
  color: var(--text-primary);
}

.detail-alt-title {
  color: var(--text-secondary);
  font-size: 0.9rem;
  margin: -0.55rem 0 0;
}

.detail-info .series-genre-list,
.series-genre-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin: -0.35rem 0 0;
}

.series-genre-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  background: var(--bg-card);
  color: var(--text-secondary);
  border: 1px solid var(--border-color);
  padding: 0.34rem 0.78rem;
  border-radius: 999px;
  font-size: 0.8rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.18s ease;
}

.series-genre-pill:hover {
  background: var(--accent-primary);
  border-color: var(--accent-primary);
  color: #ffffff;
}

.series-meta-col {
  width: 100%;
  min-width: 0;
}

.series-meta-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.75rem;
}

.series-meta-card {
  background: rgba(15, 23, 42, 0.42);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 0.85rem 1.05rem;
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  min-width: 0;
}

html[data-theme="light"] .series-meta-card {
  background: rgba(241, 245, 249, 0.75);
}

.series-meta-label {
  font-size: 0.8rem;
  color: var(--text-secondary);
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
}

.series-meta-label .ui-icon {
  color: var(--accent-primary);
  width: 15px;
  height: 15px;
}

.series-meta-value {
  font-size: 0.98rem;
  font-weight: 700;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.series-synopsis-card {
  background: rgba(15, 23, 42, 0.38);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1.15rem 1.25rem;
  min-height: 168px;
  display: flex;
  flex-direction: column;
}

html[data-theme="light"] .series-synopsis-card {
  background: rgba(241, 245, 249, 0.75);
}

.series-synopsis-title {
  font-size: 0.88rem;
  font-weight: 700;
  color: var(--text-primary);
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  margin-bottom: 0.55rem;
}

.series-synopsis-title .ui-icon {
  color: var(--accent-primary);
}

.series-synopsis-card .detail-synopsis {
  margin: 0;
  font-size: 0.94rem;
  line-height: 1.65;
  min-height: 4.65rem;
  color: var(--text-secondary);
}

.series-synopsis-card .detail-synopsis.is-collapsed {
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.series-synopsis-card .detail-synopsis.is-expanded {
  display: block;
  max-height: 240px;
  overflow-y: auto;
  padding-right: 0.3rem;
}

.series-synopsis-toggle {
  display: inline-flex;
  align-items: center;
  align-self: flex-start;
  gap: 0.3rem;
  margin-top: 0.55rem;
  padding: 0;
  background: transparent;
  border: none;
  color: var(--accent-hover);
  font-size: 0.84rem;
  font-weight: 700;
  cursor: pointer;
  transition: color 0.18s ease, opacity 0.18s ease;
}

html[data-theme="light"] .series-synopsis-toggle {
  color: var(--accent-primary);
}

.series-synopsis-toggle:hover {
  color: var(--accent-primary);
  text-decoration: underline;
}

.detail-actions.series-cta-bar,
.series-cta-bar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  row-gap: 0.9rem;
  column-gap: 0.75rem;
  margin: 0.25rem 0 0;
  padding-top: 0;
}

.series-cta-bar .series-cta-btn,
.series-cta-bar .series-cta-secondary,
.series-cta-bar .series-cta-resume {
  min-height: 42px;
  padding: 0.62rem 1.05rem;
  font-size: 0.86rem;
  line-height: 1.25;
}

.series-cta-btn {
  box-shadow: 0 6px 18px rgba(99, 102, 241, 0.3);
}

.series-cta-resume {
  border-color: rgba(99, 102, 241, 0.5);
  color: var(--accent-hover);
}

.chapter-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  margin-bottom: 1rem;
  padding-bottom: 0.85rem;
  border-bottom: 1px solid var(--border-color);
}

.chapter-toolbar-left {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  flex-wrap: wrap;
}

.series-chapter-count-pill {
  background: rgba(99, 102, 241, 0.16);
  color: var(--accent-hover);
  border: 1px solid rgba(99, 102, 241, 0.35);
  font-size: 0.76rem;
  font-weight: 700;
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
}

.chapter-toolbar-right {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  flex-wrap: wrap;
}

.chapter-search-box {
  position: relative;
  display: flex;
  align-items: center;
}

.chapter-search-box .ui-icon {
  position: absolute;
  left: 0.7rem;
  color: var(--text-secondary);
  pointer-events: none;
}

.chapter-search-input {
  padding: 0.45rem 0.85rem 0.45rem 2.1rem;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  background: var(--bg-card);
  color: var(--text-primary);
  font-size: 0.85rem;
  outline: none;
  min-width: 210px;
  transition: border-color 0.2s ease;
}

.chapter-search-input:focus {
  border-color: var(--accent-primary);
}

.chapter-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 0.7rem;
  max-height: 480px;
  overflow-y: auto;
  padding: 4px 0.25rem 4px 0;
}

.chapter-card-item {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: stretch;
  gap: 0.45rem;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 0.75rem 0.9rem;
  text-decoration: none;
  color: var(--text-primary);
  transition: border-color 0.2s ease, transform 0.18s ease, background 0.2s ease;
}

.chapter-card-item:hover {
  border-color: var(--accent-primary);
  transform: translateY(-2px);
}

.chapter-card-item.is-read {
  opacity: 1;
  border-color: rgba(16, 185, 129, 0.42);
  border-left: 3px solid #10b981;
  background: rgba(16, 185, 129, 0.06);
}

.chapter-box-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.4rem;
  min-width: 0;
}

.chapter-title-text {
  font-size: 0.92rem;
  font-weight: 800;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.chapter-box-bottom {
  position: relative;
  display: flex;
  align-items: center;
  min-width: 0;
  min-height: 1.15rem;
}

.chapter-sub-meta {
  font-size: 0.76rem;
  color: var(--text-secondary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  transition: opacity 0.16s ease, transform 0.16s ease;
}

.chapter-card-item:hover .chapter-sub-meta,
.chapter-card-item:focus-visible .chapter-sub-meta {
  opacity: 0;
  transform: translateY(-2px);
}

.chapter-read-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  color: #34d399;
  background: rgba(16, 185, 129, 0.16);
  border-radius: 999px;
  flex-shrink: 0;
}

html[data-theme="light"] .chapter-read-badge {
  color: #059669;
}

.chapter-open-pill {
  position: absolute;
  left: 0;
  top: 50%;
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--accent-primary);
  opacity: 0;
  transform: translateY(-40%);
  pointer-events: none;
  transition: opacity 0.16s ease, transform 0.16s ease, color 0.16s ease;
  white-space: nowrap;
}

.chapter-card-item:hover .chapter-open-pill,
.chapter-card-item:focus-visible .chapter-open-pill {
  opacity: 1;
  color: var(--accent-primary);
  transform: translateY(-50%);
}

.series-related-box {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1.25rem;
  margin-bottom: 2rem;
}

.series-related-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
  gap: 0.85rem;
}

.series-related-card {
  display: flex;
  align-items: center;
  gap: 0.8rem;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 0.6rem;
  text-decoration: none;
  color: var(--text-primary);
  transition: border-color 0.2s ease, transform 0.2s ease;
}

.series-related-card:hover {
  border-color: var(--accent-primary);
  transform: translateY(-2px);
}

.series-related-thumb {
  width: 52px;
  height: 70px;
  object-fit: cover;
  border-radius: 6px;
  flex-shrink: 0;
  background: var(--bg-secondary);
}

.series-related-info {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  min-width: 0;
}

.series-related-type {
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--accent-hover);
}

.series-related-title {
  font-size: 0.88rem;
  font-weight: 700;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.series-related-meta {
  font-size: 0.74rem;
  color: var(--text-secondary);
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
}

@media (max-width: 1080px) {
  .series-detail-header {
    grid-template-columns: 200px minmax(0, 1fr);
    gap: 1.35rem;
  }

  .series-meta-col {
    grid-column: 1 / -1;
  }

  .series-meta-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

@media (max-width: 768px) {
  .series-hero-card {
    padding: 1.35rem;
  }

  .series-detail-header {
    grid-template-columns: 1fr;
    gap: 1.15rem;
  }

  .series-poster-col {
    max-width: 180px;
    margin: 0 auto;
    width: 100%;
  }

  .series-info-col {
    align-items: center;
    text-align: center;
    gap: 0.9rem;
  }

  .series-top-pills,
  .detail-info .series-genre-list,
  .series-genre-list {
    justify-content: center;
  }

  .detail-info .series-main-title,
  .series-main-title {
    font-size: 1.72rem;
    margin: 0;
  }

  .detail-alt-title {
    margin: -0.35rem 0 0;
  }

  .series-synopsis-card {
    width: 100%;
    text-align: left;
    min-height: auto;
    padding: 0.95rem 1rem;
  }

  .detail-actions.series-cta-bar,
  .series-cta-bar {
    justify-content: center;
    width: 100%;
  }

  .series-meta-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.6rem;
  }

  .chapter-list-box,
  .series-related-box {
    padding: 1rem;
  }

  .chapter-toolbar {
    flex-direction: column;
    align-items: stretch;
    gap: 0.75rem;
  }

  .chapter-toolbar-left {
    justify-content: space-between;
    width: 100%;
  }

  .chapter-toolbar-right {
    width: 100%;
    display: flex;
    gap: 0.5rem;
  }

  .chapter-search-box {
    flex: 1;
    min-width: 0;
  }

  .chapter-search-input {
    width: 100%;
    min-width: 0;
  }

  .chapter-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.55rem;
    max-height: 420px;
  }
}

@media (max-width: 480px) {
  .series-hero-card {
    padding: 1.1rem 0.9rem;
  }

  .series-poster-col {
    max-width: 155px;
  }

  .detail-info .series-main-title,
  .series-main-title {
    font-size: 1.4rem;
  }

  .series-meta-card {
    padding: 0.7rem 0.8rem;
  }

  .series-meta-value {
    font-size: 0.88rem;
  }

  .detail-actions.series-cta-bar,
  .series-cta-bar {
    flex-direction: column;
    align-items: stretch;
    gap: 0.55rem;
  }

  .series-cta-bar .series-cta-btn,
  .series-cta-bar .series-cta-secondary,
  .series-cta-bar .series-cta-resume {
    width: 100%;
    justify-content: center;
  }

  .chapter-toolbar-right {
    flex-direction: row;
    align-items: center;
  }

  .chapter-toolbar-right .icon-btn {
    width: 38px;
    height: 38px;
    padding: 0;
    justify-content: center;
    flex-shrink: 0;
  }

  .chapter-card-item {
    padding: 0.6rem 0.7rem;
  }

  .chapter-title-text {
    font-size: 0.84rem;
  }

  .series-related-grid {
    grid-template-columns: 1fr;
  }
}

/* === MODULE: styles/hero-slider.css === */
/**
 * @fileoverview Minimalist ana sayfa vitrin kaydiricisi (Hero Slider) stilleri.
 * Sadece arka plan gorseli, baslik, tek buton, kenar gecis oklari ve sade nokta gostergeleri icerir.
 */

.hero-banner {
  position: relative;
  overflow: hidden;
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 2rem 3.75rem 2.25rem;
  margin-bottom: 2rem;
  box-shadow: var(--shadow-card);
  isolation: isolate;
}

.hero-backdrop {
  position: absolute;
  inset: -20px;
  background-size: cover;
  background-position: center 30%;
  filter: blur(24px) saturate(1.25);
  opacity: 0.32;
  transform: scale(1.06);
  z-index: -2;
  transition: background-image 0.4s ease;
}

html[data-theme="light"] .hero-backdrop {
  opacity: 0.18;
}

.hero-backdrop-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    rgba(11, 15, 25, 0.92) 0%,
    rgba(11, 15, 25, 0.76) 60%,
    rgba(17, 24, 39, 0.55) 100%
  );
  z-index: -1;
}

html[data-theme="light"] .hero-backdrop-overlay {
  background: linear-gradient(
    90deg,
    rgba(255, 255, 255, 0.94) 0%,
    rgba(248, 250, 252, 0.85) 60%,
    rgba(241, 245, 249, 0.72) 100%
  );
}

@keyframes heroFade {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.hero-slide-grid {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 2rem;
  align-items: center;
  animation: heroFade 0.3s ease-out;
}

.hero-content {
  min-width: 0;
}

.hero-title {
  font-size: 2.15rem;
  font-weight: 800;
  line-height: 1.2;
  margin-bottom: 0.6rem;
  letter-spacing: -0.02em;
}

.hero-title-link {
  color: var(--text-primary);
  text-decoration: none;
  transition: color 0.2s ease;
}

.hero-title-link:hover {
  color: var(--accent-primary);
}

.hero-details {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.45rem;
  margin-bottom: 0.7rem;
}

.hero-genres {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-bottom: 0.55rem;
}

.hero-detail-item {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--text-primary);
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid var(--border-color);
  padding: 0.22rem 0.65rem;
  border-radius: 999px;
}

html[data-theme="light"] .hero-detail-item {
  background: rgba(15, 23, 42, 0.06);
}

.hero-detail-type {
  background: rgba(99, 102, 241, 0.2);
  border-color: rgba(99, 102, 241, 0.45);
  color: #a5b4fc;
}

html[data-theme="light"] .hero-detail-type {
  color: var(--accent-primary);
}

.hero-detail-genre {
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--text-secondary);
  background: rgba(148, 163, 184, 0.12);
  padding: 0.2rem 0.55rem;
  border-radius: 6px;
}

.hero-desc {
  color: var(--text-secondary);
  font-size: 0.92rem;
  line-height: 1.55;
  max-width: 640px;
  margin-bottom: 1.1rem;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.hero-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.65rem;
}

.hero-primary-cta {
  padding: 0.65rem 1.35rem;
  border-radius: 999px;
  font-size: 0.9rem;
  box-shadow: 0 6px 18px rgba(99, 102, 241, 0.35);
}

.hero-detail-btn {
  background: rgba(255, 255, 255, 0.08);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
  padding: 0.62rem 1.25rem;
  border-radius: 999px;
  font-size: 0.88rem;
  font-weight: 600;
  text-decoration: none;
  transition: all 0.2s ease;
}

html[data-theme="light"] .hero-detail-btn {
  background: rgba(15, 23, 42, 0.06);
}

.hero-detail-btn:hover {
  border-color: var(--accent-primary);
  color: var(--accent-primary);
}

.hero-cover-wrap {
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-poster-card {
  display: block;
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.18);
  box-shadow: 0 14px 32px rgba(0, 0, 0, 0.45);
  transition: transform 0.25s ease;
}

.hero-poster-card:hover {
  transform: scale(1.03);
}

.hero-cover-img {
  width: 145px;
  height: 200px;
  object-fit: cover;
  display: block;
}

.hero-arrow-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 1px solid var(--border-color);
  background: rgba(15, 23, 42, 0.55);
  color: #ffffff;
  font-size: 1.3rem;
  line-height: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  backdrop-filter: blur(6px);
  transition: all 0.2s ease;
  z-index: 2;
}

html[data-theme="light"] .hero-arrow-btn {
  background: rgba(255, 255, 255, 0.75);
  color: var(--text-primary);
}

.hero-arrow-btn:hover {
  background: var(--accent-primary);
  border-color: var(--accent-primary);
  color: #ffffff;
}

.hero-arrow-prev {
  left: 0.85rem;
}

.hero-arrow-next {
  right: 0.85rem;
}

.hero-dots-bar {
  position: absolute;
  bottom: 0.8rem;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 0.45rem;
  z-index: 2;
}

.hero-dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  border: none;
  background: rgba(255, 255, 255, 0.3);
  padding: 0;
  cursor: pointer;
  transition: all 0.25s ease;
}

html[data-theme="light"] .hero-dot {
  background: rgba(15, 23, 42, 0.25);
}

.hero-dot:hover {
  background: rgba(255, 255, 255, 0.65);
}

.hero-dot.active {
  width: 24px;
  background: var(--accent-primary);
}

@media (max-width: 768px) {
  .hero-banner {
    padding: 1.35rem 2.5rem 2rem;
    margin-bottom: 1.35rem;
  }

  .hero-slide-grid {
    grid-template-columns: 1fr;
    gap: 0.85rem;
    text-align: center;
  }

  .hero-cover-wrap {
    order: -1;
  }

  .hero-cover-img {
    width: 112px;
    height: 154px;
  }

  .hero-title {
    font-size: 1.35rem;
    margin-bottom: 0.45rem;
  }

  .hero-details,
  .hero-genres {
    justify-content: center;
  }

  .hero-desc {
    margin-left: auto;
    margin-right: auto;
    font-size: 0.85rem;
    margin-bottom: 0.85rem;
  }

  .hero-actions {
    justify-content: center;
  }

  .hero-arrow-btn {
    width: 30px;
    height: 30px;
    font-size: 1.15rem;
  }

  .hero-arrow-prev {
    left: 0.45rem;
  }

  .hero-arrow-next {
    right: 0.45rem;
  }
}

@media (max-width: 480px) {
  .hero-banner {
    padding: 1.15rem 2.1rem 1.85rem;
  }

  .hero-cover-img {
    width: 96px;
    height: 132px;
  }

  .hero-title {
    font-size: 1.18rem;
  }

  .hero-primary-cta,
  .hero-detail-btn {
    padding: 0.52rem 0.95rem;
    font-size: 0.82rem;
  }
}

/* === MODULE: styles/sidebar.css === */
/**
 * @fileoverview 2 sutunlu ana sayfa duzeni (.home-layout-grid) ve sag yan panel (Sidebar) stilleri.
 */

.home-layout-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 330px;
  gap: 1.75rem;
  align-items: start;
}

.home-main-column {
  min-width: 0;
}

.home-sidebar {
  position: sticky;
  top: 5.25rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.sidebar-cta-banners {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.sidebar-cta-card {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  padding: 0.9rem 1rem;
  border-radius: var(--radius-lg);
  text-decoration: none;
  color: #ffffff;
  border: 1px solid rgba(255, 255, 255, 0.14);
  box-shadow: var(--shadow-card);
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
  position: relative;
  overflow: hidden;
}

.sidebar-cta-card:hover {
  transform: translateY(-2px);
  border-color: rgba(255, 255, 255, 0.35);
}

.sidebar-cta-card.cta-join-team {
  background: linear-gradient(135deg, #4f46e5 0%, #7c3aed 55%, #db2777 100%);
}

.sidebar-cta-card.cta-join-discord {
  background: linear-gradient(135deg, #5865f2 0%, #4752c4 60%, #313896 100%);
}

.sidebar-cta-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.16);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: #ffffff;
}

.sidebar-cta-icon .ui-icon {
  width: 20px;
  height: 20px;
}

.sidebar-cta-text {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  min-width: 0;
  flex: 1;
}

.sidebar-cta-title {
  font-size: 0.92rem;
  font-weight: 800;
  color: #ffffff;
  line-height: 1.25;
}

.sidebar-cta-sub {
  font-size: 0.73rem;
  color: rgba(255, 255, 255, 0.86);
  line-height: 1.3;
}

.sidebar-cta-badge {
  font-size: 0.72rem;
  font-weight: 700;
  padding: 0.28rem 0.58rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.2);
  color: #ffffff;
  white-space: nowrap;
  flex-shrink: 0;
  transition: background 0.18s ease;
}

.sidebar-cta-card:hover .sidebar-cta-badge {
  background: rgba(255, 255, 255, 0.32);
}

.sidebar-widget {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1.15rem;
  box-shadow: var(--shadow-card);
}

.sidebar-widget-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin-bottom: 0.9rem;
  padding-bottom: 0.65rem;
  border-bottom: 1px solid var(--border-color);
}

.sidebar-widget-title {
  font-size: 1rem;
  font-weight: 700;
  color: var(--text-primary);
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  margin: 0;
}

.sidebar-widget-title .ui-icon {
  color: var(--accent-primary);
  width: 1.1em;
  height: 1.1em;
}

.sidebar-tabs {
  display: flex;
  gap: 0.35rem;
  margin-bottom: 0.85rem;
  background: var(--bg-card);
  padding: 0.25rem;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
}

.sidebar-tab-btn {
  flex: 1;
  background: transparent;
  color: var(--text-secondary);
  border: none;
  padding: 0.32rem 0.45rem;
  border-radius: 6px;
  font-size: 0.75rem;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.18s ease;
}

.sidebar-tab-btn:hover,
.sidebar-tab-btn.active {
  background: var(--accent-primary);
  color: #ffffff;
}

.sidebar-rank-list {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.sidebar-rank-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.5rem;
  border-radius: var(--radius-md);
  background: var(--bg-card);
  border: 1px solid transparent;
  text-decoration: none;
  color: var(--text-primary);
  transition: border-color 0.2s ease, transform 0.2s ease;
}

.sidebar-rank-item:hover {
  border-color: var(--accent-primary);
  transform: translateX(3px);
}

.sidebar-rank-badge {
  width: 28px;
  height: 28px;
  border-radius: 7px;
  background: rgba(148, 163, 184, 0.14);
  color: var(--text-secondary);
  font-size: 0.76rem;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.sidebar-rank-badge.rank-top-1 {
  background: linear-gradient(135deg, #6366f1, #8b5cf6);
  color: #ffffff;
}

.sidebar-rank-badge.rank-top-2 {
  background: rgba(99, 102, 241, 0.22);
  color: var(--accent-hover);
  border: 1px solid rgba(99, 102, 241, 0.4);
}

.sidebar-rank-badge.rank-top-3 {
  background: rgba(236, 72, 153, 0.18);
  color: #f472b6;
  border: 1px solid rgba(236, 72, 153, 0.35);
}

.sidebar-rank-thumb {
  width: 44px;
  height: 58px;
  object-fit: cover;
  border-radius: 6px;
  flex-shrink: 0;
  background: var(--bg-secondary);
}

.sidebar-rank-info {
  display: flex;
  flex-direction: column;
  gap: 0.22rem;
  min-width: 0;
  flex: 1;
}

.sidebar-rank-title {
  font-size: 0.86rem;
  font-weight: 700;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sidebar-rank-meta {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.74rem;
  color: var(--text-secondary);
}

.sidebar-rank-type {
  background: rgba(99, 102, 241, 0.14);
  color: var(--accent-hover);
  padding: 0.08rem 0.42rem;
  border-radius: 4px;
  font-weight: 600;
}

.sidebar-genres-cloud {
  display: flex;
  flex-wrap: wrap;
  gap: 0.42rem;
}

.sidebar-genre-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.38rem;
  background: var(--bg-card);
  color: var(--text-secondary);
  border: 1px solid var(--border-color);
  padding: 0.32rem 0.65rem;
  border-radius: 999px;
  font-size: 0.76rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.18s ease;
}

.sidebar-genre-chip:hover,
.sidebar-genre-chip.active {
  background: var(--accent-primary);
  color: #ffffff;
  border-color: var(--accent-primary);
}

.sidebar-genre-count {
  font-size: 0.68rem;
  opacity: 0.8;
  background: rgba(0, 0, 0, 0.2);
  padding: 0.05rem 0.38rem;
  border-radius: 999px;
}

.sidebar-stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.5rem;
  margin-bottom: 0.85rem;
}

.sidebar-stat-box {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 0.55rem 0.35rem;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
}

.sidebar-stat-val {
  font-size: 1.05rem;
  font-weight: 800;
  color: var(--accent-hover);
}

.sidebar-stat-lbl {
  font-size: 0.7rem;
  color: var(--text-secondary);
}

.sidebar-fav-mini-list {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.sidebar-fav-mini-item {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.4rem 0.55rem;
  border-radius: 8px;
  background: var(--bg-card);
  border: 1px solid transparent;
  color: var(--text-primary);
  text-decoration: none;
  font-size: 0.8rem;
  transition: border-color 0.18s ease;
}

.sidebar-fav-mini-item:hover {
  border-color: var(--accent-primary);
}

.sidebar-fav-mini-thumb {
  width: 28px;
  height: 38px;
  object-fit: cover;
  border-radius: 4px;
  flex-shrink: 0;
}

.sidebar-fav-mini-title {
  flex: 1;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sidebar-fav-mini-count {
  font-size: 0.72rem;
  color: var(--text-secondary);
}

.sidebar-empty-note {
  font-size: 0.8rem;
  color: var(--text-secondary);
  padding: 0.65rem;
  background: var(--bg-card);
  border-radius: var(--radius-md);
  border: 1px dashed var(--border-color);
  line-height: 1.5;
}

.blogger-sidebar-gadgets {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.blogger-sidebar-gadgets:empty,
.blogger-footer-gadgets:empty {
  display: none;
}

.blogger-sidebar-gadgets .widget,
.blogger-footer-gadgets .widget {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1.15rem;
  color: var(--text-primary);
  text-align: left;
}

.blogger-footer-gadgets {
  max-width: 1280px;
  margin: 0 auto 1.25rem;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 1rem;
}

.blogger-sidebar-gadgets .widget h2,
.blogger-sidebar-gadgets .widget h3,
.blogger-footer-gadgets .widget h2,
.blogger-footer-gadgets .widget h3 {
  font-size: 1rem;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0 0 0.75rem 0;
  padding-bottom: 0.55rem;
  border-bottom: 1px solid var(--border-color);
}

.blogger-sidebar-gadgets .widget a,
.blogger-footer-gadgets .widget a {
  color: var(--accent-hover);
  text-decoration: none;
}

@media (max-width: 1024px) {
  .home-layout-grid {
    grid-template-columns: 1fr;
  }

  .home-sidebar {
    position: static;
  }
}

@media (max-width: 768px) {
  .sidebar-cta-banners {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: 0.65rem;
  }

  .sidebar-widget {
    padding: 0.95rem;
  }

  .blogger-footer-gadgets {
    grid-template-columns: 1fr;
  }
}

/* === MODULE: styles/search.css === */
/**
 * @fileoverview Arama cubugu acilir liste kutusu (Listbox / Combobox) stilleri.
 * Acilir pencere yerlesimi, kartlar, kapak resimleri, rozetler ve mobil uyum.
 */

.search-results-listbox {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  width: 380px;
  max-width: min(420px, calc(100vw - 1.5rem));
  max-height: 480px;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.45), 0 4px 14px rgba(0, 0, 0, 0.25);
  z-index: 1050;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  animation: searchFadeDown 0.16s cubic-bezier(0.16, 1, 0.3, 1);
}

.search-results-listbox.hidden {
  display: none !important;
}

@keyframes searchFadeDown {
  from {
    opacity: 0;
    transform: translateY(-6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.search-results-list {
  overflow-y: auto;
  max-height: 400px;
  overscroll-behavior: contain;
  display: flex;
  flex-direction: column;
}

.search-results-list::-webkit-scrollbar {
  width: 6px;
}

.search-results-list::-webkit-scrollbar-thumb {
  background: var(--border-color);
  border-radius: 999px;
}

.search-result-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.65rem 0.85rem;
  cursor: pointer;
  border-bottom: 1px solid var(--border-color);
  background: transparent;
  transition: background 0.15s ease, border-color 0.15s ease;
  user-select: none;
}

.search-result-item:last-child {
  border-bottom: none;
}

.search-result-item:hover,
.search-result-item.is-active {
  background: var(--bg-secondary);
}

.search-result-item:focus-visible {
  outline: 2px solid var(--accent-primary);
  outline-offset: -2px;
}

.search-result-thumb {
  width: 44px;
  height: 60px;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  overflow: hidden;
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: center;
}

.search-result-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.search-thumb-fallback {
  color: var(--text-muted);
  font-weight: 700;
  font-size: 1.1rem;
}

.search-result-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.search-result-title {
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--text-primary);
  line-height: 1.25;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.search-result-alt {
  font-size: 0.76rem;
  color: var(--text-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.search-result-meta {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  flex-wrap: wrap;
  margin-top: 0.15rem;
}

.search-badge {
  font-size: 0.68rem;
  font-weight: 600;
  padding: 0.1rem 0.45rem;
  border-radius: 999px;
  line-height: 1.2;
}

.search-badge.badge-type {
  background: var(--accent-glow);
  color: var(--accent-primary);
  border: 1px solid rgba(var(--accent-rgb, 124, 58, 237), 0.3);
}

.search-badge.badge-status {
  background: var(--bg-secondary);
  color: var(--text-secondary);
  border: 1px solid var(--border-color);
}

.search-badge.badge-chapter {
  color: var(--text-muted);
  font-size: 0.72rem;
  padding: 0;
}

.search-result-genres {
  display: flex;
  gap: 0.25rem;
  flex-wrap: wrap;
  margin-top: 0.15rem;
}

.search-genre-tag {
  font-size: 0.68rem;
  color: var(--text-muted);
  background: var(--bg-secondary);
  padding: 0.08rem 0.32rem;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
}

/* Eslesen metin vurgulama (Arka plan degismez, yalnizca vurgu yazi rengi ve kalinlik) */
mark.search-highlight {
  background: transparent !important;
  color: var(--accent-primary) !important;
  font-weight: 700;
  padding: 0;
  border: none;
  border-radius: 0;
  text-decoration: none;
}

/* Eslesen kategori etiketi vurgusu */
.search-genre-tag.is-matched {
  border-color: var(--accent-primary);
  background: var(--accent-glow);
  color: var(--accent-primary);
  font-weight: 700;
}

/* Eslesen rozetler (Tur, Durum) */
.search-badge.is-matched {
  border-color: var(--accent-primary);
  background: var(--accent-glow);
  color: var(--accent-primary);
}

/* Eslesme kaynagi bildirimi (Alternatif ad veya Kategori) */
.search-match-source {
  font-size: 0.74rem;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  gap: 0.25rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  margin-top: 0.1rem;
}

.search-match-label {
  font-size: 0.68rem;
  font-weight: 700;
  color: var(--accent-primary);
  background: var(--accent-glow);
  padding: 0.05rem 0.3rem;
  border-radius: var(--radius-sm);
  border: 1px solid rgba(var(--accent-rgb, 124, 58, 237), 0.25);
  flex-shrink: 0;
}

.search-result-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.65rem 0.85rem;
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
  color: var(--accent-primary);
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s ease;
  user-select: none;
}

.search-result-footer:hover,
.search-result-footer.is-active {
  background: var(--accent-primary);
  color: #ffffff;
}

.search-result-footer .ui-icon {
  flex-shrink: 0;
  transition: transform 0.15s ease;
}

.search-result-footer:hover .ui-icon,
.search-result-footer.is-active .ui-icon {
  transform: translateX(3px);
}

.search-empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 1.75rem 1.25rem;
  text-align: center;
  color: var(--text-secondary);
  gap: 0.45rem;
}

.search-empty-icon {
  color: var(--text-muted);
  margin-bottom: 0.2rem;
}

.search-empty-text {
  font-size: 0.88rem;
  color: var(--text-primary);
}

.search-empty-hint {
  font-size: 0.76rem;
  color: var(--text-muted);
}

@media (max-width: 768px) {
  .search-results-listbox {
    position: absolute;
    top: calc(100% + 6px);
    left: 0;
    right: 0;
    width: 100%;
    max-width: 100%;
    max-height: calc(85vh - 70px);
    border-radius: var(--radius-md);
  }

  .search-result-item {
    padding: 0.75rem 0.85rem;
  }

  .search-result-thumb {
    width: 48px;
    height: 64px;
  }
}

/* === MODULE: styles/layout.css === */
/**
 * @fileoverview Ana yerlesim (layout), ust baslik, vitrin (hero) ve filtre cubugu stilleri.
 */

.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(15, 17, 23, 0.88);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-color);
  transition: background-color 0.25s ease;
}

body[data-active-view="reader"] .site-header {
  position: relative;
}

[data-theme="light"] .site-header {
  background: rgba(255, 255, 255, 0.9);
}

.header-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0.85rem 1.25rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}

.brand-group {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.brand-logo {
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--text-primary);
  text-decoration: none;
  letter-spacing: -0.5px;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.brand-logo span.accent {
  color: var(--accent-primary);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.nav-btn {
  background: transparent;
  color: var(--text-secondary);
  border: 1px solid transparent;
  padding: 0.45rem 0.85rem;
  border-radius: var(--radius-md);
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  transition: all 0.2s ease;
}

.nav-btn:hover,
.nav-btn.active {
  color: var(--text-primary);
  background: var(--bg-card);
  border-color: var(--border-color);
}

.header-controls {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  flex: 1;
  justify-content: flex-end;
  min-width: 240px;
}

.search-box {
  position: relative;
  flex: 1;
  max-width: 300px;
}

.search-input {
  width: 100%;
  padding: 0.5rem 0.9rem;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  background: var(--bg-secondary);
  color: var(--text-primary);
  font-size: 0.9rem;
  outline: none;
  transition: border-color 0.2s ease;
}

.search-input:focus {
  border-color: var(--accent-primary);
}

.icon-btn {
  background: var(--bg-card);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
  padding: 0.5rem 0.75rem;
  border-radius: var(--radius-md);
  cursor: pointer;
  font-size: 0.88rem;
  font-weight: 600;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  transition: all 0.2s ease;
}

.icon-btn:hover {
  border-color: var(--accent-primary);
  background: var(--accent-primary);
  color: #ffffff;
}

.site-main {
  max-width: 1280px;
  margin: 0 auto;
  padding: 1.5rem 1.25rem 4rem;
}

.filter-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1.5rem;
  flex-wrap: wrap;
  background: var(--bg-secondary);
  padding: 0.85rem 1rem;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
}

.filter-toolbar.in-header {
  background: transparent;
  border: none;
  padding: 0;
  margin-bottom: 0;
  flex: 1;
}

.lang-filters {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.filter-pill {
  background: var(--bg-card);
  color: var(--text-secondary);
  border: 1px solid var(--border-color);
  padding: 0.4rem 0.85rem;
  border-radius: 999px;
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}

.filter-pill:hover,
.filter-pill.active {
  background: var(--accent-primary);
  color: #ffffff;
  border-color: var(--accent-primary);
}

.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
}

.section-title {
  font-size: 1.25rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.site-footer {
  border-top: 1px solid var(--border-color);
  background: var(--bg-secondary);
  padding: 2rem 1.25rem;
  text-align: center;
  color: var(--text-secondary);
  font-size: 0.88rem;
}

.catalog-toolbar-right {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  flex-wrap: wrap;
}

.scroll-top-btn {
  position: fixed;
  right: 1.5rem;
  bottom: 1.5rem;
  z-index: 120;
  width: 44px;
  height: 44px;
  border-radius: 999px;
  background: var(--accent-primary);
  color: #ffffff;
  border: 1px solid rgba(255, 255, 255, 0.2);
  font-size: 1.2rem;
  font-weight: 800;
  cursor: pointer;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.35);
  transition: transform 0.2s ease, background 0.2s ease;
}

.scroll-top-btn:hover {
  transform: translateY(-3px);
  background: var(--accent-hover);
}

.hidden,
#main-blog-section,
.posts-wrapper {
  display: none !important;
}

.ui-icon {
  display: inline-block;
  width: 1em;
  height: 1em;
  vertical-align: -0.15em;
  flex-shrink: 0;
}

.section-title .ui-icon {
  color: var(--accent-primary);
  width: 1.15em;
  height: 1.15em;
}

.fav-card-btn.is-fav .ui-icon {
  color: #ef4444;
}

.mobile-only-btn {
  display: none;
}

@media (max-width: 768px) {
  .mobile-only-btn {
    display: inline-flex;
  }

  .btn-label,
  .btn-label-sub {
    display: none !important;
  }

  .header-inner {
    padding: 0.6rem 0.85rem;
    gap: 0.45rem;
    align-items: center;
  }

  #header-section,
  .brand-logo {
    order: 1;
    margin-right: auto;
  }

  .brand-logo {
    font-size: 1.2rem;
  }

  .filter-toolbar.in-header,
  .header-controls {
    display: contents;
  }

  #btn-mobile-search,
  #btn-theme-toggle,
  #btn-mobile-menu {
    order: 2;
    width: 38px;
    height: 38px;
    padding: 0;
    justify-content: center;
    flex-shrink: 0;
  }

  #btn-mobile-search.active,
  #btn-mobile-menu.active {
    background: var(--accent-primary);
    border-color: var(--accent-primary);
    color: #ffffff;
  }

  #dev-blog-origin-box {
    display: none !important;
  }

  #header-search-box {
    order: 3;
    width: 100%;
    flex: 0 0 100%;
    max-width: none;
    display: none;
    margin-top: 0.25rem;
  }

  #header-search-box.is-mobile-open {
    display: block;
  }

  #mobile-nav-drawer {
    order: 4;
    width: 100%;
    flex: 0 0 100%;
    display: none;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.45rem;
    padding: 0.6rem;
    margin-top: 0.25rem;
    background: var(--bg-secondary);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
    box-shadow: 0 10px 24px rgba(0, 0, 0, 0.28);
  }

  #mobile-nav-drawer.is-mobile-open {
    display: grid;
  }

  #mobile-nav-drawer .nav-btn {
    width: 100%;
    justify-content: flex-start;
    padding: 0.55rem 0.75rem;
    font-size: 0.84rem;
    background: var(--bg-card);
    border-color: var(--border-color);
  }

  #mobile-nav-drawer .nav-btn.active {
    background: var(--accent-primary);
    border-color: var(--accent-primary);
    color: #ffffff;
  }

  .site-main {
    padding: 1rem 0.75rem 3rem;
  }

  body[data-active-view="reader"] .site-main {
    padding: 0.35rem 0 2.5rem;
  }

  .filter-toolbar {
    padding: 0.65rem 0.75rem;
    gap: 0.65rem;
    margin-bottom: 1.15rem;
  }

  .lang-filters {
    width: 100%;
    flex-wrap: nowrap;
    overflow-x: auto;
    scrollbar-width: none;
    -webkit-overflow-scrolling: touch;
    gap: 0.4rem;
    padding-bottom: 2px;
  }

  .lang-filters::-webkit-scrollbar {
    display: none;
  }

  .filter-pill {
    white-space: nowrap;
    flex-shrink: 0;
    padding: 0.36rem 0.75rem;
    font-size: 0.78rem;
  }

  .catalog-toolbar-right {
    width: 100%;
    justify-content: space-between;
  }

  .section-header {
    flex-wrap: wrap;
    gap: 0.5rem;
  }

  .section-title {
    font-size: 1.08rem;
  }

  .scroll-top-btn {
    right: 1rem;
    bottom: 1rem;
    width: 40px;
    height: 40px;
    font-size: 1.05rem;
  }
}

@media (max-width: 480px) {
  .header-inner {
    padding: 0.55rem 0.65rem;
  }

  #mobile-nav-drawer {
    grid-template-columns: 1fr;
  }

  .icon-btn {
    padding: 0.44rem 0.65rem;
    font-size: 0.82rem;
  }

  .site-footer {
    padding: 1.5rem 0.85rem;
    font-size: 0.82rem;
  }
}

/* === MODULE: styles/reader.css === */
/**
 * @fileoverview Cok modlu okuma motoru (Webtoon, Tek Sayfa, Cift Sayfa ve Novel) stilleri.
 */

.reader-wrapper {
  position: relative;
  background: #090b10;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  overflow: visible;
  margin-bottom: 2rem;
}

.reader-sticky-header {
  position: sticky;
  top: 0;
  z-index: 110;
  background: rgba(11, 13, 19, 0.94);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: var(--radius-lg) var(--radius-lg) 0 0;
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.45);
}

.reader-progress-track {
  width: 100%;
  height: 3px;
  background: rgba(255, 255, 255, 0.08);
  border-radius: var(--radius-lg) var(--radius-lg) 0 0;
  overflow: hidden;
}

.reader-progress-bar {
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, var(--accent-primary), #ec4899);
  transition: width 0.2s ease;
}

.reader-toolbar {
  padding: 0.65rem 1rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.65rem;
  flex-wrap: nowrap;
  overflow-x: auto;
  scrollbar-width: none;
}

.reader-toolbar::-webkit-scrollbar {
  display: none;
}

.reader-title-group {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 0.45rem;
  flex: 0 1 auto;
  min-width: 0;
}

.reader-series-back-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  height: 36px;
  padding: 0 0.85rem;
  font-size: 0.82rem;
  font-weight: 700;
  color: #e2e8f0;
  text-decoration: none;
  background: #141824;
  border: 1px solid rgba(99, 102, 241, 0.32);
  border-radius: 9px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 260px;
  transition: all 0.18s ease;
}

.reader-series-back-btn:hover {
  background: var(--accent-primary);
  border-color: var(--accent-primary);
  color: #ffffff;
}

.reader-type-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 28px;
  padding: 0 0.6rem;
  border-radius: 7px;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  background: rgba(255, 255, 255, 0.08);
  color: #e2e8f0;
  border: 1px solid rgba(255, 255, 255, 0.14);
  flex-shrink: 0;
}

.reader-type-badge[data-type='manhwa'],
.reader-type-badge[data-type='manhua'] {
  background: rgba(79, 70, 229, 0.22);
  border-color: rgba(99, 102, 241, 0.45);
  color: #c7d2fe;
}

.reader-type-badge[data-type='manga'] {
  background: rgba(225, 29, 72, 0.22);
  border-color: rgba(244, 63, 94, 0.45);
  color: #fecdd3;
}

.reader-type-badge[data-type='novel'] {
  background: rgba(13, 148, 136, 0.22);
  border-color: rgba(20, 184, 166, 0.45);
  color: #99f6e4;
}

.reader-chapter-name {
  font-size: 0.88rem;
  font-weight: 700;
  color: #cbd5e1;
  line-height: 1.2;
}

.reader-chapter-switcher {
  display: inline-flex;
  align-items: center;
  height: 36px;
  background: #141824;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 10px;
  padding: 0.18rem;
  gap: 0.18rem;
  flex-shrink: 0;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.reader-step-btn {
  background: transparent;
  color: #cbd5e1;
  border: none;
  width: 28px;
  height: 28px;
  border-radius: 7px;
  font-size: 1.05rem;
  font-weight: 800;
  line-height: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.16s ease;
}

.reader-step-btn:hover:not(:disabled) {
  background: var(--accent-primary);
  color: #ffffff;
}

.reader-step-btn:disabled {
  opacity: 0.32;
  cursor: not-allowed;
}

.reader-chapter-select {
  background: transparent !important;
  border: none !important;
  height: 28px !important;
  padding: 0 0.65rem !important;
  min-width: 138px;
  font-weight: 700;
  text-align: center;
}

.reader-chapter-select:hover {
  background: rgba(255, 255, 255, 0.05) !important;
  color: #ffffff !important;
}

.reader-chapter-select option {
  background: #141824;
  color: #f1f5f9;
}

.reader-controls {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0.45rem;
  flex: 0 0 auto;
  flex-wrap: nowrap;
  white-space: nowrap;
}

.reader-control-cluster {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  flex-wrap: nowrap;
  flex-shrink: 0;
}

.reader-control-cluster.hidden,
.reader-footer-page-nav.hidden {
  display: none !important;
}

.reader-pill-group {
  display: inline-flex;
  align-items: center;
  height: 36px;
  background: #141824;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 9px;
  padding: 0.18rem;
  gap: 0.15rem;
  flex-shrink: 0;
  white-space: nowrap;
}

.reader-pill-btn {
  background: transparent;
  color: #e2e8f0;
  border: none;
  min-width: 28px;
  height: 28px;
  padding: 0 0.45rem;
  border-radius: 6px;
  font-size: 0.8rem;
  font-weight: 800;
  cursor: pointer;
  transition: all 0.16s ease;
}

.reader-pill-btn:hover {
  background: var(--accent-primary);
  color: #ffffff;
}

.reader-pill-value {
  font-size: 0.76rem;
  font-weight: 700;
  color: #cbd5e1;
  min-width: 44px;
  text-align: center;
  padding: 0 0.25rem;
}

.reader-select,
.reader-btn {
  background: #141824;
  color: #f1f5f9;
  border: 1px solid rgba(255, 255, 255, 0.1);
  height: 36px;
  padding: 0 0.65rem;
  border-radius: 9px;
  font-size: 0.78rem;
  font-weight: 600;
  white-space: nowrap;
  flex-shrink: 0;
  cursor: pointer;
  transition: all 0.18s ease;
}

.reader-select:hover,
.reader-btn:hover,
.reader-btn.active {
  border-color: var(--accent-primary);
  background: var(--accent-primary);
  color: #ffffff;
}

.reader-btn:disabled {
  opacity: 0.4;
  pointer-events: none;
}

.translator-note-box {
  max-width: 820px;
  margin: 1rem auto;
  padding: 0.85rem 1.15rem;
  background: rgba(99, 102, 241, 0.12);
  border-left: 4px solid var(--accent-primary);
  border-radius: 8px;
  color: #e2e8f0;
  font-size: 0.88rem;
}

.reader-viewport {
  --reader-zoom: 800px;
  --page-gap: 0px;
  min-height: 520px;
  padding: 1rem 0.5rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  user-select: none;
}

.reader-viewport.mode-webtoon {
  gap: var(--page-gap);
  padding: 0;
}

.reader-viewport.mode-webtoon .reader-page-item {
  width: 100%;
  max-width: var(--reader-zoom);
  display: block;
  margin: 0 auto;
}

.reader-viewport.mode-single,
.reader-viewport.mode-double {
  cursor: pointer;
}

.reader-viewport.mode-single .reader-logical-page {
  width: 100%;
  max-width: var(--reader-zoom);
  display: flex;
  flex-direction: column;
  gap: 0;
  margin: 0 auto;
  border-radius: 6px;
  overflow: hidden;
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.55);
}

.reader-viewport.mode-single .reader-page-item {
  width: 100%;
  max-width: var(--reader-zoom);
  height: auto;
  display: block;
  margin: 0;
}

.reader-viewport.mode-double .double-page-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.5rem;
  width: 100%;
  max-width: calc(var(--reader-zoom) * 1.6);
  align-items: start;
}

.reader-viewport.mode-double .reader-logical-page {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 0;
  border-radius: 4px;
  overflow: hidden;
}

.reader-viewport.mode-double .reader-page-item {
  width: 100%;
  height: auto;
  display: block;
  margin: 0;
}

.reader-viewport.mode-novel {
  user-select: text;
  padding: 2rem 1.5rem;
}

.novel-content-box {
  width: 100%;
  max-width: var(--reader-zoom);
  background: #131620;
  border: 1px solid #2e3446;
  border-radius: var(--radius-md);
  padding: 2rem;
  color: #e2e8f0;
  font-size: 1.05rem;
  line-height: 1.85;
}

.novel-content-box p,
.novel-content-box .orv_line {
  margin-bottom: 1.15rem;
}

.novel-content-box .orv_title h1 {
  font-size: 1.45rem;
  margin-bottom: 0.5rem;
  color: #ffffff;
}

.novel-content-box .orv_wordcount {
  font-size: 0.82rem;
  color: var(--text-secondary);
  margin-bottom: 1.25rem;
}

.novel-content-box .orv_quote,
.novel-content-box .orv_notice {
  background: rgba(99, 102, 241, 0.12);
  border-left: 4px solid var(--accent-primary);
  padding: 0.85rem 1.1rem;
  border-radius: 8px;
  margin-bottom: 1.15rem;
}

.novel-content-box img {
  max-width: 100%;
  height: auto;
  display: block;
  margin: 1rem auto;
  border-radius: 8px;
}

.reader-btn {
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}

.reader-viewport.protect-images img {
  pointer-events: none;
  -webkit-user-drag: none;
  user-select: none;
}

.reader-footer-bar {
  background: rgba(15, 17, 23, 0.96);
  border-top: 1px solid var(--border-color);
  border-radius: 0 0 var(--radius-lg) var(--radius-lg);
  padding: 0.8rem 1.15rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.85rem;
  flex-wrap: wrap;
}

.reader-footer-bar .reader-controls {
  flex: 0 1 auto;
  justify-content: flex-start;
}

.reader-footer-page-nav {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
}

.page-counter-pill {
  background: #1f2330;
  color: #f8fafc;
  padding: 0.35rem 0.85rem;
  border-radius: 999px;
  font-size: 0.8rem;
  font-weight: 700;
  border: 1px solid #2e3446;
}

.novel-content-box.font-serif {
  font-family: Georgia, 'Times New Roman', Times, serif;
}

@media (max-width: 768px) {
  .reader-wrapper {
    border-radius: 0;
    border-left: none;
    border-right: none;
    margin-bottom: 1.25rem;
  }

  .reader-sticky-header,
  .reader-progress-track {
    border-radius: 0;
  }

  .reader-toolbar {
    padding: 0.5rem 0.65rem;
    gap: 0.45rem;
    flex-wrap: wrap;
    justify-content: space-between;
  }

  .reader-title-group {
    flex: 1 1 auto;
    min-width: 0;
  }

  .reader-series-back-btn {
    max-width: 165px;
    height: 32px;
    padding: 0 0.65rem;
    font-size: 0.76rem;
  }

  .reader-type-badge {
    height: 24px;
    padding: 0 0.45rem;
    font-size: 0.62rem;
  }

  .reader-chapter-switcher {
    height: 32px;
    flex-shrink: 0;
  }

  .reader-step-btn {
    width: 26px;
    height: 26px;
    font-size: 0.95rem;
  }

  .reader-chapter-select {
    height: 26px !important;
    min-width: 108px;
    font-size: 0.76rem;
    padding: 0 0.45rem !important;
  }

  .reader-controls {
    width: 100%;
    justify-content: space-between;
    overflow-x: auto;
    scrollbar-width: none;
    -webkit-overflow-scrolling: touch;
    padding-top: 0.1rem;
  }

  .reader-controls::-webkit-scrollbar {
    display: none;
  }

  .reader-pill-group,
  .reader-select,
  .reader-btn {
    height: 32px;
    font-size: 0.74rem;
  }

  .reader-pill-btn {
    height: 24px;
    min-width: 24px;
  }

  .reader-pill-value {
    min-width: 38px;
    font-size: 0.72rem;
  }

  .translator-note-box {
    margin: 0.65rem;
    padding: 0.7rem 0.9rem;
    font-size: 0.82rem;
  }

  .reader-viewport {
    min-height: 360px;
    padding: 0.5rem 0;
  }

  .reader-viewport.mode-webtoon {
    padding: 0;
  }

  .reader-viewport.mode-single .reader-logical-page {
    border-radius: 0;
  }

  .reader-viewport.mode-double .double-page-grid {
    grid-template-columns: 1fr;
  }

  .reader-viewport.mode-novel {
    padding: 0.85rem 0.65rem;
  }

  .novel-content-box {
    padding: 1.15rem 0.95rem;
    font-size: 0.98rem;
    line-height: 1.75;
  }

  .reader-footer-bar {
    border-radius: 0;
    padding: 0.65rem 0.75rem;
    gap: 0.55rem;
    justify-content: space-between;
  }

  .reader-footer-page-nav {
    width: 100%;
    justify-content: space-between;
    order: -1;
  }
}

@media (max-width: 480px) {
  .reader-series-back-btn {
    max-width: 138px;
  }

  .reader-type-badge {
    display: none;
  }

  .reader-footer-bar .reader-btn {
    padding: 0 0.55rem;
    font-size: 0.72rem;
  }

  .page-counter-pill {
    padding: 0.28rem 0.65rem;
    font-size: 0.74rem;
  }
}

/* === BLOGGER THEME DESIGNER VARIABLE BINDINGS === */
:root {
  --bg-primary: $(body.background.color);
  --bg-secondary: $(theme.bg.secondary);
  --bg-card: $(theme.bg.card);
  --text-primary: $(theme.text.primary);
  --text-secondary: $(theme.text.secondary);
  --accent-primary: $(theme.accent.primary);
  --accent-hover: $(theme.accent.hover);
  --badge-kr: $(badge.kr.color);
  --badge-jp: $(badge.jp.color);
  --badge-cn: $(badge.cn.color);
  --badge-en: $(badge.en.color);
  --border-color: $(theme.border.color);
}

[data-theme="light"] {
  --bg-primary: $(light.bg.primary);
  --bg-secondary: $(light.bg.secondary);
  --bg-card: $(light.bg.card);
  --text-primary: $(light.text.primary);
  --text-secondary: $(light.text.secondary);
  --accent-primary: $(light.accent.primary);
  --accent-hover: $(light.accent.hover);
  --border-color: $(light.border.color);
}

body {
  background: $(body.background);
  background-color: var(--bg-primary);
  font: $(body.font);
}

head.b:template-skin:
body#layout {
  background-color: #f8fafc;
  color: #0f172a;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  padding: 16px;
  margin: 0;
}
body#layout #top-app-bar,
body#layout #view-catalog,
body#layout #view-series,
body#layout #view-reader,
body#layout #view-bookmarks,
body#layout #view-history,
body#layout #view-generator,
body#layout #disqus-section,
body#layout #btn-scroll-top,
body#layout .site-footer > p {
  display: none !important;
}
body#layout .site-header,
body#layout .site-main,
body#layout .site-footer {
  max-width: 100%;
  padding: 0;
  margin: 0 0 12px 0;
  background: transparent;
  border: none;
}
body#layout .header-inner {
  max-width: 100%;
  padding: 0;
  display: block;
}
body#layout div.section {
  background: #ffffff;
  border: 1px dashed #6366f1;
  border-radius: 10px;
  padding: 14px;
  margin: 0 0 14px 0;
  box-sizing: border-box;
}
body#layout #theme-config-section {
  display: block !important;
  background: #eef2ff;
  border: 2px solid #6366f1;
}
body#layout #theme-config-section .widget {
  width: 48.5%;
  display: inline-block;
  vertical-align: top;
  margin: 4px 0.5%;
  box-sizing: border-box;
}
body#layout .blogger-layout-columns {
  display: flex;
  gap: 14px;
  align-items: flex-start;
  width: 100%;
}
body#layout #main-blog-section {
  display: block !important;
  flex: 2;
  width: 65%;
  margin: 0;
}
body#layout #sidebar-gadgets-section {
  display: block !important;
  flex: 1;
  width: 35%;
  margin: 0;
}

body.script:
//
/* === MODULE: scripts/client-logger.js === */
/**
 * @fileoverview Tarayici (Client-Side) ortaminda DEBUG seviyesine kadar kayit tutan modul.
 * Sayfa her baslatildiginda eski oturum loglarini temizler ve yeni kayit acar.
 */

(function (globalScope) {
  'use strict';

  /**
   * Tarayici ici log kayitlarini yoneten nesne.
   */
  class ClientLogger {
    /**
     * ClientLogger nesnesini baslatir ve eski kayitlari sifirlar.
     * @param {string} [storageKey='manowa_debug_logs'] - Oturum kayit anahtari.
     */
    constructor(storageKey = 'manowa_debug_logs') {
      this.storageKey = storageKey;
      this.entries = [];
      this.clearLogs();
      this.debug('ClientLogger baslatildi. Eski oturum loglari temizlendi.');
    }

    /**
     * Mevcut log dizisini ve sessionStorage kaydini temizler.
     * @returns {void}
     */
    clearLogs() {
      this.entries = [];
      try {
        if (typeof sessionStorage !== 'undefined') {
          sessionStorage.removeItem(this.storageKey);
        }
      } catch (_err) {
        // Gizli sekme veya erisim kisitlamalarinda sessizce devam et
      }
    }

    /**
     * Belirtilen seviyede log kaydi ekler.
     * @param {'DEBUG'|'INFO'|'WARN'|'ERROR'} level - Log seviyesi.
     * @param {string} message - Aciklama mesaji.
     * @param {Object|null} [data=null] - Ek veri nesnesi.
     * @returns {Object} Olusturulan log kaydi.
     */
    write(level, message, data = null) {
      const entry = {
        timestamp: new Date().toISOString(),
        level: level,
        message: message,
        data: data
      };
      this.entries.push(entry);

      try {
        if (typeof sessionStorage !== 'undefined') {
          sessionStorage.setItem(this.storageKey, JSON.stringify(this.entries));
        }
      } catch (_err) {
        // Depolama siniri asilirsa bellekte tutmaya devam et
      }

      if (typeof console !== 'undefined') {
        const prefix = `[Manowa][${entry.timestamp}][${level}]`;
        if (level === 'ERROR' && console.error) {
          console.error(prefix, message, data || '');
        } else if (level === 'WARN' && console.warn) {
          console.warn(prefix, message, data || '');
        } else if (console.log) {
          console.log(prefix, message, data || '');
        }
      }

      return entry;
    }

    /**
     * DEBUG seviyesinde kayit yazar.
     * @param {string} message - Log mesaji.
     * @param {Object|null} [data=null] - Ek veri.
     * @returns {Object} Log kaydi.
     */
    debug(message, data = null) {
      return this.write('DEBUG', message, data);
    }

    /**
     * INFO seviyesinde kayit yazar.
     * @param {string} message - Log mesaji.
     * @param {Object|null} [data=null] - Ek veri.
     * @returns {Object} Log kaydi.
     */
    info(message, data = null) {
      return this.write('INFO', message, data);
    }

    /**
     * WARN seviyesinde kayit yazar.
     * @param {string} message - Log mesaji.
     * @param {Object|null} [data=null] - Ek veri.
     * @returns {Object} Log kaydi.
     */
    warn(message, data = null) {
      return this.write('WARN', message, data);
    }

    /**
     * ERROR seviyesinde kayit yazar.
     * @param {string} message - Log mesaji.
     * @param {Object|null} [data=null] - Ek veri.
     * @returns {Object} Log kaydi.
     */
    error(message, data = null) {
      return this.write('ERROR', message, data);
    }

    /**
     * Tum aktif oturum loglarini dondurur.
     * @returns {Array<Object>} Log listesi.
     */
    getEntries() {
      return this.entries.slice();
    }
  }

  const instance = new ClientLogger();
  globalScope.ManowaLogger = instance;

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = { ClientLogger, ManowaLogger: instance };
  }
})(typeof window !== 'undefined' ? window : globalThis);

