   * @param {string} [extraClass=''] - Ek CSS sinifi.
   * @returns {string} SVG HTML dizgesi.
   */
  function getSvgIcon(name, extraClass = '') {
    const def = ICON_DEFS[name] || ICON_DEFS.book;
    const cls = ['ui-icon', `ui-icon-${name}`, extraClass].filter(Boolean).join(' ');
    const fillAttr = def.filled ? 'currentColor' : 'none';
    return `<svg class="${cls}" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="${fillAttr}" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${def.paths}</svg>`;
