        chapters: [
          {
            id: 'kuzeyin-kilici-bolum-1',
            number: 1,
            title: 'Kuzeyin Kılıcı Bölüm 1',
            date: '2026-09-29',
            translatorNote: '',
            pages: [
              createSamplePageSvg('Kuzeyin Kılıcı - Bölüm 1', 1, '#be185d'),
              createSamplePageSvg('Kuzeyin Kılıcı - Bölüm 1', 2, '#9d174d')
            ]
          }
        ]
      },
      {
        id: 'golge-hukumdari',
        title: 'Gölge Hükümdarı',
        altTitle: 'Shadow Monarch',
        author: 'Chugong',
        artist: 'DUBU',
        sourceLang: 'KR',
        type: 'Manhwa',
        defaultReaderMode: 'webtoon',
        status: 'Devam Ediyor',
        translator: 'Manowa Çeviri',
        editor: 'Manowa Editör',
        rating: '9.6',
        genres: ['Aksiyon', 'Sistem'],
        cover: createSamplePageSvg('Gölge Hükümdarı', 1, '#4f46e5'),
        synopsis: 'Gizemli zindanların kapıları açıldığında en zayıf avcının adım adım zirveye yükselişi.',
        chapters: [
          {
            id: 'golge-hukumdari-bolum-1',
            number: 1,
            title: 'Gölge Hükümdarı Bölüm 1',
            date: '2026-09-26',
            translatorNote: '',
            pages: [
              createSamplePageSvg('Gölge Hükümdarı - Bölüm 1', 1, '#4f46e5'),
              createSamplePageSvg('Gölge Hükümdarı - Bölüm 1', 2, '#4338ca')
            ]
          }
        ]
      },
      {
        id: 'goksel-simyaci',
        title: 'Göksel Simyacı',
        altTitle: 'Celestial Alchemist',
        author: 'Lin Feng',
        artist: 'Studio Cloud',
        sourceLang: 'CN',
        type: 'Manhua',
        defaultReaderMode: 'webtoon',
        status: 'Devam Ediyor',
        translator: 'Manowa Çeviri',
        editor: 'Manowa Editör',
        rating: '9.5',
        genres: ['Reenkarnasyon', 'Dövüş Sanatları'],
        cover: createSamplePageSvg('Göksel Simyacı', 1, '#0d9488'),
        synopsis: 'Kadim simya sanatlarının efendisi, bin yıl sonra genç bir bedende yeniden uyanır.',
        chapters: [
          {
            id: 'goksel-simyaci-bolum-1',
            number: 1,
            title: 'Göksel Simyacı Bölüm 1',
            date: '2026-09-20',
            translatorNote: '',
            pages: [
              createSamplePageSvg('Göksel Simyacı - Bölüm 1', 1, '#0d9488')
            ]
          }
        ]
      }
    ];
  }

  /**
   * Seri katalogunu, dil/tur filtrelerini ve aramayi yoneten sinif.
   */
  class CatalogController {
    /**
     * CatalogController nesnesini baslatir.
     * @param {Array<Object>|null} [initialSeries=null] - Baslangic serileri.
     * @param {Object|null} [logger=null] - Logger nesnesi.
     */
    constructor(initialSeries = null, logger = null) {
      this.logger = logger || globalScope.ManowaLogger || null;
      this.seriesList =
        Array.isArray(initialSeries) && initialSeries.length > 0
          ? initialSeries
          : getDefaultCatalog();
      this.activeLang = 'ALL';
      this.activeGenre = 'ALL';
      this.searchQuery = '';
      this.sortBy = 'updated';
      this._log('debug', 'CatalogController baslatildi.', { count: this.seriesList.length });
    }

    /**
     * Ic loglama yardimcisi.
     * @param {'debug'|'info'|'warn'|'error'} level - Log seviyesi.
     * @param {string} msg - Mesaj.
     * @param {Object|null} [meta=null] - Ek veri.
     * @returns {void}
     */
    _log(level, msg, meta = null) {
      if (this.logger && typeof this.logger[level] === 'function') {
        this.logger[level](msg, meta);
      }
    }

    /**
     * Katalog listesini dinamik Blogger verisiyle tamamen degistirir.
     * @param {Array<Object>} newSeriesList - Yeni seri listesi.
     * @returns {Array<Object>} Guncellenmis seri listesi.
     */
    setSeriesList(newSeriesList) {
      if (Array.isArray(newSeriesList)) {
        this.seriesList = newSeriesList.slice();
        this._log('info', 'Katalog dinamik seri listesiyle guncellendi.', {
          count: this.seriesList.length
        });
      }
      return this.seriesList;
    }

    /**
     * Dil veya tur filtresini ayarlar (orn: 'ALL', 'KR', 'JP', 'Manhwa', 'Manga', 'Novel').
     * @param {string} langOrType - Dil veya tur kodu.
     * @returns {Array<Object>} Filtrelenmis seri listesi.
     */
    setLanguageFilter(langOrType) {
      this.activeLang = String(langOrType || 'ALL').trim().toUpperCase();
      this._log('info', 'Dil/Tur filtresi degistirildi.', { activeLang: this.activeLang });
      return this.getFilteredSeries();
    }

    /**
     * Kategori / etiket filtresini ayarlar (orn: 'ALL', 'Aksiyon', 'Zindan').
     * @param {string} genre - Kategori adi.
     * @returns {Array<Object>} Filtrelenmis seri listesi.
     */
    setGenreFilter(genre) {
      const clean = String(genre || 'ALL').trim();
      this.activeGenre = clean.toUpperCase() === 'ALL' ? 'ALL' : clean;
      this._log('info', 'Kategori filtresi degistirildi.', { activeGenre: this.activeGenre });
      return this.getFilteredSeries();
    }

    /**
     * Arama sorgusunu gunceller.
     * @param {string} query - Arama metni.
     * @returns {Array<Object>} Filtrelenmis seri listesi.
     */
    setSearchQuery(query) {
      this.searchQuery = String(query || '').trim().toLowerCase();
      this._log('debug', 'Arama sorgusu guncellendi.', { searchQuery: this.searchQuery });
      return this.getFilteredSeries();
    }

    /**
     * Katalog siralama olcutunu degistirir ('updated', 'title_asc', 'chapters_desc').
     * @param {string} sortOrder - Siralama tipi.
     * @returns {Array<Object>} Siralanmis ve filtrelenmis seri listesi.
     */
    setSortOrder(sortOrder) {
      const valid = ['updated', 'title_asc', 'chapters_desc'];
      this.sortBy = valid.includes(sortOrder) ? sortOrder : 'updated';
      this._log('info', 'Katalog siralamasi degistirildi.', { sortBy: this.sortBy });
      return this.getFilteredSeries();
    }

    /**
     * Aktif filtre, arama sorgusu ve siralama olcutune uyan serileri dondurur.
     * @returns {Array<Object>} Filtrelenmis ve siralanmis seriler.
     */
    getFilteredSeries() {
      const filtered = this.seriesList.filter((item) => {
        const itemLang = String(item.sourceLang || '').toUpperCase();
        const itemType = String(item.type || '').toUpperCase();
        const matchesLang =
          this.activeLang === 'ALL' ||
          itemLang === this.activeLang ||
          itemType === this.activeLang;

        if (!matchesLang) {
          return false;
        }

        if (this.activeGenre && this.activeGenre !== 'ALL') {
          const targetGenre = this.activeGenre.toLowerCase();
          const hasGenre = (item.genres || []).some(
            (g) => String(g || '').trim().toLowerCase() === targetGenre
          );
          if (!hasGenre) {
            return false;
          }
        }

        if (!this.searchQuery) {
          return true;
        }
        const haystack = [
          item.title,
          item.altTitle || '',
          item.type || '',
          item.status || '',
          (item.genres || []).join(' ')
        ]
          .join(' ')
          .toLowerCase();

        return haystack.includes(this.searchQuery);
      });

      if (this.sortBy === 'title_asc') {
        return filtered
          .slice()
          .sort((a, b) => String(a.title || '').localeCompare(String(b.title || ''), 'tr'));
      }
      if (this.sortBy === 'chapters_desc') {
        return filtered
          .slice()
          .sort((a, b) => (b.chapters || []).length - (a.chapters || []).length);
      }
      return filtered;
    }

    /**
     * ID degerine gore seri bulur.
     * @param {string} seriesId - Seri kimligi.
     * @returns {Object|null} Bulunan seri veya null.
     */
    getSeriesById(seriesId) {
      return this.seriesList.find((s) => s.id === seriesId) || null;
    }

    /**
     * Belirtilen serinin bolumlerini numara sirasina gore dondurur.
     * @param {string} seriesId - Seri kimligi.
     * @param {'asc'|'desc'} [order='desc'] - Siralama yonu.
     * @returns {Array<Object>} Siralanmis bolum listesi.
     */
    getSortedChapters(seriesId, order = 'desc') {
      const series = this.getSeriesById(seriesId);
      if (!series || !Array.isArray(series.chapters)) {
        return [];
      }
      const copy = series.chapters.slice();
      copy.sort((a, b) => (order === 'asc' ? a.number - b.number : b.number - a.number));
      return copy;
    }

    /**
     * Katalog icine yeni seri ekler veya mevcut seriyi gunceller.
     * @param {Object} seriesObj - Seri nesnesi.
     * @returns {void}
     */
    upsertSeries(seriesObj) {
      if (!seriesObj || !seriesObj.id) {
        return;
      }
      const idx = this.seriesList.findIndex((s) => s.id === seriesObj.id);
      if (idx >= 0) {
        this.seriesList[idx] = seriesObj;
      } else {
        this.seriesList.unshift(seriesObj);
      }
      this._log('info', 'Katalog serisi guncellendi.', { id: seriesObj.id });
    }
  }

  globalScope.CatalogController = CatalogController;
  globalScope.MANOWA_LANGUAGE_LABELS = LANGUAGE_LABELS;

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
      CatalogController,
      LANGUAGE_LABELS,
      getDefaultCatalog,
      createSamplePageSvg
    };
  }
})(typeof window !== 'undefined' ? window : globalThis);

/* === MODULE: scripts/user-library.js === */
/**
 * @fileoverview Kullanici kitapligi (Favoriler / Bookmarks), okuma gecmisi listesi ve
 * son eklenen bolumler akisini yoneten modul.
 */

(function (globalScope) {
  'use strict';

  const iconFn =
    (globalScope.ManowaIcons && globalScope.ManowaIcons.get) ||
    (typeof require === 'function' ? require('./svg-icons').getSvgIcon : () => '');

  /**
   * Favori serileri, okuma gecmisini ve son eklenen bolumleri yoneten sinif.
   */
  class UserLibrary {
    /**
     * UserLibrary nesnesini baslatir.
     * @param {Object} [options={}] - Yapilandirma secenekleri.
     */
    constructor(options = {}) {
      this.logger = options.logger || globalScope.ManowaLogger || null;
      this.storage =
        options.storage || (typeof localStorage !== 'undefined' ? localStorage : null);
      this.favoritesKey = options.favoritesKey || 'manowa_favorites';
      this.historyKey = options.historyKey || 'manowa_reading_history';
      this._log('debug', 'UserLibrary baslatildi.');
    }

    /**
     * SVG ikon uretici yardimci.
     * @param {string} name - Ikon adi.
     * @returns {string} SVG HTML.
     */
    _icon(name) {
      const fn =
        (globalScope.ManowaIcons && globalScope.ManowaIcons.get) || iconFn;
      return typeof fn === 'function' ? fn(name) : '';
    }

    /**
     * Ic loglama yardimcisi.
     * @param {'debug'|'info'|'warn'|'error'} level - Log seviyesi.
     * @param {string} msg - Log mesaji.
     * @param {Object|null} [meta=null] - Ek veri.
     * @returns {void}
     */
    _log(level, msg, meta = null) {
      if (this.logger && typeof this.logger[level] === 'function') {
        this.logger[level](msg, meta);
      }
    }

    /**
     * Kayitli favori seri kimliklerini (ID) dondurur.
     * @returns {Array<string>} Favori seri ID listesi.
     */
    getFavoriteIds() {
      if (!this.storage) {
        return [];
      }
      try {
        const raw = this.storage.getItem(this.favoritesKey);
        const parsed = raw ? JSON.parse(raw) : [];
        return Array.isArray(parsed) ? parsed : [];
      } catch (_err) {
        return [];
      }
    }

    /**
     * Belirtilen serinin favorilerde olup olmadigini kontrol eder.
     * @param {string} seriesId - Seri kimligi.
     * @returns {boolean} Favoride ise true.
     */
    isFavorite(seriesId) {
      if (!seriesId) {
        return false;
      }
      return this.getFavoriteIds().includes(seriesId);
    }

    /**
     * Seriyi favorilere ekler veya favorilerden cikarir.
     * @param {string} seriesId - Seri kimligi.
     * @returns {boolean} Islem sonrasi favori durumu (eklendiyse true, cikarildiysa false).
     */
    toggleFavorite(seriesId) {
      if (!seriesId) {
        return false;
      }
      const list = this.getFavoriteIds();
      const idx = list.indexOf(seriesId);
      let added = false;
      if (idx >= 0) {
        list.splice(idx, 1);
      } else {
        list.unshift(seriesId);
        added = true;
      }

      if (this.storage) {
        try {
          this.storage.setItem(this.favoritesKey, JSON.stringify(list));
        } catch (_err) {
          // Depolama hatasini yoksay
        }
      }
      this._log('info', added ? 'Seri kitapliga eklendi.' : 'Seri kitapliktan cikarildi.', {
        seriesId,
        totalFavorites: list.length
      });
      return added;
    }

    /**
     * Katalog icindeki favori serilerin tam nesne listesini dondurur.
     * @param {Object} catalog - CatalogController nesnesi.
     * @returns {Array<Object>} Favori seri nesneleri.
     */
    getFavoriteSeries(catalog) {
      if (!catalog || !Array.isArray(catalog.seriesList)) {
        return [];
      }
      const favIds = this.getFavoriteIds();
      return favIds
        .map((id) => catalog.getSeriesById(id))
        .filter((series) => Boolean(series));
    }

    /**
     * Tum serilerdeki bolumleri tarayarak en son yayinlanan bolumleri dondurur.
     * @param {Object} catalog - CatalogController nesnesi.
     * @param {number} [limit=8] - Maksimum bolum sayisi.
     * @returns {Array<Object>} Son eklenen bolum listesi.
     */
    getLatestChapters(catalog, limit = 8) {
      if (!catalog || !Array.isArray(catalog.seriesList)) {
        return [];
      }
      const items = [];
      catalog.seriesList.forEach((series) => {
        if (!Array.isArray(series.chapters)) {
          return;
        }
        series.chapters.forEach((ch) => {
          items.push({
            seriesId: series.id,
            seriesTitle: series.title,
            seriesCover: series.cover || '',
            seriesType: series.type || 'Seri',
            sourceLang: series.sourceLang || 'KR',
            chapterId: ch.id,
            number: Number(ch.number) || 0,
            title: ch.title || `Bölüm ${ch.number}`,
            date: ch.date || '',
            isNovel: Boolean(ch.isNovel)
          });
        });
      });

      items.sort((a, b) => {
        const dateCompare = String(b.date).localeCompare(String(a.date));
        if (dateCompare !== 0) {
          return dateCompare;
        }
        return b.number - a.number;
      });

      return items.slice(0, Math.max(1, limit));
    }

    /**
     * Kullanicinin okuma gecmisini katalog verileriyle zenginlestirerek en yeniden eskiye dondurur.
     * @param {Object} catalog - CatalogController nesnesi.
     * @param {Object} [readingEngine=null] - ReadingEngine nesnesi.
     * @returns {Array<Object>} Zenginlestirilmis gecmis listesi.
     */
    getRecentHistoryList(catalog, readingEngine = null) {
      if (!catalog) {
        return [];
      }
      let rawHistory = {};
      if (readingEngine && typeof readingEngine.getAllHistory === 'function') {
        rawHistory = readingEngine.getAllHistory();
      } else if (this.storage) {
        try {
          const raw = this.storage.getItem(this.historyKey);
          rawHistory = raw ? JSON.parse(raw) : {};
        } catch (_err) {
          rawHistory = {};
        }
      }

      const entries = Object.values(rawHistory || {});
      const enriched = entries
        .map((entry) => {
          const series = catalog.getSeriesById(entry.seriesId);
          if (!series || !Array.isArray(series.chapters)) {
            return null;
          }
          const chapter = series.chapters.find((c) => c.id === entry.chapterId);
          if (!chapter) {
            return null;
          }
          return {
            seriesId: series.id,
            seriesTitle: series.title,
            seriesCover: series.cover || '',
            seriesType: series.type || 'Seri',
            chapterId: chapter.id,
            chapterNumber: chapter.number,
            chapterTitle: chapter.title || `Bölüm ${chapter.number}`,
            pageIndex: Number(entry.pageIndex) || 0,
            updatedAt: entry.updatedAt || ''
          };
        })
        .filter(Boolean);

      enriched.sort((a, b) => String(b.updatedAt).localeCompare(String(a.updatedAt)));
      return enriched;
    }

    /**
     * Tum okuma gecmisini temizler.
     * @returns {void}
     */
    clearHistory() {
      if (this.storage) {
        try {
          this.storage.removeItem(this.historyKey);
        } catch (_err) {
          // Depolama hatasini yoksay
        }
      }
      this._log('info', 'Okuma gecmisi temizlendi.');
    }

    /**
     * Ana sayfadaki Son Eklenen Bolumler izgarasi icin HTML uretir.
     * @param {Object} catalog - CatalogController nesnesi.
     * @param {Function} computeUrlFn - URL hesaplama fonksiyonu.
     * @param {number} [limit=6] - Gosterilecek bolum sayisi.
     * @returns {string} HTML icerigi.
     */
    renderLatestChaptersHtml(catalog, computeUrlFn, limit = 6) {
      const latest = this.getLatestChapters(catalog, limit);
      if (latest.length === 0) {
        return '';
      }
      return latest
        .map((item) => {
          const chHref = computeUrlFn('reader', item.seriesId, item.chapterId);
          return `<a class="latest-chapter-card" href="${chHref}" data-action="read" data-series="${item.seriesId}" data-chapter="${item.chapterId}">
            <img class="latest-chapter-thumb" src="${item.seriesCover}" alt="${item.seriesTitle}" loading="lazy" />
            <div class="latest-chapter-info">
              <span class="latest-series-name">${item.seriesTitle}</span>
              <span class="latest-chapter-badge">Bölüm ${item.number}</span>
              <span class="latest-chapter-date">${item.date || 'Yeni'} • ${item.seriesType}</span>
            </div>
          </a>`;
        })
        .join('');
    }

    /**
     * Ana sayfadaki Kaldigin Yerden Devam Et seridi icin HTML uretir.
     * @param {Object} catalog - CatalogController nesnesi.
     * @param {Object} readingEngine - ReadingEngine nesnesi.
     * @param {Function} computeUrlFn - URL hesaplama fonksiyonu.
     * @returns {string} HTML icerigi.
     */
    renderContinueReadingHtml(catalog, readingEngine, computeUrlFn) {
      const historyList = this.getRecentHistoryList(catalog, readingEngine).slice(0, 4);
      if (historyList.length === 0) {
        return '';
      }
      return historyList
        .map((item) => {
          const readHref = computeUrlFn('reader', item.seriesId, item.chapterId);
          return `<a class="continue-card" href="${readHref}" data-action="read" data-series="${item.seriesId}" data-chapter="${item.chapterId}">
            <img class="continue-thumb" src="${item.seriesCover}" alt="${item.seriesTitle}" loading="lazy" />
            <div class="continue-info">
              <strong class="continue-title">${item.seriesTitle}</strong>
              <span class="continue-meta">Bölüm ${item.chapterNumber} • Sayfa ${item.pageIndex + 1}</span>
            </div>
            <span class="continue-play">${this._icon('play')}</span>
          </a>`;
        })
        .join('');
    }

    /**
     * Katalog veya Kitapligim gorunumu icin seri kartlari HTML dizgesini uretir.
     * @param {Array<Object>} seriesList - Gosterilecek seri dizisi.
     * @param {Object} catalog - CatalogController nesnesi.
     * @param {Function} computeUrlFn - URL hesaplama fonksiyonu.
     * @returns {string} Seri kartlari HTML icerigi.
     */
    renderSeriesCardListHtml(seriesList, catalog, computeUrlFn) {
      if (!Array.isArray(seriesList) || seriesList.length === 0) {
        return '';
      }
      return seriesList
        .map((series) => {
          const seriesHref = computeUrlFn('series', series.id);
          const isFav = this.isFavorite(series.id);
          const latestChapters = catalog
            ? catalog.getSortedChapters(series.id, 'desc').slice(0, 2)
            : [];
          const chaptersHtml =
            latestChapters.length > 0
              ? latestChapters
                  .map((ch) => {
                    const chHref = computeUrlFn('reader', series.id, ch.id);
                    return (
                      `<a class="chapter-mini-btn" href="${chHref}" data-action="read" data-series="${series.id}" data-chapter="${ch.id}">` +
                      `<span>Bölüm ${ch.number}</span><span>${ch.date}</span></a>`
                    );
                  })
                  .join('')
              : `<a class="chapter-mini-btn" href="${seriesHref}" data-action="detail" data-series="${series.id}"><span>Seri Sayfası</span><span>Detay</span></a>`;

          return `<article class="series-card">
            <div class="card-cover-wrap">
              <a href="${seriesHref}" data-action="detail" data-series="${series.id}" style="display:block;width:100%;height:100%;">
                <img class="card-cover" src="${series.cover}" alt="${series.title}" loading="lazy" />
              </a>
              <span class="lang-badge lang-${series.sourceLang}">${series.sourceLang}</span>
              <span class="type-badge">${series.type}</span>
              <button class="fav-card-btn ${isFav ? 'is-fav' : ''}" type="button" data-action="toggle-fav" data-series="${series.id}" title="${isFav ? 'Kitaplıktan Çıkar' : 'Kitaplığa Ekle'}">${isFav ? this._icon('heart-filled') : this._icon('heart')}</button>
            </div>
            <div class="card-body">
              <a class="card-title" href="${seriesHref}" data-action="detail" data-series="${series.id}">${series.title}</a>
              <div class="card-meta">
                <span>${this._icon('layers')} ${(series.chapters || []).length} Bölüm</span>
                <span>${series.status}</span>
              </div>
              <div class="card-chapters">${chaptersHtml}</div>
            </div>
          </article>`;
        })
        .join('');
    }

    /**
     * Okuma Gecmisim sayfasi (#view-history) icin liste HTML icerigini uretir.
     * @param {Object} catalog - CatalogController nesnesi.
     * @param {Object} readingEngine - ReadingEngine nesnesi.
     * @param {Function} computeUrlFn - URL hesaplama fonksiyonu.
     * @returns {string} Gecmis listesi HTML icerigi.
     */
    renderHistoryListHtml(catalog, readingEngine, computeUrlFn) {
      const list = this.getRecentHistoryList(catalog, readingEngine);
      if (list.length === 0) {
        return `<div class="disqus-status-note">Henüz okuma geçmişiniz bulunmuyor. Bir bölüm okuduğunuzda otomatik olarak burada listelenir.</div>`;
      }
      return list
        .map((item) => {
          const readHref = computeUrlFn('reader', item.seriesId, item.chapterId);
          return `<a class="continue-card" href="${readHref}" data-action="read" data-series="${item.seriesId}" data-chapter="${item.chapterId}">
            <img class="continue-thumb" src="${item.seriesCover}" alt="${item.seriesTitle}" loading="lazy" />
            <div class="continue-info">
              <strong class="continue-title">${item.seriesTitle}</strong>
              <span class="continue-meta">Bölüm ${item.chapterNumber}: ${item.chapterTitle} • Kaldığın Sayfa: ${item.pageIndex + 1}</span>
            </div>
            <span class="continue-play">${this._icon('play')} Devam Et</span>
          </a>`;
        })
        .join('');
    }

    /**
     * Seri detay kutusu (#series-detail-box) icin HTML icerigini uretir.
     * @param {Object} series - Seri nesnesi.
     * @param {Object} catalog - CatalogController nesnesi.
     * @param {Object|null} savedProgress - Kayitli ilerleme.
     * @param {Function} computeUrlFn - URL hesaplama fonksiyonu.
     * @returns {string} Seri detay HTML icerigi.
     */
    renderSeriesDetailHtml(series, catalog, savedProgress, computeUrlFn) {
      const SeriesPageClass =
        globalScope.SeriesPageController ||
        (typeof require === 'function' ? require('./series-page').SeriesPageController : null);
      if (SeriesPageClass) {
        const sp = new SeriesPageClass({ logger: this.logger });
        return sp.renderSeriesDetailHtml(series, catalog, this, savedProgress, computeUrlFn);
      }
      return '';
    }

    /**
     * Seri sayfasindaki bolum listesi (#chapter-list-grid) icin SeriesPageController uzerinden HTML uretir.
     * @param {string} seriesId - Seri kimligi.
     * @param {Array<Object>} chapters - Siralanmis bolumler.
     * @param {Object|null} savedProgress - Kayitli ilerleme.
     * @param {Function} computeUrlFn - URL hesaplama fonksiyonu.
     * @returns {string} Bolum listesi HTML icerigi.
     */
    renderChapterListHtml(seriesId, chapters, savedProgress, computeUrlFn) {
      const SeriesPageClass =
        globalScope.SeriesPageController ||
        (typeof require === 'function' ? require('./series-page').SeriesPageController : null);
      if (SeriesPageClass) {
        const sp = new SeriesPageClass({ logger: this.logger });
        return sp.renderChapterListHtml(seriesId, chapters, savedProgress, computeUrlFn);
      }
      return '';
    }
  }

  globalScope.UserLibrary = UserLibrary;

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = { UserLibrary };
  }
})(typeof window !== 'undefined' ? window : globalThis);

/* === MODULE: scripts/series-page.js === */
/**
 * @fileoverview Baştan tasarlanan Seri Bilgileri Sayfası (SeriesPageController) modülü.
 * Bulanık arka planlı seri vitrini, yapılandırılmış meta veri tablosu, temizlenmiş özet,
 * bölüm içi anlık arama/sıralama ve benzer seriler öneri şeridini yönetir.
 */

(function (globalScope) {
  'use strict';

  const iconFn =
    (globalScope.ManowaIcons && globalScope.ManowaIcons.get) ||
    (typeof require === 'function' ? require('./svg-icons').getSvgIcon : () => '');

  /**
   * Blogger şablonlarındaki yer tutucu özet ifadeleri.
   * @type {RegExp}
   */
  const PLACEHOLDER_SYNOPSIS_REGEX =
    /buraya serinin özet hikayesini|yepyeni tasarımla çok profesyonel|örnek özet metni/i;

  /**
   * Seri açıklaması için varsayılan maksimum karakter sınırı (~3 satır).
   * @type {number}
   */
  const DEFAULT_SYNOPSIS_MAX_LENGTH = 165;

  /**
   * Seri tanıtım sayfasını, bölüm arama/sıralama araçlarını ve benzer serileri yöneten sınıf.
   */
  class SeriesPageController {
    /**
     * SeriesPageController nesnesini başlatır.
     * @param {Object} [options={}] - Yapılandırma seçenekleri.
     * @param {Object} [options.logger=null] - Logger nesnesi.
     * @param {number} [options.synopsisMaxLength=165] - Özet kısaltma karakter sınırı.
     */
    constructor(options = {}) {
      this.logger = options.logger || globalScope.ManowaLogger || null;
      this.chapterSortOrder = options.chapterSortOrder || 'desc';
      this.chapterSearchQuery = '';
      this.activeSeriesId = '';
      this.synopsisMaxLength = options.synopsisMaxLength || DEFAULT_SYNOPSIS_MAX_LENGTH;
      this.activeSynopsisFull = '';
      this.activeSynopsisPreview = '';
      this.isSynopsisExpanded = false;
      this._log('debug', 'SeriesPageController baslatildi.');
    }

    /**
     * Vektörel SVG ikon üretici yardımcı metod.
     * @param {string} name - İkon adı.
     * @returns {string} SVG HTML dizgesi.
     */
    _icon(name) {
      const fn = (globalScope.ManowaIcons && globalScope.ManowaIcons.get) || iconFn;
      return typeof fn === 'function' ? fn(name) : '';
    }

    /**
     * İç loglama yardımcı metodu.
     * @param {'debug'|'info'|'warn'|'error'} level - Log seviyesi.
     * @param {string} msg - Log mesajı.
     * @param {Object|null} [meta=null] - Ek veri.
     * @returns {void}
     */
    _log(level, msg, meta = null) {
      if (this.logger && typeof this.logger[level] === 'function') {
        this.logger[level](msg, meta);
      }
    }

    /**
     * HTML öznitelikleri içinde kullanılacak metinleri güvenli şekilde kaçırır.
     * @param {string} text - Ham metin.
     * @returns {string} Kaçırılmış güvenli metin.
     */
    _escapeAttr(text) {
      return String(text || '')
        .replace(/&/g, '&amp;')
        .replace(/"/g, '&quot;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;');
    }

    /**
     * Seri özet metnini şablon yer tutucularından temizler.
     * @param {string} rawText - Ham özet metni.
     * @param {Object} series - Seri nesnesi.
     * @returns {string} Temizlenmiş özet metni.
     */
    cleanSynopsis(rawText, series = {}) {
      const text = String(rawText || '').trim();
      if (!text || PLACEHOLDER_SYNOPSIS_REGEX.test(text)) {
        const genres = Array.isArray(series.genres) ? series.genres.join(', ') : 'Genel';
        const count = Array.isArray(series.chapters) ? series.chapters.length : 0;
        return `${series.title || 'Bu seri'}, ${genres} kategorilerinde yer alan güncel bir ${series.type || 'Manhwa'} eseridir. Arşivimizde şu an ${count} Türkçe çeviri bölümü mevcuttur.`;
      }
      return text;
    }

    /**
     * Seri özetini uzunluk sınırına göre kontrol eder ve gerekirse kelime bütünlüğünü koruyarak kısaltır.
     * @param {string} rawText - Ham özet metni.
     * @param {Object} [series={}] - Seri nesnesi.
     * @param {number} [maxLength=this.synopsisMaxLength] - Maksimum karakter sınırı.
     * @returns {{ isLong: boolean, previewText: string, fullText: string }} Özet önizleme bilgisi.
     */
    formatSynopsisPreview(rawText, series = {}, maxLength = this.synopsisMaxLength) {
      const fullText = this.cleanSynopsis(rawText, series);
      const limit = Number(maxLength) > 0 ? Number(maxLength) : DEFAULT_SYNOPSIS_MAX_LENGTH;
      if (fullText.length <= limit) {
        return {
          isLong: false,
          previewText: fullText,
          fullText
        };
      }
      const sliced = fullText.slice(0, limit);
      const lastSpace = sliced.lastIndexOf(' ');
      const cutIndex = lastSpace > Math.floor(limit * 0.65) ? lastSpace : limit;
      const cleanCut = sliced.slice(0, cutIndex).replace(/[.,;:\-\s]+$/, '');
      return {
        isLong: true,
        previewText: `${cleanCut}...`,
        fullText
      };
    }

    /**
     * Uzun seri özetinin daraltılmış ("Devamını Oku") ve genişletilmiş ("Daha Az Göster") durumunu değiştirir.
     * @param {Element|null} [cardEl=null] - Özet kartı DOM düğümü.
     * @param {Element|null} [btnEl=null] - Tıklanan düğme DOM düğümü.
     * @returns {boolean} Yeni genişletilmişlik durumu (true: açık, false: daraltılmış).
     */
    toggleSynopsis(cardEl = null, btnEl = null) {
      const textEl =
        (cardEl && typeof cardEl.querySelector === 'function'
          ? cardEl.querySelector('#series-synopsis-text, .detail-synopsis')
          : null) ||
        (typeof document !== 'undefined' ? document.getElementById('series-synopsis-text') : null);
      const toggleBtn =
        btnEl ||
        (cardEl && typeof cardEl.querySelector === 'function'
          ? cardEl.querySelector('#btn-toggle-synopsis, .series-synopsis-toggle')
          : null) ||
        (typeof document !== 'undefined' ? document.getElementById('btn-toggle-synopsis') : null);

      const currentExpanded =
        toggleBtn && typeof toggleBtn.getAttribute === 'function'
          ? toggleBtn.getAttribute('aria-expanded') === 'true'
          : Boolean(this.isSynopsisExpanded);
      const nextExpanded = !currentExpanded;
      this.isSynopsisExpanded = nextExpanded;

      if (textEl) {
        const fullText =
          (typeof textEl.getAttribute === 'function' && textEl.getAttribute('data-full-text')) ||
          this.activeSynopsisFull ||
          textEl.textContent;
        const shortText =
          (typeof textEl.getAttribute === 'function' && textEl.getAttribute('data-short-text')) ||
          this.activeSynopsisPreview ||
          textEl.textContent;
        textEl.textContent = nextExpanded ? fullText : shortText;
        if (textEl.classList) {
          textEl.classList.toggle('is-collapsed', !nextExpanded);
          textEl.classList.toggle('is-expanded', nextExpanded);
        }
      }

      if (toggleBtn) {
        if (typeof toggleBtn.setAttribute === 'function') {
          toggleBtn.setAttribute('aria-expanded', nextExpanded ? 'true' : 'false');
        }
        toggleBtn.textContent = nextExpanded ? 'Daha Az Göster' : 'Devamını Oku';
      }

      this._log('debug', 'Seri ozeti gorunumu degistirildi.', {
        seriesId: this.activeSeriesId,
        expanded: nextExpanded
      });
      return nextExpanded;
    }

    /**
     * Okuma motoru kodunu kullanıcı dostu Türkçe etikete dönüştürür.
     * @param {string} mode - Motor kodu ('webtoon', 'single', 'double', 'novel').
     * @returns {string} Türkçe motor adı.
     */
    formatReaderModeLabel(mode) {
      const m = String(mode || 'webtoon').toLowerCase();
      if (m === 'single') return 'Tek Sayfa (Manga)';
      if (m === 'double') return 'Çift Sayfa (Kitap)';
      if (m === 'novel') return 'Novel (Metin Modu)';
      return 'Webtoon (Dikey Şerit)';
    }

    /**
     * Kaynak dil kodunu tam açıklamaya dönüştürür.
     * @param {string} langCode - Dil kodu ('KR', 'JP', 'CN', 'EN').
     * @returns {string} Açıklamalı dil metni.
     */
    formatSourceLangLabel(langCode) {
      const code = String(langCode || 'KR').toUpperCase();
      const map = {
        KR: 'Korece (KR)',
        JP: 'Japonca (JP)',
        CN: 'Çince (CN)',
        EN: 'İngilizce (EN)'
      };
      return map[code] || code;
    }

    /**
     * Bölüm arama sorgusunu günceller.
     * @param {string} query - Arama metni veya bölüm numarası.
     * @returns {void}
     */
    setChapterSearchQuery(query) {
      this.chapterSearchQuery = String(query || '').trim();
      this._log('debug', 'Bolum arama sorgusu guncellendi.', {
        seriesId: this.activeSeriesId,
        query: this.chapterSearchQuery
      });
    }

    /**
     * Bölüm sıralama yönünü değiştirir ('desc' <-> 'asc').
     * @returns {'desc'|'asc'} Yeni sıralama yönü.
     */
    toggleSortOrder() {
      this.chapterSortOrder = this.chapterSortOrder === 'desc' ? 'asc' : 'desc';
      this._log('info', 'Bolum siralama yonu degistirildi.', {
        order: this.chapterSortOrder
      });
      return this.chapterSortOrder;
    }

    /**
     * Aktif serinin bölümlerini sıralanmış ve arama sorgusuna göre filtrelenmiş olarak döndürür.
     * @param {Object} catalog - CatalogController nesnesi.
     * @param {string} seriesId - Seri kimliği.
     * @returns {Array<Object>} Filtrelenmiş bölüm listesi.
     */
    getFilteredChapters(catalog, seriesId) {
      if (!catalog || !seriesId) {
        return [];
      }
      const sorted = catalog.getSortedChapters(seriesId, this.chapterSortOrder);
      if (!this.chapterSearchQuery) {
        return sorted;
      }
      const q = this.chapterSearchQuery.toLowerCase();
      return sorted.filter((ch) => {
        const numMatch = String(ch.number || '').toLowerCase().includes(q);
        const titleMatch = String(ch.title || '').toLowerCase().includes(q);
        return numMatch || titleMatch;
      });
    }

    /**
     * Seçilen seriye tür ve kategori bakımından en yakın benzer serileri döndürür.
     * @param {Object} catalog - CatalogController nesnesi.
     * @param {Object} currentSeries - Aktif seri nesnesi.
     * @param {number} [limit=4] - Maksimum öneri sayısı.
     * @returns {Array<Object>} Benzer seri listesi.
     */
    getRelatedSeries(catalog, currentSeries, limit = 4) {
      if (!catalog || !Array.isArray(catalog.seriesList) || !currentSeries) {
        return [];
      }
      const targetGenres = new Set(
        (currentSeries.genres || []).map((g) => String(g).toLowerCase())
      );
      const candidates = catalog.seriesList
        .filter((s) => s.id !== currentSeries.id)
        .map((s) => {
          let score = 0;
          if (s.type === currentSeries.type) score += 2;
          (s.genres || []).forEach((g) => {
            if (targetGenres.has(String(g).toLowerCase())) score += 3;
          });
          score += Math.min(2, (s.chapters || []).length * 0.1);
          return { series: s, score };
        });

      candidates.sort((a, b) => b.score - a.score);
      return candidates.slice(0, Math.max(1, limit)).map((item) => item.series);
    }

    /**
     * Seri detay vitrin ve bilgi kartı (#series-detail-box) için HTML üretir.
     * @param {Object} series - Seri nesnesi.
     * @param {Object} catalog - CatalogController nesnesi.
     * @param {Object|null} library - UserLibrary nesnesi.
     * @param {Object|null} savedProgress - Kullanıcının bu serideki kayıtlı okuma ilerlemesi.
     * @param {Function} computeUrlFn - URL hesaplama fonksiyonu.
     * @returns {string} Seri detay HTML içeriği.
     */
    renderSeriesDetailHtml(series, catalog, library, savedProgress, computeUrlFn) {
      if (!series) {
        return '';
      }
      const isFav =
        library && typeof library.isFavorite === 'function'
          ? library.isFavorite(series.id)
          : false;
      const sortedAsc = catalog ? catalog.getSortedChapters(series.id, 'asc') : [];
      const totalChapters = sortedAsc.length;
      const firstChapter = sortedAsc[0] || null;
      const latestChapter = sortedAsc[totalChapters - 1] || null;

      const resumeChapterObj =
        savedProgress && savedProgress.chapterId
          ? sortedAsc.find((c) => c.id === savedProgress.chapterId) || firstChapter
          : null;

      const firstHref = firstChapter ? computeUrlFn('reader', series.id, firstChapter.id) : '#';
      const latestHref = latestChapter ? computeUrlFn('reader', series.id, latestChapter.id) : '#';
      const resumeHref = resumeChapterObj
        ? computeUrlFn('reader', series.id, resumeChapterObj.id)
        : '#';

      const genresHtml = (series.genres || [])
        .map(
          (g) =>
            `<button class="series-genre-pill" type="button" data-series-genre="${g}" title="${g} kategorisindeki serileri filtrele">${this._icon('tag')} ${g}</button>`
        )
        .join('');

      const synopsisInfo = this.formatSynopsisPreview(series.synopsis, series);
      this.activeSynopsisFull = synopsisInfo.fullText;
      this.activeSynopsisPreview = synopsisInfo.previewText;
      this.isSynopsisExpanded = false;
      const latestDate =
        latestChapter && latestChapter.date
          ? latestChapter.date
          : series.publishedDate || 'Güncel';
      const authorText = series.author || 'Bilinmiyor';
      const artistText = series.artist || 'Bilinmiyor';
      const translatorText = series.translator || 'Bilinmiyor';
      const editorText = series.editor || 'Bilinmiyor';
      const rawAlt = String(series.altTitle || '').trim();
      const altTitleText = /isteğe bağlı|alternatif isimler/.test(
        rawAlt.toLocaleLowerCase('tr-TR')
      )
        ? ''
        : rawAlt;

      return `<div class="series-hero-card">
        <div class="series-backdrop" style="background-image: url('${series.cover || ''}');"></div>
        <div class="series-backdrop-overlay"></div>

        <div class="series-detail-header">
          <div class="series-poster-col">
            <div class="series-poster-frame">
              <img class="detail-cover" src="${series.cover}" alt="${series.title}" />
            </div>
            <div class="series-poster-quick-actions">
              <button class="icon-btn series-fav-btn ${isFav ? 'is-fav' : ''}" type="button" data-action="toggle-fav" data-series="${series.id}">
                ${isFav ? `${this._icon('heart-filled')} Kitaplığımda` : `${this._icon('heart')} Kitaplığa Ekle`}
              </button>
              <button class="icon-btn series-share-btn" id="btn-copy-series-url" type="button" title="Seri Bağlantısını Kopyala">
                ${this._icon('link')} Paylaş
              </button>
            </div>
          </div>

          <div class="series-info-col detail-info">
            <h1 class="series-main-title">${series.title}</h1>
            ${altTitleText ? `<div class="detail-alt-title">${altTitleText}</div>` : ''}

            <div class="series-genre-list detail-badges">
              ${genresHtml}
            </div>

            <div class="series-synopsis-card">
              <div class="series-synopsis-title">${this._icon('book')} Seri Özeti</div>
              <p class="detail-synopsis ${synopsisInfo.isLong ? 'is-collapsed' : ''}" id="series-synopsis-text" data-full-text="${this._escapeAttr(synopsisInfo.fullText)}" data-short-text="${this._escapeAttr(synopsisInfo.previewText)}">${synopsisInfo.previewText}</p>
              ${
                synopsisInfo.isLong
                  ? `<button class="series-synopsis-toggle" id="btn-toggle-synopsis" type="button" aria-expanded="false">Devamını Oku</button>`
                  : ''
              }
            </div>

            <div class="detail-actions series-cta-bar">
              ${
                firstChapter
                  ? `<a class="primary-btn series-cta-btn" href="${firstHref}" data-action="read" data-series="${series.id}" data-chapter="${firstChapter.id}">${this._icon('play')} İlk Bölümü Oku (Bölüm ${firstChapter.number})</a>`
                  : ''
              }
              ${
                latestChapter && latestChapter.id !== (firstChapter && firstChapter.id)
                  ? `<a class="icon-btn series-cta-secondary" href="${latestHref}" data-action="read" data-series="${series.id}" data-chapter="${latestChapter.id}">${this._icon('flame')} Son Bölüm (Bölüm ${latestChapter.number})</a>`
                  : ''
              }
              ${
                resumeChapterObj && savedProgress
                  ? `<a class="icon-btn series-cta-resume" href="${resumeHref}" data-action="read" data-series="${series.id}" data-chapter="${resumeChapterObj.id}">${this._icon('clock')} Devam Et: Bölüm ${resumeChapterObj.number} (Sayfa ${Number(savedProgress.pageIndex || 0) + 1})</a>`
                  : ''
              }
            </div>
          </div>

          <aside class="series-meta-col" aria-label="Seri Bilgi Izgarası">
            <div class="series-meta-grid">
              <div class="series-meta-card">
                <span class="series-meta-label">${this._icon('layers')} Toplam Bölüm</span>
                <strong class="series-meta-value">${totalChapters} Bölüm</strong>
              </div>
              <div class="series-meta-card">
                <span class="series-meta-label">${this._icon('sparkles')} Durum</span>
                <strong class="series-meta-value">${series.status || 'Devam Ediyor'}</strong>
              </div>
              <div class="series-meta-card">
                <span class="series-meta-label">${this._icon('user')} Yazar</span>
                <strong class="series-meta-value">${authorText}</strong>
              </div>
              <div class="series-meta-card">
                <span class="series-meta-label">${this._icon('pen')} Çizer</span>
                <strong class="series-meta-value">${artistText}</strong>
              </div>
              <div class="series-meta-card">
                <span class="series-meta-label">${this._icon('globe')} Çevirmen</span>
                <strong class="series-meta-value">${translatorText}</strong>
              </div>
              <div class="series-meta-card">
                <span class="series-meta-label">${this._icon('wrench')} Editör</span>
                <strong class="series-meta-value">${editorText}</strong>
              </div>
              <div class="series-meta-card">
                <span class="series-meta-label">${this._icon('clock')} Son Güncelleme</span>
                <strong class="series-meta-value">${latestDate}</strong>
              </div>
              <div class="series-meta-card">
                <span class="series-meta-label">${this._icon('award')} Arşiv Puanı</span>
                <strong class="series-meta-value">${series.rating || '9.6'} / 10</strong>
              </div>
            </div>
          </aside>
        </div>
      </div>`;
    }

    /**
     * Bölüm yayın tarihini 1 aya (30 güne) kadar göreceli ("Bugün", "X gün önce", "1 ay önce"),
     * 30 günden eski ise normal tarih ("YYYY-AA-GG") formatında döndürür.
     * @param {string} dateStr - Bölüm tarihi ('YYYY-MM-DD' veya ISO dizgesi).
     * @param {Date|string} [nowDate=new Date()] - Referans güncel tarih.
     * @returns {string} Formatlanmış tarih metni.
     */
    formatRelativeChapterDate(dateStr, nowDate = new Date()) {
      const raw = String(dateStr || '').trim();
      if (!raw) {
        return 'Güncel';
      }
      const parseToUtcMidnight = (val) => {
        if (val instanceof Date && !Number.isNaN(val.getTime())) {
          return Date.UTC(val.getFullYear(), val.getMonth(), val.getDate());
        }
        const str = String(val || '').trim();
        const ymd = str.match(/^(\d{4})-(\d{2})-(\d{2})/);
        if (ymd) {
          return Date.UTC(Number(ymd[1]), Number(ymd[2]) - 1, Number(ymd[3]));
        }
        const parsed = new Date(str);
        if (!Number.isNaN(parsed.getTime())) {
          return Date.UTC(parsed.getFullYear(), parsed.getMonth(), parsed.getDate());
        }
        return NaN;
      };

      const targetUtc = parseToUtcMidnight(raw);
      const nowUtc = parseToUtcMidnight(nowDate);
      if (Number.isNaN(targetUtc) || Number.isNaN(nowUtc)) {
        return raw;
      }
      const diffDays = Math.floor((nowUtc - targetUtc) / 86400000);
      if (diffDays <= 0) {
        return 'Bugün';
      }
      if (diffDays < 30) {
        return `${diffDays} gün önce`;
      }
      if (diffDays === 30) {
        return '1 ay önce';
      }
      return raw.slice(0, 10);
    }

    /**
     * Bölüm listesi ızgarası (#chapter-list-grid) için kompakt kutu ve göreceli tarihli HTML üretir.
     * @param {string} seriesId - Seri kimliği.
     * @param {Array<Object>} chapters - Sıralanmış/filtrelenmiş bölüm listesi.
     * @param {Object|null} savedProgress - Kullanıcının kayıtlı ilerlemesi.
     * @param {Function} computeUrlFn - URL hesaplama fonksiyonu.
     * @param {Date|string} [nowDate=new Date()] - Göreceli tarih hesabı için referans tarih.
     * @returns {string} Bölüm listesi HTML içeriği.
     */
    renderChapterListHtml(seriesId, chapters, savedProgress, computeUrlFn, nowDate = new Date()) {
      if (!Array.isArray(chapters) || chapters.length === 0) {
        if (this.chapterSearchQuery) {
          return `<div class="disqus-status-note">"${this.chapterSearchQuery}" aramasıyla eşleşen bölüm bulunamadı.</div>`;
        }
        return `<div class="disqus-status-note">Bu seri için henüz bölüm eklenmemiş.</div>`;
      }
      return chapters
        .map((ch) => {
          const isRead = Boolean(savedProgress && savedProgress.chapterId === ch.id);
          const chHref = computeUrlFn('reader', seriesId, ch.id);
          const relDate = this.formatRelativeChapterDate(ch.date, nowDate);
          return `<a class="chapter-item-btn chapter-card-item chapter-compact-box ${isRead ? 'is-read' : ''}" href="${chHref}" data-action="read" data-series="${seriesId}" data-chapter="${ch.id}" title="Bölüm ${ch.number} (${ch.date || 'Güncel'})">
            <div class="chapter-box-top">
              <strong class="chapter-title-text">Bölüm ${ch.number}</strong>
              ${
                isRead
                  ? `<span class="chapter-read-badge" title="Son Okunan" aria-label="Son Okunan">${this._icon('check')}</span>`
                  : ''
              }
            </div>
            <div class="chapter-box-bottom">
              <span class="chapter-sub-meta">${relDate}</span>
              <span class="chapter-open-pill">Oku</span>
            </div>
          </a>`;
        })
        .join('');
    }

    /**
     * Benzer / Önerilen seriler şeridi (#series-related-grid) için HTML üretir.
     * @param {Object} catalog - CatalogController nesnesi.
     * @param {Object} currentSeries - Aktif seri nesnesi.
     * @param {Function} computeUrlFn - URL hesaplama fonksiyonu.
     * @returns {string} Benzer seriler HTML içeriği.
     */
    renderRelatedSeriesHtml(catalog, currentSeries, computeUrlFn) {
      const related = this.getRelatedSeries(catalog, currentSeries, 4);
      if (related.length === 0) {
        return '';
      }
      return related
        .map((s) => {
          const href = computeUrlFn('series', s.id);
          const chCount = (s.chapters || []).length;
          return `<a class="series-related-card" href="${href}" data-action="detail" data-series="${s.id}">
            <img class="series-related-thumb" src="${s.cover}" alt="${s.title}" loading="lazy" />
            <div class="series-related-info">
              <span class="series-related-type">${s.type || 'Manhwa'} • ${s.sourceLang || 'KR'}</span>
              <strong class="series-related-title">${s.title}</strong>
              <span class="series-related-meta">${this._icon('layers')} ${chCount} Bölüm • ${s.status || 'Devam Ediyor'}</span>
            </div>
          </a>`;
        })
        .join('');
    }

    /**
     * Seri sayfasının tüm DOM bileşenlerini günceller.
     * @param {Object} series - Aktif seri nesnesi.
     * @param {Object} catalog - CatalogController nesnesi.
     * @param {Object|null} library - UserLibrary nesnesi.
     * @param {Object|null} readingEngine - ReadingEngine nesnesi.
     * @param {Function} computeUrlFn - URL hesaplama fonksiyonu.
     * @returns {void}
     */
    renderIntoDom(series, catalog, library, readingEngine, computeUrlFn) {
      if (typeof document === 'undefined' || !series) {
        return;
      }
      if (this.activeSeriesId !== series.id) {
        this.activeSeriesId = series.id;
        this.chapterSearchQuery = '';
        const searchInp = document.getElementById('input-chapter-search');
        if (searchInp) searchInp.value = '';
      }

      const breadcrumbTitle = document.getElementById('series-breadcrumb-title');
      if (breadcrumbTitle) breadcrumbTitle.textContent = series.title;

      const savedProgress =
        readingEngine && typeof readingEngine.getProgress === 'function'
          ? readingEngine.getProgress(series.id)
          : null;

      const detailBox = document.getElementById('series-detail-box');
      if (detailBox) {
        detailBox.innerHTML = this.renderSeriesDetailHtml(
          series,
          catalog,
          library,
          savedProgress,
          computeUrlFn
        );
      }

      this.renderChaptersIntoDom(catalog, readingEngine, computeUrlFn);

      const relatedSec = document.getElementById('series-related-section');
      const relatedGrid = document.getElementById('series-related-grid');
      if (relatedSec && relatedGrid) {
        const relHtml = this.renderRelatedSeriesHtml(catalog, series, computeUrlFn);
        relatedGrid.innerHTML = relHtml;
        relatedSec.classList.toggle('hidden', !relHtml);
      }
    }

    /**
     * Yalnızca bölüm listesi ızgarasını ve bölüm sayacı etiketini DOM üzerinde günceller.
     * @param {Object} catalog - CatalogController nesnesi.
     * @param {Object|null} readingEngine - ReadingEngine nesnesi.
     * @param {Function} computeUrlFn - URL hesaplama fonksiyonu.
     * @returns {void}
     */
    renderChaptersIntoDom(catalog, readingEngine, computeUrlFn) {
      if (typeof document === 'undefined' || !this.activeSeriesId || !catalog) {
        return;
      }
      const listGrid = document.getElementById('chapter-list-grid');
      const countBadge = document.getElementById('series-chapter-count');
      const sortBtn = document.getElementById('btn-sort-chapters');
      const filtered = this.getFilteredChapters(catalog, this.activeSeriesId);
      const total = (catalog.getSortedChapters(this.activeSeriesId, 'asc') || []).length;

      if (countBadge) {
        countBadge.textContent =
          this.chapterSearchQuery && filtered.length !== total
            ? `${filtered.length} / ${total} Bölüm`
            : `${total} Bölüm`;
      }
      if (sortBtn) {
        sortBtn.innerHTML =
          this.chapterSortOrder === 'desc'
            ? `${this._icon('sort')} <span class="btn-label">Sıralama: Yeni → Eski</span>`
            : `${this._icon('sort')} <span class="btn-label">Sıralama: Eski → Yeni</span>`;
      }
      if (listGrid) {
        const saved =
          readingEngine && typeof readingEngine.getProgress === 'function'
            ? readingEngine.getProgress(this.activeSeriesId)
            : null;
        listGrid.innerHTML = this.renderChapterListHtml(
          this.activeSeriesId,
          filtered,
          saved,
          computeUrlFn
        );
      }
    }

    /**
     * Seri sayfası üzerindeki bölüm arama, sıralama, kategori seçimi ve bağlantı paylaşım olaylarını bağlar.
     * @param {Object} [callbacks={}] - Geri çağırım fonksiyonları.
     * @param {Function} [callbacks.onChapterUpdate] - Bölüm listesi değiştiğinde çağrılır.
     * @param {Function} [callbacks.onGenreSelect] - Seri üzerindeki kategori etiketine tıklandığında çağrılır.
     * @returns {void}
     */
    bindDomEvents(callbacks = {}) {
      if (typeof document === 'undefined') {
        return;
      }
      const searchInp = document.getElementById('input-chapter-search');
      if (searchInp) {
        searchInp.addEventListener('input', (e) => {
          this.setChapterSearchQuery(e.target.value);
          if (typeof callbacks.onChapterUpdate === 'function') {
            callbacks.onChapterUpdate();
          }
        });
      }

      const sortBtn = document.getElementById('btn-sort-chapters');
      if (sortBtn) {
        sortBtn.addEventListener('click', () => {
          this.toggleSortOrder();
          if (typeof callbacks.onChapterUpdate === 'function') {
            callbacks.onChapterUpdate();
          }
        });
      }

      const viewSeries = document.getElementById('view-series');
      if (viewSeries) {
        viewSeries.addEventListener('click', (e) => {
          const synopsisBtn = e.target.closest('#btn-toggle-synopsis, .series-synopsis-toggle');
          if (synopsisBtn) {
            e.preventDefault();
            const cardEl = synopsisBtn.closest('.series-synopsis-card');
            this.toggleSynopsis(cardEl, synopsisBtn);
            return;
          }

          const genreBtn = e.target.closest('[data-series-genre]');
          if (genreBtn) {
            e.preventDefault();
            const genre = genreBtn.getAttribute('data-series-genre');
            if (genre && typeof callbacks.onGenreSelect === 'function') {
              callbacks.onGenreSelect(genre);
            }
            return;
          }

          const copyBtn = e.target.closest('#btn-copy-series-url');
          if (copyBtn) {
            e.preventDefault();
            const shareUrl =
              typeof globalScope.location !== 'undefined' ? globalScope.location.href : '';
            if (shareUrl && typeof navigator !== 'undefined' && navigator.clipboard) {
              navigator.clipboard.writeText(shareUrl);
            }
            copyBtn.innerHTML = `${this._icon('check')} Kopyalandı`;
            this._log('info', 'Seri baglantisi panoya kopyalandi.', { url: shareUrl });
          }
        });
      }
    }
  }

  globalScope.SeriesPageController = SeriesPageController;

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = { SeriesPageController };
  }
})(typeof window !== 'undefined' ? window : globalThis);

/* === MODULE: scripts/hero-slider.js === */
/**
 * @fileoverview Minimalist ana sayfa vitrin kaydiricisi (HeroSlider) modulu.
 * Sadece arka plan, baslik, tek buton, kenar gecis oklari ve sade nokta gostergeleri sunar.
 */

(function (globalScope) {
  'use strict';

  /**
   * Ana sayfa vitrin kaydiricisini (Hero Slider) yoneten sinif.
   */
  class HeroSlider {
    /**
     * HeroSlider nesnesini yapilandirir.
     * @param {Object} [options={}] - Kaydirici secenekleri.
     * @param {Object} [options.logger] - Istemci loglayici nesnesi.
     * @param {number} [options.maxSlides=6] - Vitrinde gosterilecek maksimum seri sayisi.
     * @param {number} [options.autoPlayMs=6000] - Otomatik gecis suresi (ms). 0 ise kapali.
     */
    constructor(options = {}) {
      this.logger = options.logger || globalScope.ManowaLogger || null;
      this.maxSlides = typeof options.maxSlides === 'number' ? options.maxSlides : 6;
      this.autoPlayMs = typeof options.autoPlayMs === 'number' ? options.autoPlayMs : 6000;
      this.slides = [];
      this.currentIndex = 0;
      this.isPaused = false;
      this.timerId = null;
      this.touchStartX = null;

      this._log('debug', 'Minimalist HeroSlider baslatildi.', {
        maxSlides: this.maxSlides,
        autoPlayMs: this.autoPlayMs
      });
    }

    /**
     * Ic loglama yardimcisi.
     * @param {'debug'|'info'|'warn'|'error'} level - Log seviyesi.
     * @param {string} msg - Log mesaji.
     * @param {Object} [meta={}] - Ek veri.
     * @returns {void}
     */
    _log(level, msg, meta = {}) {
      if (this.logger && typeof this.logger[level] === 'function') {
        this.logger[level](msg, meta);
      }
    }

    /**
     * Sablondan kalan yer tutucu ozet metinlerini temizler.
     * @param {string} rawSynopsis - Ham ozet metni.
     * @param {Object} [series={}] - Seri nesnesi.
     * @returns {string} Temizlenmis ozet metni.
     */
    cleanSynopsis(rawSynopsis, series = {}) {
      const text = String(rawSynopsis || '').trim();
      const isPlaceholder =
        !text ||
        /buraya serinin özet hikayesini|yepyeni tasarımla çok profesyonel|serisi tüm bölümleriyle arşivimizde/i.test(
          text
        );
      if (!isPlaceholder) {
        return text;
      }
      const typeLabel = series.type || 'Manhwa';
      const statusLabel = series.status || 'Devam Ediyor';
      const chapterCount = Array.isArray(series.chapters) ? series.chapters.length : 0;
      const genresText =
        Array.isArray(series.genres) && series.genres.length > 0
          ? `${series.genres.slice(0, 3).join(', ')} kategorilerinde `
          : '';
      return `${series.title || 'Seri'} (${typeLabel}) — ${genresText}${statusLabel.toLowerCase()} durumunda, ${chapterCount} Türkçe çeviri bölümüyle arşivde.`;
    }

    /**
     * Katalogdan one cikan serileri secerek slayt listesini gunceller.
     * @param {Object} catalog - CatalogController nesnesi.
     * @returns {Array<Object>} Secilen slayt dizisi.
     */
    setSlidesFromCatalog(catalog) {
      if (!catalog || !Array.isArray(catalog.seriesList)) {
        this.slides = [];
        this.currentIndex = 0;
        return this.slides;
      }

      const all = catalog.seriesList.slice();
      const withChapters = all.filter((s) => Array.isArray(s.chapters) && s.chapters.length > 0);
      const withoutChapters = all.filter((s) => !Array.isArray(s.chapters) || s.chapters.length === 0);

      this.slides = [...withChapters, ...withoutChapters].slice(0, this.maxSlides);
      if (this.currentIndex >= this.slides.length) {
        this.currentIndex = 0;
      }

      this._log('debug', 'HeroSlider slayt listesi guncellendi.', {
        slideCount: this.slides.length
      });
      return this.slides;
    }

    /**
     * Aktif slayt nesnesini dondurur.
     * @returns {Object|null} Aktif seri nesnesi veya null.
     */
    getCurrentSlide() {
      if (this.slides.length === 0) {
        return null;
      }
      return this.slides[this.currentIndex] || this.slides[0];
    }

    /**
     * Belirtilen indeksteki slayta gecis yapar (dairesel sarma destekli).
     * @param {number} targetIndex - Hedef slayt indeksi.
     * @returns {Object|null} Yeni aktif slayt nesnesi.
     */
    goToSlide(targetIndex) {
      const len = this.slides.length;
      if (len === 0) {
        this.currentIndex = 0;
        return null;
      }
      const normalized = ((Number(targetIndex) % len) + len) % len;
      this.currentIndex = normalized;
      const active = this.slides[this.currentIndex];
      this._log('debug', 'HeroSlider slayt degisti.', {
        currentIndex: this.currentIndex,
        seriesId: active ? active.id : ''
      });
      return active;
    }

    /**
     * Bir sonraki slayta gecer.
     * @returns {Object|null} Yeni aktif slayt nesnesi.
     */
    nextSlide() {
      return this.goToSlide(this.currentIndex + 1);
    }

    /**
     * Bir onceki slayta gecer.
     * @returns {Object|null} Yeni aktif slayt nesnesi.
     */
    prevSlide() {
      return this.goToSlide(this.currentIndex - 1);
    }

    /**
     * Fare uzerine geldiginde veya ayrildiginda duraklatma durumunu degistirir.
     * @param {boolean} paused - Duraklatildi mi?
     * @returns {void}
     */
    setPaused(paused) {
      this.isPaused = Boolean(paused);
    }

    /**
     * Dokunmatik ekranda kaydirma hareketini (swipe) degerlendirir.
     * @param {number} startX - Dokunma baslangic X koordinati.
     * @param {number} endX - Dokunma bitis X koordinati.
     * @param {number} [threshold=45] - Minimum piksel esigi.
     * @returns {'next'|'prev'|'none'} Tetiklenen hareket yonu.
     */
    handleTouchGesture(startX, endX, threshold = 45) {
      const diff = Number(endX) - Number(startX);
      if (Math.abs(diff) < threshold) {
        return 'none';
      }
      if (diff < 0) {
        this.nextSlide();
        return 'next';
      }
      this.prevSlide();
      return 'prev';
    }

    /**
     * Otomatik slayt gecis zamanlayicisini baslatir.
     * @param {Function} [onTick] - Her geciste cagrilacak geri bildirim fonksiyonu.
     * @returns {void}
     */
    startAutoPlay(onTick) {
      this.stopAutoPlay();
      if (this.autoPlayMs <= 0 || this.slides.length <= 1) {
        return;
      }
      this.timerId = setInterval(() => {
        if (this.isPaused || this.slides.length <= 1) {
          return;
        }
        this.nextSlide();
        if (typeof onTick === 'function') {
          onTick(this.getCurrentSlide(), this.currentIndex);
        }
      }, this.autoPlayMs);
    }

    /**
     * Otomatik slayt gecis zamanlayicisini durdurur.
     * @returns {void}
     */
    stopAutoPlay() {
      if (this.timerId !== null) {
        clearInterval(this.timerId);
        this.timerId = null;
      }
    }

    /**
     * Aktif slayt icin HTML kodunu uretir (arka plan, baslik, baslik alti seri ayrintilari, butonlar ve noktalar).
     * @param {Object} catalog - CatalogController nesnesi.
     * @param {Object} [_library=null] - UserLibrary nesnesi (arayuz uyumu icin).
     * @param {Function} [urlBuilder=null] - URL olusturucu fonksiyon.
     * @returns {string} Uretilen HTML dizgesi.
     */
    buildSliderHtml(catalog, _library = null, urlBuilder = null) {
      const featured = this.getCurrentSlide();
      if (!featured) {
        return '';
      }

      const resolveUrl = typeof urlBuilder === 'function' ? urlBuilder : () => '#';
      const sortedAsc = catalog ? catalog.getSortedChapters(featured.id, 'asc') : [];
      const firstChapter = sortedAsc[0] || null;
      const chapterCount = Array.isArray(featured.chapters) ? featured.chapters.length : 0;

      const detailHref = resolveUrl('series', featured.id);
      const firstReadHref = firstChapter
        ? resolveUrl('reader', featured.id, firstChapter.id)
        : detailHref;
      const firstReadAction = firstChapter ? 'read' : 'detail';
      const firstReadChapterAttr = firstChapter ? `data-chapter="${firstChapter.id}"` : '';

      const coverSrc = featured.cover || 'https://placehold.co/600x800/1e1b4b/ffffff?text=Kapak';
      const typeLabel = featured.type || 'Manhwa';
      const statusLabel = featured.status || 'Devam Ediyor';
      const synopsis = this.cleanSynopsis(featured.synopsis, featured);

      const genresList = (Array.isArray(featured.genres) ? featured.genres : [])
        .filter((g) => String(g).toLowerCase() !== typeLabel.toLowerCase())
        .slice(0, 5);
      const genresHtml = genresList
        .map((g) => `<span class="hero-detail-genre">${g}</span>`)
        .join('');
      const genresBlockHtml = genresHtml
        ? `<div class="hero-genres" id="hero-genres">${genresHtml}</div>`
        : '';

      const iconFn =
        (globalScope.ManowaIcons && globalScope.ManowaIcons.get) ||
        (typeof require === 'function' ? require('./svg-icons').getSvgIcon : () => '');
      const authorHtml = featured.author
        ? `<span class="hero-detail-item">${iconFn('pen')} ${featured.author}</span>`
        : '';

      const dotsHtml = this.slides
        .map((slide, idx) => {
          const isActive = idx === this.currentIndex;
          return `<button class="hero-dot ${isActive ? 'active' : ''}" type="button" data-hero-index="${idx}" aria-label="${slide.title}" title="${slide.title}"></button>`;
        })
        .join('');

      return `
        <div class="hero-backdrop" style="background-image: url('${coverSrc}');"></div>
        <div class="hero-backdrop-overlay"></div>

        <button class="hero-arrow-btn hero-arrow-prev" id="btn-hero-prev" type="button" data-hero-nav="prev" aria-label="Önceki Slayt" title="Önceki">‹</button>
        <button class="hero-arrow-btn hero-arrow-next" id="btn-hero-next" type="button" data-hero-nav="next" aria-label="Sonraki Slayt" title="Sonraki">›</button>

        <div class="hero-slide-grid">
          <div class="hero-content">
            <h1 class="hero-title" id="hero-title">
              <a class="hero-title-link" href="${detailHref}" data-action="detail" data-series="${featured.id}">${featured.title}</a>
            </h1>
            ${genresBlockHtml}
            <div class="hero-details" id="hero-details">
              <span class="hero-detail-item hero-detail-type">${typeLabel}</span>
              <span class="hero-detail-item">${statusLabel}</span>
              <span class="hero-detail-item">${iconFn('layers')} ${chapterCount} Bölüm</span>
              ${authorHtml}
            </div>
            <p class="hero-desc" id="hero-desc">${synopsis}</p>
            <div class="hero-actions">
              <a class="primary-btn hero-primary-cta" href="${firstReadHref}" id="btn-hero-read" data-action="${firstReadAction}" data-series="${featured.id}" ${firstReadChapterAttr}>Hemen Oku →</a>
              <a class="hero-detail-btn" href="${detailHref}" id="btn-hero-detail" data-action="detail" data-series="${featured.id}">Seri Ayrıntıları</a>
            </div>
          </div>

          <div class="hero-cover-wrap">
            <a class="hero-poster-card" href="${detailHref}" data-action="detail" data-series="${featured.id}" title="${featured.title}">
              <img alt="${featured.title}" class="hero-cover-img" id="hero-cover-img" src="${coverSrc}" />
            </a>
          </div>
        </div>

        <div class="hero-dots-bar" id="hero-dots-track">
          ${dotsHtml}
        </div>
      `.trim();
    }

    /**
     * Tarayici DOM icindeki #hero-showcase kapsayicisini gunceller.
     * @param {Object} catalog - CatalogController nesnesi.
     * @param {Object} [library=null] - UserLibrary nesnesi.
     * @param {Function} [urlBuilder=null] - URL olusturucu fonksiyon.
     * @returns {boolean} Guncelleme yapildiysa true.
     */
    renderIntoDom(catalog, library = null, urlBuilder = null) {
      if (typeof document === 'undefined') {
        return false;
      }
      const container = document.getElementById('hero-showcase');
      if (!container) {
        return false;
      }
      if (this.slides.length === 0 && catalog) {
        this.setSlidesFromCatalog(catalog);
      }
      const html = this.buildSliderHtml(catalog, library, urlBuilder);
      if (!html) {
        return false;
      }
      container.innerHTML = html;
      return true;
    }

    /**
     * #hero-showcase uzerindeki tiklama, uzerine gelme ve dokunmatik kaydirma olaylarini baglar.
     * @param {Function} onChange - Slayt degistiginde cagrilacak guncelleme fonksiyonu.
     * @returns {void}
     */
    bindDomEvents(onChange) {
      if (typeof document === 'undefined') {
        return;
      }
      const heroBox = document.getElementById('hero-showcase');
      if (!heroBox) {
        return;
      }
      const refresh = () => {
        if (typeof onChange === 'function') {
          onChange();
        }
      };
      heroBox.addEventListener('click', (ev) => {
        const heroNav = ev.target.closest('[data-hero-nav], [data-hero-index]');
        if (!heroNav) {
          return;
        }
        ev.preventDefault();
        const dir = heroNav.getAttribute('data-hero-nav');
        const idx = heroNav.getAttribute('data-hero-index');
        if (dir === 'next') this.nextSlide();
        else if (dir === 'prev') this.prevSlide();
        else if (idx !== null) this.goToSlide(Number(idx));
        refresh();
        this.startAutoPlay(refresh);
      });
      heroBox.addEventListener('mouseenter', () => this.setPaused(true));
      heroBox.addEventListener('mouseleave', () => this.setPaused(false));
      heroBox.addEventListener(
        'touchstart',
        (e) => {
          if (e.touches && e.touches[0]) {
            this.touchStartX = e.touches[0].clientX;
          }
        },
        { passive: true }
      );
      heroBox.addEventListener(
        'touchend',
        (e) => {
          if (this.touchStartX !== null && e.changedTouches && e.changedTouches[0]) {
            const moved = this.handleTouchGesture(this.touchStartX, e.changedTouches[0].clientX);
            this.touchStartX = null;
            if (moved !== 'none') refresh();
          }
        },
        { passive: true }
      );
    }
  }

  globalScope.HeroSlider = HeroSlider;

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = { HeroSlider };
  }
})(typeof window !== 'undefined' ? window : globalThis);

/* === MODULE: scripts/sidebar-controller.js === */
/**
 * @fileoverview Ana sayfa sag yan panel (Sidebar) bilesenlerini yoneten modul (SidebarController).
 * Populer & One Cikan Seriler siralamasi, Kategoriler bulutu ve Hizli Kitaplik / Arsiv Ozetini uretir.
 */

(function (globalScope) {
  'use strict';

  const EXCLUDED_GENRE_TYPES = ['manhwa', 'manga', 'manhua', 'novel', 'webcomic', 'seri', 'bölüm'];

  /**
   * Ana sayfa yan panelini (Sidebar) yoneten sinif.
   */
  class SidebarController {
    /**
     * SidebarController nesnesini yapilandirir.
     * @param {Object} [options={}] - Yapilandirma secenekleri.
     * @param {Object} [options.logger=null] - Loglayici nesnesi.
     * @param {number} [options.topLimit=5] - Populer listedeki maksimum seri sayisi.
     */
    constructor(options = {}) {
      this.logger = options.logger || globalScope.ManowaLogger || null;
      this.topLimit = typeof options.topLimit === 'number' ? options.topLimit : 5;
      this.topFilter = 'ALL';
      this._log('debug', 'SidebarController baslatildi.', { topLimit: this.topLimit });
    }

    /**
     * Ic loglama yardimcisi.
     * @param {'debug'|'info'|'warn'|'error'} level - Log seviyesi.
     * @param {string} msg - Log mesaji.
     * @param {Object|null} [meta=null] - Ek veri.
     * @returns {void}
     */
    _log(level, msg, meta = null) {
      if (this.logger && typeof this.logger[level] === 'function') {
        this.logger[level](msg, meta);
      }
    }

    /**
     * SVG ikon yardimcisini dondurur.
     * @param {string} name - Ikon adi.
     * @returns {string} SVG dizgesi.
     */
    _icon(name) {
      if (globalScope.ManowaIcons && typeof globalScope.ManowaIcons.get === 'function') {
        return globalScope.ManowaIcons.get(name);
      }
      if (typeof require === 'function') {
        try {
          return require('./svg-icons').getSvgIcon(name);
        } catch (_err) {
          return '';
        }
      }
      return '';
    }

    /**
     * Populer seriler sekme filtresini degistirir ('ALL', 'Manhwa', 'Manga', 'Novel').
     * @param {string} filterType - Yeni filtre turu.
     * @returns {string} Aktif filtre turu.
     */
    setTopFilter(filterType) {
      this.topFilter = String(filterType || 'ALL').trim();
      this._log('debug', 'Sidebar populer seri filtresi degistirildi.', {
        topFilter: this.topFilter
      });
      return this.topFilter;
    }

    /**
     * Katalog icindeki serileri bolum sayisi ve puana gore siralayarak dondurur.
     * @param {Object} catalog - CatalogController nesnesi.
     * @param {string} [typeFilter=this.topFilter] - Tur filtresi ('ALL', 'Manhwa', 'Manga', 'Novel').
     * @param {number} [limit=this.topLimit] - Maksimum kayit sayisi.
     * @returns {Array<Object>} Siralanmis populer seriler.
     */
    getTopSeries(catalog, typeFilter = this.topFilter, limit = this.topLimit) {
      if (!catalog || !Array.isArray(catalog.seriesList)) {
        return [];
      }
      const normFilter = String(typeFilter || 'ALL').trim().toUpperCase();
      const filtered = catalog.seriesList.filter((series) => {
        if (normFilter === 'ALL') {
          return true;
        }
        return (
          String(series.type || '').toUpperCase() === normFilter ||
          String(series.sourceLang || '').toUpperCase() === normFilter
        );
      });

      filtered.sort((a, b) => {
        const chDiff = (b.chapters || []).length - (a.chapters || []).length;
        if (chDiff !== 0) {
          return chDiff;
        }
        return parseFloat(b.rating || '0') - parseFloat(a.rating || '0');
      });

      return filtered.slice(0, Math.max(1, limit));
    }

    /**
     * Katalogdaki tum serilerden kategori (genre) isimlerini ve seri sayilarini cikarir.
     * @param {Object} catalog - CatalogController nesnesi.
     * @returns {Array<{ name: string, count: number }>} Kategori ve sayac listesi.
     */
    getGenreCounts(catalog) {
      if (!catalog || !Array.isArray(catalog.seriesList)) {
        return [];
      }
      const map = new Map();
      catalog.seriesList.forEach((series) => {
        const seenInSeries = new Set();
        (series.genres || []).forEach((rawGenre) => {
          const clean = String(rawGenre || '').trim();
          const lower = clean.toLowerCase();
          if (!clean || EXCLUDED_GENRE_TYPES.includes(lower) || seenInSeries.has(lower)) {
            return;
          }
          seenInSeries.add(lower);
          const existing = map.get(lower);
          if (existing) {
            existing.count += 1;
          } else {
            map.set(lower, { name: clean, count: 1 });
          }
        });
      });

      return Array.from(map.values()).sort((a, b) => {
        if (b.count !== a.count) {
          return b.count - a.count;
        }
        return a.name.localeCompare(b.name, 'tr');
      });
    }

    /**
     * Toplam seri, toplam bolum ve favori seri istatistiklerini hesaplar.
     * @param {Object} catalog - CatalogController nesnesi.
     * @param {Object|null} [library=null] - UserLibrary nesnesi.
     * @returns {{ totalSeries: number, totalChapters: number, favoriteCount: number }}
     */
    getArchiveStats(catalog, library = null) {
      const seriesList = catalog && Array.isArray(catalog.seriesList) ? catalog.seriesList : [];
      const totalSeries = seriesList.length;
      const totalChapters = seriesList.reduce(
        (sum, s) => sum + (Array.isArray(s.chapters) ? s.chapters.length : 0),
        0
      );
      const favoriteCount =
        library && typeof library.getFavoriteIds === 'function'
          ? library.getFavoriteIds().length
          : 0;
      return { totalSeries, totalChapters, favoriteCount };
    }

    /**
     * Populer & One Cikan Seriler listesi icin HTML uretir.
     * @param {Object} catalog - CatalogController nesnesi.
     * @param {Function} computeUrlFn - URL olusturucu fonksiyon.
     * @returns {string} HTML dizgesi.
     */
    renderTopSeriesHtml(catalog, computeUrlFn) {
      const resolveUrl = typeof computeUrlFn === 'function' ? computeUrlFn : () => '#';
      const list = this.getTopSeries(catalog, this.topFilter, this.topLimit);
      if (list.length === 0) {
        return `<div class="sidebar-empty-note">Bu filtrede seri bulunamadı.</div>`;
      }
      return list
        .map((series, idx) => {
          const rankNum = String(idx + 1).padStart(2, '0');
          const rankClass = idx < 3 ? `rank-top-${idx + 1}` : '';
          const href = resolveUrl('series', series.id);
          const chCount = (series.chapters || []).length;
          return `<a class="sidebar-rank-item" href="${href}" data-action="detail" data-series="${series.id}">
            <span class="sidebar-rank-badge ${rankClass}">${rankNum}</span>
            <img class="sidebar-rank-thumb" src="${series.cover}" alt="${series.title}" loading="lazy" />
            <div class="sidebar-rank-info">
              <strong class="sidebar-rank-title">${series.title}</strong>
              <div class="sidebar-rank-meta">
                <span class="sidebar-rank-type">${series.type || 'Seri'}</span>
                <span>${this._icon('layers')} ${chCount} Bölüm</span>
              </div>
            </div>
          </a>`;
        })
        .join('');
    }

    /**
     * Kategoriler / Tur Bulutu kutusu icin HTML uretir.
     * @param {Object} catalog - CatalogController nesnesi.
     * @returns {string} HTML dizgesi.
     */
    renderGenresHtml(catalog) {
      const genres = this.getGenreCounts(catalog);
      const activeGenre = (catalog && catalog.activeGenre) || 'ALL';
      const totalCount = catalog && Array.isArray(catalog.seriesList) ? catalog.seriesList.length : 0;

      const allPill = `<button class="sidebar-genre-chip ${activeGenre === 'ALL' ? 'active' : ''}" type="button" data-sidebar-genre="ALL">
        <span>Tümü</span>
        <span class="sidebar-genre-count">${totalCount}</span>
      </button>`;

      const genrePills = genres
        .map((g) => {
          const isActive = activeGenre.toLowerCase() === g.name.toLowerCase();
          return `<button class="sidebar-genre-chip ${isActive ? 'active' : ''}" type="button" data-sidebar-genre="${g.name}">
            <span>${g.name}</span>
            <span class="sidebar-genre-count">${g.count}</span>
          </button>`;
        })
        .join('');

      return allPill + genrePills;
    }

    /**
     * Hizli Kitapligim ve Arsiv Ozeti kutusu icin HTML uretir.
     * @param {Object} catalog - CatalogController nesnesi.
     * @param {Object|null} library - UserLibrary nesnesi.
     * @param {Function} computeUrlFn - URL olusturucu fonksiyon.
     * @returns {string} HTML dizgesi.
     */
    renderQuickLibraryHtml(catalog, library, computeUrlFn) {
      const resolveUrl = typeof computeUrlFn === 'function' ? computeUrlFn : () => '#';
      const stats = this.getArchiveStats(catalog, library);
      const favSeries =
        library && typeof library.getFavoriteSeries === 'function'
          ? library.getFavoriteSeries(catalog).slice(0, 3)
          : [];

      const statsHtml = `<div class="sidebar-stats-grid">
        <div class="sidebar-stat-box">
          <strong class="sidebar-stat-val">${stats.totalSeries}</strong>
          <span class="sidebar-stat-lbl">Seri</span>
        </div>
        <div class="sidebar-stat-box">
          <strong class="sidebar-stat-val">${stats.totalChapters}</strong>
          <span class="sidebar-stat-lbl">Bölüm</span>
        </div>
        <div class="sidebar-stat-box">
          <strong class="sidebar-stat-val">${stats.favoriteCount}</strong>
          <span class="sidebar-stat-lbl">Kitaplık</span>
        </div>
      </div>`;

      const favListHtml =
        favSeries.length > 0
          ? `<div class="sidebar-fav-mini-list">` +
            favSeries
              .map((s) => {
                const sHref = resolveUrl('series', s.id);
                return `<a class="sidebar-fav-mini-item" href="${sHref}" data-action="detail" data-series="${s.id}">
                  <img class="sidebar-fav-mini-thumb" src="${s.cover}" alt="${s.title}" loading="lazy" />
                  <span class="sidebar-fav-mini-title">${s.title}</span>
                  <span class="sidebar-fav-mini-count">${(s.chapters || []).length} Böl.</span>
                </a>`;
              })
              .join('') +
            `</div>`
          : `<div class="sidebar-empty-note">Favori serilerinize hızlı erişmek için kartlardaki ${this._icon('heart')} düğmesini kullanın.</div>`;

      return statsHtml + favListHtml;
    }

    /**
     * Tarayici DOM icindeki Sidebar bilesenlerini gunceller.
     * @param {Object} catalog - CatalogController nesnesi.
     * @param {Object|null} library - UserLibrary nesnesi.
     * @param {Function} computeUrlFn - URL olusturucu fonksiyon.
     * @returns {void}
     */
    renderIntoDom(catalog, library, computeUrlFn) {
      if (typeof document === 'undefined' || !catalog) {
        return;
      }
      const topListEl = document.getElementById('sidebar-top-list');
      if (topListEl) {
        topListEl.innerHTML = this.renderTopSeriesHtml(catalog, computeUrlFn);
      }
      const genresListEl = document.getElementById('sidebar-genres-list');
      if (genresListEl) {
        genresListEl.innerHTML = this.renderGenresHtml(catalog);
      }
      const quickLibEl = document.getElementById('sidebar-quick-library-body');
      if (quickLibEl) {
        quickLibEl.innerHTML = this.renderQuickLibraryHtml(catalog, library, computeUrlFn);
      }
    }

    /**
     * Sidebar uzerindeki sekme ve kategori filtre tiklamalarini baglar.
     * @param {Object} callbacks - Geri bildirim islevleri ({ onTopFilterChange, onGenreSelect }).
     * @returns {void}
     */
    bindDomEvents(callbacks = {}) {
      if (typeof document === 'undefined') {
        return;
      }
      const sidebarEl = document.getElementById('home-sidebar');
      if (!sidebarEl) {
        return;
      }
      sidebarEl.addEventListener('click', (ev) => {
        const tabBtn = ev.target.closest('[data-sidebar-tab]');
        if (tabBtn) {
          ev.preventDefault();
          const tabVal = tabBtn.getAttribute('data-sidebar-tab') || 'ALL';
          this.setTopFilter(tabVal);
          sidebarEl
            .querySelectorAll('[data-sidebar-tab]')
            .forEach((b) => b.classList.toggle('active', b === tabBtn));
          if (typeof callbacks.onTopFilterChange === 'function') {
            callbacks.onTopFilterChange(tabVal);
          }
          return;
        }
        const genreBtn = ev.target.closest('[data-sidebar-genre]');
        if (genreBtn) {
          ev.preventDefault();
          const genreVal = genreBtn.getAttribute('data-sidebar-genre') || 'ALL';
          if (typeof callbacks.onGenreSelect === 'function') {
            callbacks.onGenreSelect(genreVal);
          }
        }
      });
    }
  }

  globalScope.SidebarController = SidebarController;

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = { SidebarController };
  }
})(typeof window !== 'undefined' ? window : globalThis);

/* === MODULE: scripts/reading-engine.js === */
/**
 * @fileoverview Cok modlu okuma motoru (Webtoon, Tek Sayfa, Cift Sayfa ve Novel) sinifi.
 * Okuma yonu (LTR/RTL), zoom, sayfa boslugu, otomatik kaydirma ve ilerleme kaydini yonetir.
 */

(function (globalScope) {
  'use strict';

  const VALID_MODES = ['webtoon', 'single', 'double', 'novel'];
  const VALID_DIRECTIONS = ['ltr', 'rtl'];

  /**
   * Manga, Manhwa ve Novel okuma deneyimini yoneten sinif.
   */
  class ReadingEngine {
    /**
     * ReadingEngine nesnesini baslatir.
     * @param {Object} [options={}] - Baslangic secenekleri.
     */
    constructor(options = {}) {
      this.logger = options.logger || globalScope.ManowaLogger || null;
      this.storage =
        options.storage || (typeof localStorage !== 'undefined' ? localStorage : null);
      this.historyKey = 'manowa_reading_history';
      this.seriesType = this.normalizeSeriesType(
        options.seriesType || 'Manhwa',
        options.sourceLang || '',
        Boolean(options.isNovel)
      );
      this.mode = VALID_MODES.includes(options.mode) ? options.mode : 'webtoon';
      this.direction = VALID_DIRECTIONS.includes(options.direction) ? options.direction : 'ltr';
      this.zoom = this._clamp(options.zoom || 100, 50, 150);
      this.gap = typeof options.gap === 'number' ? Math.max(0, options.gap) : 0;
      this.novelFontSize = this._clamp(options.novelFontSize || 105, 85, 160);
      this.novelFontFamily = options.novelFontFamily === 'serif' ? 'serif' : 'sans';
      this.protectImages =
        options.protectImages !== undefined ? Boolean(options.protectImages) : true;
      this.rawPages = [];
      this.pageGroups = [];
      this.pages = [];
      this.htmlContent = '';
      this.currentIndex = 0;
      this.seriesId = '';
      this.chapterId = '';
      this.autoScrollActive = false;
      this.autoScrollSpeed = 2;
      this._autoScrollTimer = null;

      this._log('debug', 'ReadingEngine baslatildi.', {
        seriesType: this.seriesType,
        mode: this.mode,
        direction: this.direction,
        zoom: this.zoom
      });
    }

    /**
     * Seri turunu ('manhwa', 'manhua', 'manga', 'novel') olarak normalize eder.
     * @param {string} [rawType=''] - Ham seri turu.
     * @param {string} [sourceLang=''] - Kaynak dil kodu ('KR', 'JP', 'CN', 'EN').
     * @param {boolean} [isNovel=false] - Bolumun metin tabanli olup olmadigi.
     * @returns {'manhwa'|'manhua'|'manga'|'novel'} Normalize edilmis tur.
     */
    normalizeSeriesType(rawType = '', sourceLang = '', isNovel = false) {
      const lower = String(rawType || '').trim().toLowerCase();
      const lang = String(sourceLang || '').trim().toUpperCase();
      if (isNovel || lower === 'novel' || lower === 'roman' || lower === 'webnovel') {
        return 'novel';
      }
      if (lower === 'manga' || lang === 'JP') {
        return 'manga';
      }
      if (lower === 'manhua' || lang === 'CN') {
        return 'manhua';
      }
      return 'manhwa';
    }

    /**
     * Aktif seri turunun kullanici arayuzu etiketini dondurur.
     * @returns {string} Gosterilecek tur etiketi.
     */
    getSeriesTypeLabel() {
      const map = {
        novel: 'Novel',
        manga: 'Manga',
        manhua: 'Manhua',
        manhwa: 'Manhwa'
      };
      return map[this.seriesType] || 'Manhwa';
    }

    /**
     * Bolum secici acilir kutusu icin tekrarli seri adindan arindirilmis kisa etiket uretir.
     * @param {Object} [chapter={}] - Bolum nesnesi.
     * @returns {string} Kisa bolum etiketi (orn: "Bölüm 279").
     */
    formatChapterSelectLabel(chapter = {}) {
      if (chapter && chapter.number !== undefined && chapter.number !== null && chapter.number !== '') {
        return `Bölüm ${chapter.number}`;
      }
      const rawTitle = String((chapter && chapter.title) || '').trim();
      const match = rawTitle.match(/B[öo]l[üu]m\s*(\d+(?:[.,]\d+)?)/i);
      if (match) {
        return `Bölüm ${match[1]}`;
      }
      return rawTitle || 'Bölüm';
    }

    /**
     * Gorsel URL'sinden "01_01", "01_02", "02-01" gibi bolunmus sayfa grup anahtarini cikarir.
     * Tekil dosya adlarinda (orn: "Kapak.webp", "p1.webp") null dondurur.
     * @param {string} rawUrl - Gorsel URL dizgesi.
     * @returns {string|null} Mantiksal sayfa grup anahtari (orn: "page:1") veya null.
     */
    extractSliceGroupKey(rawUrl) {
      const rawStr = String(rawUrl || '');
      const cleanPath = rawStr.split(/[?#]/)[0];
      const hashPath = rawStr.includes('#') ? rawStr.split('#').pop() : '';
      const candidates = [cleanPath, hashPath, rawStr];

      for (const candidate of candidates) {
        const lastSegMatch = String(candidate || '').match(/([^/?#&]+)$/);
        if (!lastSegMatch) continue;
        let fileName = lastSegMatch[1];
        try {
          fileName = decodeURIComponent(fileName);
        } catch (_err) {
          // Decode hatasini yoksay
        }
        const baseName = fileName.replace(/\.(?:webp|jpe?g|png|gif|avif|bmp|svg)$/i, '').trim();
        const sliceMatch =
          baseName.match(/^(?:sayfa[_-]?|page[_-]?|p)?(\d+)[_](\d+)$/i) ||
          baseName.match(/^(\d{2,})[-_](\d{2,})$/);
        if (sliceMatch) {
          return `page:${Number(sliceMatch[1])}`;
        }
      }
      return null;
    }

    /**
     * "01_01, 01_02, 01_03" seklinde bolunerek yuklenmis gorsel URL listesini
     * ardisik mantiksal tam sayfa gruplarina (Array<Array<string>>) donusturur.
     * @param {Array<string>} [rawPages=[]] - Ham gorsel URL dizisi.
     * @returns {Array<Array<string>>} Gruplanmis mantiksal sayfa dilimleri.
     */
    groupSlicedPages(rawPages = []) {
      if (!Array.isArray(rawPages) || rawPages.length === 0) {
        return [];
      }
      const groups = [];
      let currentGroup = [];
      let currentKey = null;

      rawPages.forEach((url) => {
        const key = this.extractSliceGroupKey(url);
        if (key && key === currentKey && currentGroup.length > 0) {
          currentGroup.push(url);
        } else {
          currentGroup = [url];
          currentKey = key;
          groups.push(currentGroup);
        }
      });

      return groups;
    }

    /**
     * Belirtilen mantiksal sayfa indeksine ait tum gorsel dilimlerini dondurur.
     * @param {number} pageIndex - Mantiksal sayfa indeksi.
     * @returns {Array<string>} Sayfayi olusturan gorsel URL dilimleri.
     */
    getPageSlices(pageIndex) {
      if (Array.isArray(this.pageGroups) && Array.isArray(this.pageGroups[pageIndex])) {
        return this.pageGroups[pageIndex];
      }
      if (this.pages[pageIndex]) {
        return [this.pages[pageIndex]];
      }
      return [];
    }

    /**
     * Ic loglama yardimcisi.
     * @param {'debug'|'info'|'warn'|'error'} level - Log seviyesi.
     * @param {string} msg - Log mesaji.
     * @param {Object|null} [meta=null] - Ek veri.
     * @returns {void}
     */
    _log(level, msg, meta = null) {
      if (this.logger && typeof this.logger[level] === 'function') {
        this.logger[level](msg, meta);
      }
    }

    /**
     * Sayisal degeri min ve max araliginda sinirlar.
     * @param {number} val - Deger.
     * @param {number} min - Alt sinir.
     * @param {number} max - Ust sinir.
     * @returns {number} Sinirlanmis deger.
     */
    _clamp(val, min, max) {
      return Math.min(max, Math.max(min, Number(val) || min));
    }

    /**
     * Yeni bir bolumu okuma motoruna yukler ve seri turune gore modu/yonu otomatik ayarlar.
     * Bolunmus ("01_01, 01_02") gorselleri mantiksal tam sayfalara gruplar.
     * @param {Object} [chapterData={}] - Bolum verileri.
     * @returns {Object} Guncel motor durumu.
     */
    loadChapter(chapterData = {}) {
      this.stopAutoScroll();
      this.seriesId = chapterData.seriesId || '';
      this.chapterId = chapterData.chapterId || '';
      this.rawPages = Array.isArray(chapterData.pages) ? chapterData.pages.slice() : [];
      this.pageGroups = this.groupSlicedPages(this.rawPages);
      this.pages = this.pageGroups.map((group) => group[0]);
      this.htmlContent = String(chapterData.htmlContent || '');
      const hasOnlyNovelHtml = Boolean(this.pages.length === 0 && this.htmlContent);
      const isNovelChapter = Boolean(chapterData.isNovel || hasOnlyNovelHtml);

      this.seriesType = this.normalizeSeriesType(
        chapterData.seriesType || '',
        chapterData.sourceLang || '',
        isNovelChapter
      );

      if (this.seriesType === 'novel' || hasOnlyNovelHtml) {
        this.seriesType = 'novel';
        this.mode = 'novel';
        this.direction = 'ltr';
      } else {
        if (chapterData.defaultMode && VALID_MODES.includes(chapterData.defaultMode) && chapterData.defaultMode !== 'novel') {
          this.mode = chapterData.defaultMode;
        } else if (this.seriesType === 'manga') {
          this.mode = 'single';
        } else {
          this.mode = 'webtoon';
        }

        if (chapterData.direction && VALID_DIRECTIONS.includes(chapterData.direction)) {
          this.direction = chapterData.direction;
        } else if (this.seriesType === 'manga') {
          this.direction = 'rtl';
        } else {
          this.direction = 'ltr';
        }
      }

      const saved = this.getProgress(this.seriesId);
      if (typeof chapterData.startPage === 'number') {
        this.currentIndex = this._clamp(chapterData.startPage, 0, Math.max(0, this.pages.length - 1));
      } else if (
        saved &&
        saved.chapterId === this.chapterId &&
        typeof saved.pageIndex === 'number'
      ) {
        this.currentIndex = this._clamp(saved.pageIndex, 0, Math.max(0, this.pages.length - 1));
      } else {
        this.currentIndex = 0;
      }

      this.saveProgress();
      this.preloadAdjacentPages();
      this._log('info', 'Bolum okuma motoruna yuklendi.', {
        seriesId: this.seriesId,
        chapterId: this.chapterId,
        seriesType: this.seriesType,
        mode: this.mode,
        direction: this.direction,
        pageCount: this.pages.length,
        rawSliceCount: this.rawPages.length,
        isNovel: this.seriesType === 'novel',
        startIndex: this.currentIndex
      });

      return this.getState();
    }

    /**
     * Okuma modunu degistirir ('webtoon', 'single', 'double', 'novel').
     * @param {string} newMode - Yeni okuma modu.
     * @returns {string} Aktif okuma modu.
     */
    setMode(newMode) {
      if (VALID_MODES.includes(newMode)) {
        this.mode = newMode;
        this._log('info', 'Okuma modu degistirildi.', { mode: this.mode });
      } else {
        this._log('warn', 'Gecersiz okuma modu reddedildi.', { attempted: newMode });
      }
      return this.mode;
    }

    /**
     * Okuma yonunu degistirir ('ltr' veya 'rtl').
     * @param {string} newDir - Yeni yon.
     * @returns {string} Aktif yon.
     */
    setDirection(newDir) {
      if (VALID_DIRECTIONS.includes(newDir)) {
        this.direction = newDir;
        this._log('info', 'Okuma yonu degistirildi.', { direction: this.direction });
      }
      return this.direction;
    }

    /**
     * Yakinlastirma (zoom) yuzdesini ayarlar (50 - 150).
     * @param {number} zoomPercent - Zoom degeri.
     * @returns {number} Guncel zoom degeri.
     */
    setZoom(zoomPercent) {
      this.zoom = this._clamp(zoomPercent, 50, 150);
      this._log('debug', 'Zoom seviyesi guncellendi.', { zoom: this.zoom });
      return this.zoom;
    }

    /**
     * Webtoon modunda sayfalar arasi boslugu ayarlar.
     * @param {number} gapPx - Piksel cinsinden bosluk.
     * @returns {number} Guncel bosluk.
     */
    setGap(gapPx) {
      this.gap = Math.max(0, Number(gapPx) || 0);
      this._log('debug', 'Sayfa arasi bosluk guncellendi.', { gap: this.gap });
      return this.gap;
    }

    /**
     * Novel modu yazi boyutunu yuzde olarak ayarlar (85 - 160).
     * @param {number} sizePercent - Yazi boyutu yuzdesi.
     * @returns {number} Guncel yazi boyutu yuzdesi.
     */
    setNovelFontSize(sizePercent) {
      this.novelFontSize = this._clamp(sizePercent, 85, 160);
      this._log('debug', 'Novel yazi boyutu guncellendi.', { novelFontSize: this.novelFontSize });
      return this.novelFontSize;
    }

    /**
     * Novel modu yazi tipini ('sans' ve 'serif') arasinda degistirir.
     * @returns {string} Guncel yazi tipi ('sans' veya 'serif').
     */
    toggleNovelFontFamily() {
      this.novelFontFamily = this.novelFontFamily === 'serif' ? 'sans' : 'serif';
      this._log('info', 'Novel yazi tipi degistirildi.', { novelFontFamily: this.novelFontFamily });
      return this.novelFontFamily;
    }

    /**
     * Mevcut mod ve yone gore ekranda gosterilecek sayfa indekslerini dondurur.
     * @returns {Array<number>} Sayfa indeks dizisi.
     */
    getVisiblePageIndices() {
      const total = this.pages.length;
      if (total === 0) {
        return [];
      }
      if (this.mode === 'webtoon') {
        return this.pages.map((_, idx) => idx);
      }
      if (this.mode === 'single') {
        return [this.currentIndex];
      }
      const pair = [this.currentIndex];
      if (this.currentIndex + 1 < total) {
        pair.push(this.currentIndex + 1);
      }
      if (this.direction === 'rtl' && pair.length === 2) {
        return [pair[1], pair[0]];
      }
      return pair;
    }

    /**
     * Sonraki sayfaya gecer (Single ve Double modlarinda).
     * @returns {boolean} Sayfa degistiyse true.
     */
    nextPage() {
      if (this.mode === 'webtoon' || this.mode === 'novel' || this.pages.length === 0) {
        return false;
      }
      const step = this.mode === 'double' ? 2 : 1;
      if (this.currentIndex + step < this.pages.length) {
        this.currentIndex += step;
        this.saveProgress();
        this.preloadAdjacentPages();
        this._log('debug', 'Sonraki sayfaya gecildi.', { currentIndex: this.currentIndex });
        return true;
      }
      return false;
    }

    /**
     * Onceki sayfaya doner (Single ve Double modlarinda).
     * @returns {boolean} Sayfa degistiyse true.
     */
    prevPage() {
      if (this.mode === 'webtoon' || this.mode === 'novel' || this.pages.length === 0) {
        return false;
      }
      const step = this.mode === 'double' ? 2 : 1;
      if (this.currentIndex > 0) {
        this.currentIndex = Math.max(0, this.currentIndex - step);
        this.saveProgress();
        this._log('debug', 'Onceki sayfaya donuldu.', { currentIndex: this.currentIndex });
        return true;
      }
      return false;
    }

    /**
     * Belirtilen sayfa indeksine dogrudan gider.
     * @param {number} pageIndex - Hedef sayfa indeksi.
     * @returns {number} Gidilen sayfa indeksi.
     */
    goToPage(pageIndex) {
      if (this.pages.length === 0) {
        this.currentIndex = 0;
        return 0;
      }
      this.currentIndex = this._clamp(pageIndex, 0, this.pages.length - 1);
      this.saveProgress();
      this.preloadAdjacentPages();
      return this.currentIndex;
    }

    /**
     * Okuma ilerleme yuzdesini hesaplar.
     * @returns {number} 0-100 arasi yuzde.
     */
    getProgressPercent() {
      if (this.mode === 'novel') {
        return 100;
      }
      const total = this.pages.length;
      if (total <= 1) {
        return total === 1 ? 100 : 0;
      }
      const lastVisible =
        this.mode === 'double' ? Math.min(total - 1, this.currentIndex + 1) : this.currentIndex;
      return Math.round(((lastVisible + 1) / total) * 100);
    }

    /**
     * Sonraki 2 mantiksal sayfanin tum gorsel dilimlerini onceden bellekleme (preload) yapar.
     * @returns {Array<string>} On yuklenen URL listesi.
     */
    preloadAdjacentPages() {
      const preloaded = [];
      for (let i = 1; i <= 2; i++) {
        const targetIdx = this.currentIndex + i;
        if (targetIdx < this.pages.length) {
          const slices = this.getPageSlices(targetIdx);
          slices.forEach((url) => {
            preloaded.push(url);
            if (typeof Image !== 'undefined') {
              const img = new Image();
              img.src = url;
            }
          });
        }
      }
      return preloaded;
    }

    /**
     * Otomatik dikey kaydirmayi baslatir.
     * @param {Function|null} [scrollCallback=null] - Ozel kaydirma islevi.
     * @returns {boolean} Aktif durumu.
     */
    startAutoScroll(scrollCallback = null) {
      this.stopAutoScroll();
      this.autoScrollActive = true;
      this._log('info', 'Otomatik kaydirma baslatildi.', { speed: this.autoScrollSpeed });
      this._autoScrollTimer = setInterval(() => {
        const pixels = this.autoScrollSpeed * 2;
        if (typeof scrollCallback === 'function') {
          scrollCallback(pixels);
        } else if (typeof window !== 'undefined' && typeof window.scrollBy === 'function') {
          window.scrollBy({ top: pixels, behavior: 'auto' });
        }
      }, 30);
      return this.autoScrollActive;
    }

    /**
     * Otomatik kaydirmayi durdurur.
     * @returns {boolean} Aktif durumu (false).
     */
    stopAutoScroll() {
      if (this._autoScrollTimer) {
        clearInterval(this._autoScrollTimer);
        this._autoScrollTimer = null;
      }
      this.autoScrollActive = false;
      return false;
    }

    /**
     * Otomatik kaydirmayi acar veya kapatir.
     * @param {Function|null} [scrollCallback=null] - Ozel kaydirma islevi.
     * @returns {boolean} Yeni durum.
     */
    toggleAutoScroll(scrollCallback = null) {
      if (this.autoScrollActive) {
        return this.stopAutoScroll();
      }
      return this.startAutoScroll(scrollCallback);
    }

    /**
     * Klavye kisayol komutunu isler (RTL yonunde sag/sol tuslarini ters cevirir).
     * @param {string} key - Klavye tus kodu (orn: 'ArrowRight', 'KeyM', 'KeyF').
     * @returns {string} Yapilan islem ('next', 'prev', 'mode:*', 'fullscreen', 'none').
     */
    handleKeyCommand(key) {
      if (key === 'ArrowRight' || key === 'KeyD') {
        if (this.direction === 'rtl') {
          this.prevPage();
          return 'prev';
        }
        this.nextPage();
        return 'next';
      }
      if (key === 'ArrowLeft' || key === 'KeyA') {
        if (this.direction === 'rtl') {
          this.nextPage();
          return 'next';
        }
        this.prevPage();
        return 'prev';
      }
      if (key === 'KeyM') {
        const imageModes = ['webtoon', 'single', 'double'];
        const currentIdx = Math.max(0, imageModes.indexOf(this.mode));
        const nextIdx = (currentIdx + 1) % imageModes.length;
        this.setMode(imageModes[nextIdx]);
        return 'mode:' + this.mode;
      }
      if (key === 'KeyF') {
        return 'fullscreen';
      }
      return 'none';
    }

    /**
     * Okuma ilerlemesini localStorage uzerine kaydeder.
     * @returns {void}
     */
    saveProgress() {
      if (!this.seriesId || !this.chapterId || !this.storage) {
        return;
      }
      try {
        const history = this.getAllHistory();
        history[this.seriesId] = {
          seriesId: this.seriesId,
          chapterId: this.chapterId,
          pageIndex: this.currentIndex,
          updatedAt: new Date().toISOString()
        };
        this.storage.setItem(this.historyKey, JSON.stringify(history));
      } catch (_err) {
        // Depolama hatasini yoksay
      }
    }

    /**
     * Belirtilen seri icin kaydedilmis okuma ilerlemesini getirir.
     * @param {string} seriesId - Seri kimligi.
     * @returns {Object|null} Kayitli ilerleme.
     */
    getProgress(seriesId) {
      const history = this.getAllHistory();
      return history[seriesId] || null;
    }

    /**
     * Tum okuma gecmisini dondurur.
     * @returns {Object} Seri bazli gecmis nesnesi.
     */
    getAllHistory() {
      if (!this.storage) {
        return {};
      }
      try {
        const raw = this.storage.getItem(this.historyKey);
        return raw ? JSON.parse(raw) : {};
      } catch (_err) {
        return {};
      }
    }

    /**
     * Seri turune ve aktif moda gore gosterilecek kontrol gruplarini hesaplar.
     * @returns {{ showMangaControls: boolean, showImageControls: boolean, showAutoScroll: boolean, showNovelControls: boolean, showPageFooterNav: boolean }}
     */
    getVisibleControlGroups() {
      const isNovelMode = this.mode === 'novel' || this.seriesType === 'novel';
      const isMangaType = this.seriesType === 'manga' && !isNovelMode;
      const isPagedMode = !isNovelMode && (this.mode === 'single' || this.mode === 'double');
      return {
        showMangaControls: isMangaType,
        showImageControls: !isNovelMode,
        showAutoScroll: !isNovelMode && this.mode === 'webtoon',
        showNovelControls: isNovelMode,
        showPageFooterNav: isPagedMode
      };
    }

    /**
     * Tek sayfa veya cift sayfa modunda goruntu alaninin sol/sag kenarina tiklandiginda sayfa degistirir.
     * @param {number} clickRatioX - 0 ile 1 arasinda yatay tiklama orani.
     * @returns {'next'|'prev'|'none'} Yapilan sayfa gecisi.
     */
    handleViewportClick(clickRatioX) {
      if (this.mode !== 'single' && this.mode !== 'double') {
        return 'none';
      }
      const ratio = Number(clickRatioX);
      if (Number.isNaN(ratio)) {
        return 'none';
      }
      if (ratio < 0.45) {
        const moved = this.direction === 'rtl' ? this.nextPage() : this.prevPage();
        return moved ? (this.direction === 'rtl' ? 'next' : 'prev') : 'none';
      }
      if (ratio > 0.55) {
        const moved = this.direction === 'rtl' ? this.prevPage() : this.nextPage();
        return moved ? (this.direction === 'rtl' ? 'prev' : 'next') : 'none';
      }
      return 'none';
    }

    /**
     * Mobil dokunmatik ekranlarda yatay kaydirma (swipe) hareketiyle sayfa degistirir.
     * @param {number} startX - Dokunma baslangic X koordinati.
     * @param {number} endX - Dokunma bitis X koordinati.
     * @param {number} [startY=0] - Dokunma baslangic Y koordinati.
     * @param {number} [endY=0] - Dokunma bitis Y koordinati.
     * @returns {'next'|'prev'|'none'} Yapilan sayfa gecisi.
     */
    handleTouchSwipe(startX, endX, startY = 0, endY = 0) {
      if (this.mode !== 'single' && this.mode !== 'double') {
        return 'none';
      }
      const deltaX = Number(endX) - Number(startX);
      const deltaY = Number(endY) - Number(startY);
      if (Number.isNaN(deltaX) || Math.abs(deltaX) < 45) {
        return 'none';
      }
      if (!Number.isNaN(deltaY) && Math.abs(deltaY) > Math.abs(deltaX) * 0.85) {
        return 'none';
      }
      if (deltaX < 0) {
        const moved = this.direction === 'rtl' ? this.prevPage() : this.nextPage();
        return moved ? (this.direction === 'rtl' ? 'prev' : 'next') : 'none';
      }
      const moved = this.direction === 'rtl' ? this.nextPage() : this.prevPage();
      return moved ? (this.direction === 'rtl' ? 'next' : 'prev') : 'none';
    }

    /**
     * Motorun anlik durum özetini dondurur.
     * @returns {Object} Motor durum nesnesi.
     */
    getState() {
      const controlGroups = this.getVisibleControlGroups();
      return {
        seriesType: this.seriesType,
        seriesTypeLabel: this.getSeriesTypeLabel(),
        mode: this.mode,
        direction: this.direction,
        zoom: this.zoom,
        gap: this.gap,
        novelFontSize: this.novelFontSize,
        novelFontFamily: this.novelFontFamily,
        protectImages: this.protectImages,
        currentIndex: this.currentIndex,
        totalPages: this.pages.length,
        hasNovelContent: Boolean(this.htmlContent),
        visibleIndices: this.getVisiblePageIndices(),
        progressPercent: this.getProgressPercent(),
        autoScrollActive: this.autoScrollActive,
        ...controlGroups
      };
    }

    /**
     * Okuyucu kontrol cubugunu motor durumuyla ve seri turuyle esitler.
     * @param {Document} [doc] - Hedef DOM belgesi.
     * @returns {void}
     */
    syncControlsIntoDom(doc) {
      const targetDoc = doc || (typeof document !== 'undefined' ? document : null);
      if (!targetDoc || typeof targetDoc.getElementById !== 'function') return;
      const state = this.getState();
      const modeSelect = targetDoc.getElementById('select-mode');
      const dirSelect = targetDoc.getElementById('select-direction');
      const zoomLabel = targetDoc.getElementById('zoom-label');
      const fontSizeLabel = targetDoc.getElementById('font-size-label');
      const fontFamilyLabel = targetDoc.getElementById('font-family-label');
      const typeBadge = targetDoc.getElementById('reader-type-badge');
      const mangaGroup = targetDoc.getElementById('reader-group-manga');
      const imageGroup = targetDoc.getElementById('reader-group-image');
      const novelGroup = targetDoc.getElementById('reader-group-novel');
      const autoScrollBtn = targetDoc.getElementById('btn-autoscroll');
      const footerPageNav = targetDoc.getElementById('reader-footer-page-nav');
      const prevPageBtn = targetDoc.getElementById('btn-prev-page');
      const nextPageBtn = targetDoc.getElementById('btn-next-page');

      if (modeSelect) modeSelect.value = state.mode;
      if (dirSelect) dirSelect.value = state.direction;
      if (zoomLabel) zoomLabel.textContent = `${state.zoom}%`;
      if (fontSizeLabel) fontSizeLabel.textContent = `${state.novelFontSize}%`;
      if (fontFamilyLabel) {
        fontFamilyLabel.textContent = state.novelFontFamily === 'serif' ? 'Serif' : 'Sans';
      }
      if (typeBadge) {
        typeBadge.textContent = state.seriesTypeLabel;
        if (typeof typeBadge.setAttribute === 'function') {
          typeBadge.setAttribute('data-type', state.seriesType);
        }
      }
      if (mangaGroup && mangaGroup.classList) {
        mangaGroup.classList.toggle('hidden', !state.showMangaControls);
      }
      if (imageGroup && imageGroup.classList) {
        imageGroup.classList.toggle('hidden', !state.showImageControls);
      }
      if (autoScrollBtn && autoScrollBtn.classList) {
        autoScrollBtn.classList.toggle('hidden', !state.showAutoScroll);
      }
      if (novelGroup && novelGroup.classList) {
        novelGroup.classList.toggle('hidden', !state.showNovelControls);
      }
      if (footerPageNav && footerPageNav.classList) {
        footerPageNav.classList.toggle('hidden', !state.showPageFooterNav);
      }
      if (prevPageBtn) {
        prevPageBtn.disabled = state.currentIndex <= 0;
      }
      if (nextPageBtn) {
        const step = state.mode === 'double' ? 2 : 1;
        nextPageBtn.disabled = state.currentIndex + step >= state.totalPages;
      }
    }

    /**
     * Okuma motoru goruntuleme alanini (viewport) aktif moda gore cizer.
     * @param {Document} [doc] - Hedef DOM belgesi.
     * @returns {void}
     */
    renderViewportIntoDom(doc) {
      const targetDoc = doc || (typeof document !== 'undefined' ? document : null);
      if (!targetDoc || typeof targetDoc.getElementById !== 'function') return;
      const viewport = targetDoc.getElementById('reader-viewport');
      const progressBar = targetDoc.getElementById('reader-progress-bar');
      const pageCounter = targetDoc.getElementById('page-counter');
      if (!viewport) return;
      if (!viewport._manowaTouchBound && typeof viewport.addEventListener === 'function') {
        viewport._manowaTouchBound = true;
        viewport.addEventListener(
          'touchstart',
          (ev) => {
            if (ev.touches && ev.touches[0]) {
              this._touchStartX = ev.touches[0].clientX;
              this._touchStartY = ev.touches[0].clientY;
            }
          },
          { passive: true }
        );
        viewport.addEventListener(
          'touchend',
          (ev) => {
            if (
              this._touchStartX !== null &&
              this._touchStartX !== undefined &&
              ev.changedTouches &&
              ev.changedTouches[0]
            ) {
              const res = this.handleTouchSwipe(
                this._touchStartX,
                ev.changedTouches[0].clientX,
                this._touchStartY || 0,
                ev.changedTouches[0].clientY || 0
              );
              this._touchStartX = null;
              this._touchStartY = null;
              if (res !== 'none') {
                this.syncControlsIntoDom(targetDoc);
                this.renderViewportIntoDom(targetDoc);
              }
            }
          },
          { passive: true }
        );
      }
      const state = this.getState();
      viewport.className = `reader-viewport mode-${state.mode} ${state.protectImages ? 'protect-images' : ''}`;
      if (viewport.style && typeof viewport.style.setProperty === 'function') {
        viewport.style.setProperty('--reader-zoom', `${Math.round((state.zoom / 100) * 800)}px`);
        viewport.style.setProperty('--page-gap', `${state.gap}px`);
      }
      if (state.mode === 'novel' || (state.totalPages === 0 && this.htmlContent)) {
        const fontClass = state.novelFontFamily === 'serif' ? 'font-serif' : '';
        const fontSizePct = state.novelFontSize || 105;
        viewport.innerHTML = `<article class="novel-content-box ${fontClass}" style="font-size: ${fontSizePct}%;">${this.htmlContent}</article>`;
      } else if (state.mode === 'double') {
        const pageBlocks = state.visibleIndices
          .map((idx) => {
            const slices = this.getPageSlices(idx);
            const sliceImgs = slices
              .map(
                (src, sIdx) =>
                  `<img class="reader-page-item" src="${src}" alt="Sayfa ${idx + 1}${slices.length > 1 ? ' Parça ' + (sIdx + 1) : ''}" />`
              )
              .join('');
            return `<div class="reader-logical-page" data-page-index="${idx}">${sliceImgs}</div>`;
          })
          .join('');
        viewport.innerHTML = `<div class="double-page-grid">${pageBlocks}</div>`;
      } else if (state.mode === 'single') {
        const pageBlocks = state.visibleIndices
          .map((idx) => {
            const slices = this.getPageSlices(idx);
            const sliceImgs = slices
              .map(
                (src, sIdx) =>
                  `<img class="reader-page-item" src="${src}" alt="Sayfa ${idx + 1}${slices.length > 1 ? ' Parça ' + (sIdx + 1) : ''}" />`
              )
              .join('');
            return `<div class="reader-logical-page" data-page-index="${idx}">${sliceImgs}</div>`;
          })
          .join('');
        viewport.innerHTML = pageBlocks;
      } else {
        viewport.innerHTML = state.visibleIndices
          .map((idx) => {
            const slices = this.getPageSlices(idx);
            return slices
              .map(
                (src) =>
                  `<img class="reader-page-item" src="${src}" alt="Sayfa ${idx + 1}" loading="lazy" />`
              )
              .join('');
          })
          .join('');
      }
      if (progressBar && progressBar.style) progressBar.style.width = `${state.progressPercent}%`;
      if (pageCounter) {
        if (state.mode === 'novel') {
          pageCounter.textContent = `Novel Metin (${state.novelFontSize || 105}%)`;
        } else if (state.mode === 'webtoon') {
          pageCounter.textContent = `${state.totalPages} Sayfa`;
        } else {
          pageCounter.textContent = `Sayfa ${state.currentIndex + 1} / ${state.totalPages}`;
        }
      }
    }
  }

  globalScope.ReadingEngine = ReadingEngine;

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
      ReadingEngine,
      VALID_MODES,
      VALID_DIRECTIONS
