/**
 * @fileoverview Blogger Kalici URL (Permalink), History API (pushState / replaceState)
 * ve Tarayici Geri/Ileri Tusu (popstate) yonlendirme mantigini yoneten modul.
 */
(function (globalScope) {
  'use strict';
  /**
   * Verilen URL dizgesinden kucuk harfli pathname kismini cikarir.
   * @param {string} rawUrl - Ham URL veya yol.
   * @returns {string} Normalize edilmis pathname.
   */
  function extractPathname(rawUrl) {
    if (!rawUrl) return '';
    const str = String(rawUrl).trim();
    try {
      if (str.startsWith('http://') || str.startsWith('https://')) {
        return new URL(str).pathname.toLowerCase().replace(/\/+$/, '') || '/';
      }
    } catch (_err) {
      // Gecersiz URL durumunda alt satirdan devam et
    }
    const clean = str.split('?')[0].split('#')[0].toLowerCase();
    return clean.replace(/\/+$/, '') || '/';
  }
  /**
   * Blogger URL uretimi, History API senkronizasyonu ve rota cozumlemesini yoneten sinif.
   */
  class RouterController {
    /**
     * RouterController nesnesini yapilandirir.
     * @param {Object} [options={}] - Yapilandirma secenekleri.
     */
    constructor(options = {}) {
      this.logger = options.logger || globalScope.ManowaLogger || null;
      this.historyObj =
        options.historyObj || (typeof history !== 'undefined' ? history : null);
      this.locationObj =
        options.locationObj || (typeof location !== 'undefined' ? location : null);
    }
    /**
     * Ortamin yerel dosya onizlemesi (file: veya preview.html) olup olmadigini belirler.
     * @returns {boolean} Yerel onizleme ise true.
     */
    isLocalPreviewEnv() {
      const loc = this.locationObj;
      if (!loc) return false;
      if (loc.protocol === 'file:') return true;
      const pathname = String(loc.pathname || '').toLowerCase();
      return pathname.endsWith('/preview.html') || pathname.endsWith('\\preview.html');
    }
    /**
     * Hedef gorunum, seri veya bolum icin gercek Blogger URL'sini veya yedek rotayi uretir.
     * @param {Object|null} catalog - Katalog denetleyicisi.
     * @param {'catalog'|'series'|'reader'|'generator'} viewName - Hedef gorunum.
     * @param {string} [seriesId=''] - Seri kimligi.
     * @param {string} [chapterId=''] - Bolum kimligi.
     * @returns {string} Hedef URL veya yol.
     */
    computeTargetUrl(catalog, viewName, seriesId = '', chapterId = '') {
      const isPreview = this.isLocalPreviewEnv();
      if (viewName === 'catalog') {
        return isPreview ? '#catalog' : '/';
      }
      if (viewName === 'bookmarks') {
        return isPreview ? '#kitaplik' : '/?gorunum=kitaplik';
      }
      if (viewName === 'history') {
        return isPreview ? '#gecmis' : '/?gorunum=gecmis';
      }
      if (viewName === 'generator') {
        return isPreview ? '#olusturucu' : '/?gorunum=olusturucu';
      }
      if (viewName === 'series' && seriesId) {
        const series = catalog ? catalog.getSeriesById(seriesId) : null;
        if (series && series.url && !isPreview) {
          try {
            const parsed = new URL(series.url);
            return parsed.pathname + parsed.search;
          } catch (_err) {
            if (series.url.startsWith('/')) return series.url;
          }
        }
        return isPreview
          ? `#seri/${encodeURIComponent(seriesId)}`
          : `/?seri=${encodeURIComponent(seriesId)}`;
      }
      if (viewName === 'reader' && seriesId && chapterId) {
        const series = catalog ? catalog.getSeriesById(seriesId) : null;
        const chapter =
          series && Array.isArray(series.chapters)
            ? series.chapters.find((c) => c.id === chapterId)
            : null;
        if (chapter && chapter.url && !isPreview) {
          try {
            const parsed = new URL(chapter.url);
            return parsed.pathname + parsed.search;
          } catch (_err) {
            if (chapter.url.startsWith('/')) return chapter.url;
          }
        }
        return isPreview
          ? `#oku/${encodeURIComponent(seriesId)}/${encodeURIComponent(chapterId)}`
          : `/?seri=${encodeURIComponent(seriesId)}&bolum=${encodeURIComponent(chapterId)}`;
      }
      return isPreview ? '#catalog' : '/';
    }
    /**
     * Tarayici adres cubugunu (URL), sayfa basligini ve History API gecmisini gunceller.
     * @param {Object} stateObj - History state nesnesi ({ view, seriesId, chapterId }).
     * @param {string} pageTitle - Yeni sayfa basligi.
     * @param {string} targetUrl - Yeni URL veya yol.
     * @param {Object} [options={}] - Gecmis guncelleme secenekleri.
     * @returns {void}
     */
    syncBrowserHistory(stateObj, pageTitle, targetUrl, options = {}) {
      const updateHistory = options.updateHistory !== undefined ? options.updateHistory : true;
      const replace = Boolean(options.replace);
      if (typeof document !== 'undefined' && pageTitle) {
        document.title = pageTitle;
      }
      if (!updateHistory || !this.historyObj) {
        return;
      }
      try {
        if (replace && typeof this.historyObj.replaceState === 'function') {
          this.historyObj.replaceState(stateObj, pageTitle, targetUrl);
          return;
        }
        if (typeof this.historyObj.pushState === 'function') {
          const cur = this.historyObj.state;
          const isSame =
            cur &&
            cur.view === stateObj.view &&
            (cur.seriesId || '') === (stateObj.seriesId || '') &&
            (cur.chapterId || '') === (stateObj.chapterId || '');
          if (!isSame) {
            this.historyObj.pushState(stateObj, pageTitle, targetUrl);
            if (this.logger && typeof this.logger.info === 'function') {
              this.logger.info('Tarayici URL pushState ile degistirildi.', {
                targetUrl,
                state: stateObj
              });
            }
          }
        }
      } catch (err) {
        if (this.logger && typeof this.logger.warn === 'function') {
          this.logger.warn('History pushState hatasi.', { error: err.message });
        }
      }
    }
    /**
     * Verilen URL'yi cozumleyerek hangi gorunumun acilmasi gerektigini dondurur.
     * @param {Object|null} catalog - Katalog denetleyicisi.
     * @param {string} [currentUrl] - Kontrol edilecek URL.
     * @returns {{ matched: boolean, view: string, seriesId: string, chapterId: string }}
     */
    resolveUrlRoute(catalog, currentUrl) {
      const empty = { matched: false, view: 'catalog', seriesId: '', chapterId: '' };
      if (!catalog) return empty;
      const href = currentUrl || (this.locationObj ? this.locationObj.href : '');
      if (!href) return empty;
      const hashIndex = href.indexOf('#');
      if (hashIndex >= 0) {
        const hashVal = href.slice(hashIndex + 1);
        if (hashVal.startsWith('oku/')) {
          const parts = hashVal.slice(4).split('/');
          if (parts.length >= 2) {
            return {
              matched: true,
              view: 'reader',
              seriesId: decodeURIComponent(parts[0]),
              chapterId: decodeURIComponent(parts[1])
            };
          }
        } else if (hashVal.startsWith('seri/')) {
          const sId = decodeURIComponent(hashVal.slice(5));
          if (sId) {
            return { matched: true, view: 'series', seriesId: sId, chapterId: '' };
          }
        } else if (hashVal === 'kitaplik') {
          return { matched: true, view: 'bookmarks', seriesId: '', chapterId: '' };
        } else if (hashVal === 'gecmis') {
          return { matched: true, view: 'history', seriesId: '', chapterId: '' };
        } else if (hashVal === 'olusturucu') {
          return { matched: true, view: 'generator', seriesId: '', chapterId: '' };
        }
      }
      try {
        const baseOrigin =
          this.locationObj && this.locationObj.origin && this.locationObj.origin.startsWith('http')
            ? this.locationObj.origin
            : 'https://example.blogspot.com';
        const parsedUrl = new URL(href, baseOrigin);
        const qSeri = parsedUrl.searchParams.get('seri');
        const qBolum = parsedUrl.searchParams.get('bolum');
        const qGorunum = parsedUrl.searchParams.get('gorunum');
        if (qGorunum === 'kitaplik') {
          return { matched: true, view: 'bookmarks', seriesId: '', chapterId: '' };
        }
        if (qGorunum === 'gecmis') {
          return { matched: true, view: 'history', seriesId: '', chapterId: '' };
        }
        if (qGorunum === 'olusturucu') {
          return { matched: true, view: 'generator', seriesId: '', chapterId: '' };
        }
        if (qSeri && qBolum) {
          return { matched: true, view: 'reader', seriesId: qSeri, chapterId: qBolum };
        }
        if (qSeri) {
          return { matched: true, view: 'series', seriesId: qSeri, chapterId: '' };
        }
      } catch (_err) {
        // Pathname kontrolune gec
      }
      if (!href.includes('.html')) {
        return empty;
      }
      const targetPath = extractPathname(href);
      if (targetPath.endsWith('/preview.html') || targetPath === '/' || targetPath === '') {
        return empty;
      }
      for (const series of catalog.seriesList) {
        for (const ch of series.chapters || []) {
          if (ch.url && extractPathname(ch.url) === targetPath) {
            return { matched: true, view: 'reader', seriesId: series.id, chapterId: ch.id };
          }
        }
        if (series.url && extractPathname(series.url) === targetPath) {
          return { matched: true, view: 'series', seriesId: series.id, chapterId: '' };
        }
      }
      for (const series of catalog.seriesList) {
        if (targetPath.includes(series.id)) {
          const bolumMatch = targetPath.match(/bolum-(\d+)/);
          if (bolumMatch) {
            const targetNo = Number(bolumMatch[1]);
            const foundCh = (series.chapters || []).find((c) => c.number === targetNo);
            if (foundCh) {
              return { matched: true, view: 'reader', seriesId: series.id, chapterId: foundCh.id };
            }
          }
          return { matched: true, view: 'series', seriesId: series.id, chapterId: '' };
        }
      }
      return empty;
    }
  }
  globalScope.RouterController = RouterController;
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = { RouterController, extractPathname };
  }
})(typeof window !== 'undefined' ? window : globalThis);

/* === MODULE: scripts/blogger-theme-bridge.js === */
/**
 * @fileoverview Blogger Tema Ozellestiricisi (Theme Designer), kalici Koyu/Acik tema modu,
 * ust baslik cubugu, Yan Panel (Sidebar) Gadget yerlesimi ve gelistirici araci koprusu.
 */

(function (globalScope) {
  'use strict';

  /**
   * Kullanicinin sectigi tema modunu saklamak icin kullanilan localStorage anahtari.
   * @type {string}
   */
  const THEME_STORAGE_KEY = 'manowa_theme_mode';

  /**
   * Blogger XML sablonu ile onyuz bilesenlerini birbirine baglayan kopru sinifi.
   */
  class BloggerThemeBridge {
    /**
     * BloggerThemeBridge nesnesini yapilandirir.
     * @param {Object} [options={}] - Yapilandirma secenekleri.
     * @param {Object} [options.logger] - Kullanilacak logger nesnesi.
     * @param {Object} [options.storage] - Ozellestirilmis depolama nesnesi (testler icin).
     */
    constructor(options = {}) {
      this.logger = options.logger || globalScope.ManowaLogger || null;
      this.storage =
        options.storage ||
        (typeof globalScope.localStorage !== 'undefined' ? globalScope.localStorage : null);
    }

    /**
     * Tema modunu ('dark' veya 'light') gecerli formata normalize eder.
     * @param {string} rawMode - Ham tema modu degeri.
     * @returns {'dark'|'light'} Normalize edilmis tema modu.
     */
    normalizeThemeMode(rawMode) {
      const cleaned = String(rawMode || '')
        .trim()
        .toLowerCase();
      return cleaned === 'light' ? 'light' : 'dark';
    }

    /**
     * Kullanicinin localStorage uzerinde kayitli tema tercihini okur.
     * @returns {'dark'|'light'|null} Kayitli tema modu veya yoksa null.
     */
    getSavedThemeMode() {
      if (!this.storage || typeof this.storage.getItem !== 'function') {
        return null;
      }
      try {
        const saved = this.storage.getItem(THEME_STORAGE_KEY);
        if (saved === 'light' || saved === 'dark') {
          return saved;
        }
      } catch (_err) {
        // Gizli sekme veya depolama erisim engeli durumunda sessizce gec
      }
      return null;
    }

    /**
     * Kullanicinin tema modu tercihini localStorage uzerine kaydeder.
     * @param {'dark'|'light'} mode - Kaydedilecek tema modu.
     * @returns {boolean} Kayit basariliysa true.
     */
    saveThemeMode(mode) {
      const normalized = this.normalizeThemeMode(mode);
      if (!this.storage || typeof this.storage.setItem !== 'function') {
        return false;
      }
      try {
        this.storage.setItem(THEME_STORAGE_KEY, normalized);
        return true;
      } catch (_err) {
        return false;
      }
    }

    /**
     * Blogger Yerlesim (Layout) yapilandirma widget'indan metin degerini okur ve temizler.
     * @param {string} elementId - Hedef DOM eleman kimligi.
     * @param {Document} [doc] - Hedef DOM belgesi.
     * @returns {string} Temizlenmis metin degeri.
     */
    readLayoutWidgetText(elementId, doc) {
      const targetDoc = doc || (typeof document !== 'undefined' ? document : null);
      if (!targetDoc || typeof targetDoc.getElementById !== 'function') {
        return '';
      }
      const el = targetDoc.getElementById(elementId);
      if (!el) {
        return '';
      }
      const raw =
        typeof el.textContent === 'string'
          ? el.textContent
          : String(el.innerHTML || '').replace(/<[^>]*>/g, '');
      return raw.trim();
    }

    /**
     * Blogger Yerlesim widget'indan (#blogger-cfg-theme-mode), <meta id="manowa-theme-mode-meta">
     * etiketinden veya <html> uzerinden varsayilan tema modunu cozumler.
     * @param {Document} [doc] - Hedef DOM belgesi.
     * @returns {'dark'|'light'} Varsayilan tema modu.
     */
    resolveDefaultThemeMode(doc) {
      const targetDoc = doc || (typeof document !== 'undefined' ? document : null);
      if (!targetDoc) {
        return 'dark';
      }
      const widgetMode = this.readLayoutWidgetText('blogger-cfg-theme-mode', targetDoc);
      if (widgetMode) {
        return this.normalizeThemeMode(widgetMode);
      }
      const metaEl =
        typeof targetDoc.getElementById === 'function'
          ? targetDoc.getElementById('manowa-theme-mode-meta')
          : null;
      const metaContent =
        metaEl && typeof metaEl.getAttribute === 'function'
          ? metaEl.getAttribute('content')
          : '';
      if (metaContent && metaContent.trim()) {
        return this.normalizeThemeMode(metaContent);
      }
      const htmlEl = targetDoc.documentElement;
      const htmlAttr =
        htmlEl && typeof htmlEl.getAttribute === 'function'
          ? htmlEl.getAttribute('data-theme')
          : '';
      return this.normalizeThemeMode(htmlAttr || 'dark');
    }

    /**
     * Blogger Yerlesim (Layout) ekranindaki Tema Degiskenleri widget'larini
     * (Disqus Shortname, Hero Gecis Suresi, Alt Bilgi Slogani, Ekibe Katil ve Discord Linkleri) okur ve uygular.
     * @param {Object} [targets={}] - Hedef denetleyiciler ({ disqus, heroSlider }).
     * @param {Document} [doc] - Hedef DOM belgesi.
     * @returns {{ disqusShortname: string, themeMode: string, heroIntervalMs: number, footerText: string, recruitUrl: string, discordUrl: string }} Uygulanan degerler.
     */
    applyLayoutConfigWidgets(targets = {}, doc) {
      const targetDoc = doc || (typeof document !== 'undefined' ? document : null);
      const disqusShortname = this.readLayoutWidgetText('blogger-cfg-disqus', targetDoc);
      if (disqusShortname && targets.disqus && typeof targets.disqus.setShortname === 'function') {
        targets.disqus.setShortname(disqusShortname);
      }

      const intervalRaw = this.readLayoutWidgetText('blogger-cfg-hero-interval', targetDoc);
      const parsedInterval = Number(intervalRaw);
      const heroIntervalMs =
        Number.isFinite(parsedInterval) && parsedInterval >= 1000 ? parsedInterval : 6000;
      if (targets.heroSlider && Number.isFinite(parsedInterval) && parsedInterval >= 1000) {
        targets.heroSlider.intervalMs = heroIntervalMs;
      }

      const footerText = this.readLayoutWidgetText('blogger-cfg-footer-text', targetDoc);
      if (footerText && targetDoc && typeof targetDoc.getElementById === 'function') {
        const sloganEl = targetDoc.getElementById('footer-slogan-text');
        if (sloganEl) {
          sloganEl.textContent = footerText;
        }
      }

      const applyBannerHref = (bannerId, rawUrl) => {
        if (!rawUrl || !targetDoc || typeof targetDoc.getElementById !== 'function') return;
        const bannerEl = targetDoc.getElementById(bannerId);
        if (!bannerEl) return;
        if (typeof bannerEl.setAttribute === 'function') {
          bannerEl.setAttribute('href', rawUrl);
          if (/^https?:\/\//i.test(rawUrl)) {
            bannerEl.setAttribute('target', '_blank');
            bannerEl.setAttribute('rel', 'noopener noreferrer');
          }
        } else {
          bannerEl.href = rawUrl;
        }
      };

      const recruitUrl = this.readLayoutWidgetText('blogger-cfg-recruit-url', targetDoc);
      applyBannerHref('banner-join-team', recruitUrl);

      const discordUrl = this.readLayoutWidgetText('blogger-cfg-discord-url', targetDoc);
      applyBannerHref('banner-join-discord', discordUrl);

      return {
        disqusShortname,
        themeMode: this.resolveDefaultThemeMode(targetDoc),
        heroIntervalMs,
        footerText,
        recruitUrl,
        discordUrl
      };
    }

    /**
     * Belirtilen tema modunu <html> etiketine uygular.
     * @param {'dark'|'light'} mode - Uygulanacak tema modu.
     * @param {Document} [doc] - Hedef DOM belgesi.
     * @returns {'dark'|'light'} Uygulanan tema modu.
     */
    applyThemeMode(mode, doc) {
      const normalized = this.normalizeThemeMode(mode);
      const targetDoc = doc || (typeof document !== 'undefined' ? document : null);
      if (targetDoc && targetDoc.documentElement) {
        targetDoc.documentElement.setAttribute('data-theme', normalized);
      }
      if (this.logger && typeof this.logger.debug === 'function') {
        this.logger.debug('Blogger tema modu uygulandi.', { theme: normalized });
      }
      return normalized;
    }

    /**
     * Baslangic tema modunu (once localStorage, yoksa Blogger Özelleştirici varsayilani) yukler.
     * @param {Document} [doc] - Hedef DOM belgesi.
     * @returns {'dark'|'light'} Baslatilan tema modu.
     */
    initThemeMode(doc) {
      const savedMode = this.getSavedThemeMode();
      const initialMode = savedMode || this.resolveDefaultThemeMode(doc);
      return this.applyThemeMode(initialMode, doc);
    }

    /**
     * Koyu ve Acik tema arasinda gecis yapar ve secimi kalici olarak kaydeder.
     * @param {Document} [doc] - Hedef DOM belgesi.
     * @returns {'dark'|'light'} Yeni aktif tema modu.
     */
    toggleThemeMode(doc) {
      const targetDoc = doc || (typeof document !== 'undefined' ? document : null);
      const htmlEl = targetDoc ? targetDoc.documentElement : null;
      const current =
        htmlEl && typeof htmlEl.getAttribute === 'function'
          ? htmlEl.getAttribute('data-theme')
          : 'dark';
      const next = current === 'light' ? 'dark' : 'light';
      this.applyThemeMode(next, targetDoc);
      this.saveThemeMode(next);
      if (this.logger && typeof this.logger.info === 'function') {
        this.logger.info('Tema modu degistirildi.', { theme: next });
      }
      return next;
    }

    /**
     * Mobil hamburger menuyu (#mobile-nav-drawer) acar veya kapatir.
     * @param {boolean} [force] - Zorunlu acik/kapali durumu.
     * @param {Document} [doc] - Hedef DOM belgesi.
     * @returns {boolean} Menunun yeni acik/kapali durumu.
     */
    toggleMobileMenu(force, doc) {
      const targetDoc = doc || (typeof document !== 'undefined' ? document : null);
      if (!targetDoc || typeof targetDoc.getElementById !== 'function') return false;
      const topBar = targetDoc.getElementById('top-app-bar');
      const drawer = targetDoc.getElementById('mobile-nav-drawer');
      const btn = targetDoc.getElementById('btn-mobile-menu');
      if (!drawer) return false;
      const isOpen =
        typeof force === 'boolean'
          ? force
          : !(drawer.classList && drawer.classList.contains('is-mobile-open'));
      if (drawer.classList) drawer.classList.toggle('is-mobile-open', isOpen);
      if (topBar && topBar.classList) topBar.classList.toggle('is-menu-open', isOpen);
      if (btn) {
        if (typeof btn.setAttribute === 'function') {
          btn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
        }
        if (btn.classList) btn.classList.toggle('active', isOpen);
        if (typeof btn.querySelector === 'function') {
          const openIcon = btn.querySelector('.icon-menu-open');
          const closeIcon = btn.querySelector('.icon-menu-close');
          if (openIcon && openIcon.classList) openIcon.classList.toggle('hidden', isOpen);
          if (closeIcon && closeIcon.classList) closeIcon.classList.toggle('hidden', !isOpen);
        }
      }
      if (isOpen) {
        this.toggleMobileSearch(false, targetDoc);
      }
      return isOpen;
    }

    /**
     * Mobil arama cubugunu (#header-search-box) acar veya kapatir.
     * @param {boolean} [force] - Zorunlu acik/kapali durumu.
     * @param {Document} [doc] - Hedef DOM belgesi.
     * @returns {boolean} Arama cubugunun yeni acik/kapali durumu.
     */
    toggleMobileSearch(force, doc) {
      const targetDoc = doc || (typeof document !== 'undefined' ? document : null);
      if (!targetDoc || typeof targetDoc.getElementById !== 'function') return false;
      const topBar = targetDoc.getElementById('top-app-bar');
      const searchBox = targetDoc.getElementById('header-search-box');
      const btn = targetDoc.getElementById('btn-mobile-search');
      const input = targetDoc.getElementById('input-search');
      if (!searchBox) return false;
      const isOpen =
        typeof force === 'boolean'
          ? force
          : !(searchBox.classList && searchBox.classList.contains('is-mobile-open'));
      if (searchBox.classList) searchBox.classList.toggle('is-mobile-open', isOpen);
      if (topBar && topBar.classList) topBar.classList.toggle('is-search-open', isOpen);
      if (btn) {
        if (typeof btn.setAttribute === 'function') {
          btn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
        }
        if (btn.classList) btn.classList.toggle('active', isOpen);
      }
      if (isOpen) {
        this.toggleMobileMenu(false, targetDoc);
        if (input && typeof input.focus === 'function') {
          input.focus();
        }
      }
      return isOpen;
    }

    /**
     * Acik olan mobil hamburger menuyu ve mobil arama panelini kapatir.
     * @param {Document} [doc] - Hedef DOM belgesi.
     * @returns {void}
     */
    closeMobilePanels(doc) {
      this.toggleMobileMenu(false, doc);
      this.toggleMobileSearch(false, doc);
    }

    /**
     * Mobil hamburger menu ve mobil arama dugmesi olay dinleyicilerini baglar.
     * @param {Document} [doc] - Hedef DOM belgesi.
     * @returns {void}
     */
    bindMobileHeaderEvents(doc) {
      const targetDoc = doc || (typeof document !== 'undefined' ? document : null);
      if (!targetDoc || typeof targetDoc.getElementById !== 'function') return;
      const menuBtn = targetDoc.getElementById('btn-mobile-menu');
      const searchBtn = targetDoc.getElementById('btn-mobile-search');
      const drawer = targetDoc.getElementById('mobile-nav-drawer');

      if (menuBtn && !menuBtn._manowaBound && typeof menuBtn.addEventListener === 'function') {
        menuBtn._manowaBound = true;
        menuBtn.addEventListener('click', () => this.toggleMobileMenu(undefined, targetDoc));
      }
      if (searchBtn && !searchBtn._manowaBound && typeof searchBtn.addEventListener === 'function') {
        searchBtn._manowaBound = true;
        searchBtn.addEventListener('click', () => this.toggleMobileSearch(undefined, targetDoc));
      }
      if (drawer && !drawer._manowaBound && typeof drawer.addEventListener === 'function') {
        drawer._manowaBound = true;
        drawer.addEventListener('click', (ev) => {
          if (ev && ev.target && typeof ev.target.closest === 'function') {
            if (ev.target.closest('.nav-btn')) {
              this.toggleMobileMenu(false, targetDoc);
            }
          }
        });
      }
    }

    /**
     * Ust kontrol cubugunu (#top-app-bar) Blogger site basliginin (#site-header-inner) icine tasir.
     * @param {Document} [doc] - Hedef DOM belgesi.
     * @returns {boolean} Tasima islemi yapildiysa true.
     */
    integrateHeaderBar(doc) {
      const targetDoc = doc || (typeof document !== 'undefined' ? document : null);
      if (!targetDoc) return false;
      this.bindMobileHeaderEvents(targetDoc);
      const headerInner =
        targetDoc.getElementById('site-header-inner') ||
        (typeof targetDoc.querySelector === 'function'
          ? targetDoc.querySelector('.site-header .header-inner')
          : null);
      const topAppBar = targetDoc.getElementById('top-app-bar');
      if (headerInner && topAppBar && topAppBar.parentElement !== headerInner) {
        topAppBar.classList.add('in-header');
        headerInner.appendChild(topAppBar);
        return true;
      }
      return false;
    }

    /**
     * Blogger Yerlesim / Ozellestirici uzerinden eklenen Yan Panel Gadget bolumunu
     * (#sidebar-gadgets-section) sag yan panelin (#home-sidebar) icine tasir.
     * @param {Document} [doc] - Hedef DOM belgesi.
     * @returns {boolean} Tasima islemi yapildiysa true.
     */
    integrateSidebarGadgets(doc) {
      const targetDoc = doc || (typeof document !== 'undefined' ? document : null);
      if (!targetDoc || typeof targetDoc.getElementById !== 'function') return false;
      const sidebarEl = targetDoc.getElementById('home-sidebar');
      const gadgetsSection = targetDoc.getElementById('sidebar-gadgets-section');
      if (sidebarEl && gadgetsSection && gadgetsSection.parentElement !== sidebarEl) {
        sidebarEl.appendChild(gadgetsSection);
        if (this.logger && typeof this.logger.debug === 'function') {
          this.logger.debug('Blogger yan panel gadget alani #home-sidebar icine tasindi.');
        }
        return true;
      }
      return false;
    }

    /**
     * Gelistirici DEBUG log panelini gunceller.
     * @param {Object} [logger] - Log nesnesi.
     * @param {Document} [doc] - Hedef DOM belgesi.
     * @returns {void}
     */
    renderDebugLogs(logger, doc) {
      const targetDoc = doc || (typeof document !== 'undefined' ? document : null);
      const activeLogger = logger || this.logger;
      if (!targetDoc || typeof targetDoc.getElementById !== 'function') return;
      const listEl = targetDoc.getElementById('debug-log-list');
      if (!listEl || !activeLogger || typeof activeLogger.getEntries !== 'function') return;
      const entries = activeLogger.getEntries().slice(-15).reverse();
      listEl.innerHTML = entries
        .map((e) => `<div>[${e.timestamp}] <strong>[${e.level}]</strong> ${e.message}</div>`)
        .join('');
    }

    /**
     * Gelistirici gonderi olusturucu form verilerini okuyup cikti uretir.
     * @param {Object} generator - PostGenerator nesnesi.
     * @param {'series'|'chapter'} mode - Olusturma modu.
     * @param {Document} [doc] - Hedef DOM belgesi.
     * @returns {Object|null} Uretilen kod nesnesi.
     */
    runGeneratorFromDom(generator, mode, doc) {
      if (!generator) return null;
      const targetDoc = doc || (typeof document !== 'undefined' ? document : null);
      const getVal = (id, fallback) => {
        const el = targetDoc && targetDoc.getElementById ? targetDoc.getElementById(id) : null;
        return (el && el.value) || fallback;
      };
      const title = getVal('gen-series-title', 'Yeni Seri');
      const sourceLang = getVal('gen-source-lang', 'KR');
      const chapterNumber = getVal('gen-chapter-num', 1);
      const readerMode = getVal('gen-reader-mode', 'webtoon');
      const translatorNote = getVal('gen-translator-note', '');
      const pages = getVal('gen-pages-input', '');
      const res =
        mode === 'series'
          ? generator.generateSeriesPost({ title, sourceLang, defaultReaderMode: readerMode })
          : generator.generateChapterPost({
              seriesTitle: title,
              chapterNumber,
              readerMode,
              translatorNote,
              pages
            });
      if (targetDoc && targetDoc.getElementById) {
        const outEl = targetDoc.getElementById('gen-code-output');
        const labelsEl = targetDoc.getElementById('gen-labels-info');
        if (outEl) outEl.value = res.html;
        if (labelsEl) labelsEl.textContent = `Önerilen Blogger Etiketleri: ${res.labels}`;
      }
      return res;
    }

    /**
     * DOM uzerindeki .manowa-series-post dugumlerinden katalog serilerini yukler.
     * @param {Object} catalog - CatalogController nesnesi.
     * @param {string} [siteBaseTitle='Manowa'] - Site basligi.
     * @param {Document} [doc] - Hedef DOM belgesi.
     * @returns {number} Islenen seri sayisi.
     */
    ingestDomSeriesNodes(catalog, siteBaseTitle = 'Manowa', doc) {
      const targetDoc = doc || (typeof document !== 'undefined' ? document : null);
      if (!targetDoc || !catalog || typeof targetDoc.querySelectorAll !== 'function') return 0;
      let count = 0;
      const seriesNodes = targetDoc.querySelectorAll('.manowa-series-post');
      seriesNodes.forEach((node) => {
        const id = node.getAttribute('data-series-id');
        if (!id) return;
        const existing = catalog.getSeriesById(id);
        catalog.upsertSeries({
          id,
          title: node.getAttribute('data-title') || id,
          altTitle: node.getAttribute('data-alt-title') || '',
          sourceLang: node.getAttribute('data-source-lang') || 'KR',
          type: node.getAttribute('data-type') || 'Manhwa',
          defaultReaderMode: node.getAttribute('data-reader-mode') || 'webtoon',
          status: node.getAttribute('data-status') || 'Devam Ediyor',
          translator: node.getAttribute('data-translator') || siteBaseTitle,
          rating: '9.6',
          genres: (node.getAttribute('data-genres') || 'Aksiyon').split(',').map((s) => s.trim()),
          cover: node.getAttribute('data-cover') || '',
          synopsis: node.textContent.trim(),
          chapters: existing ? existing.chapters : []
        });
        count++;
      });
      return count;
    }
  }

  globalScope.BloggerThemeBridge = BloggerThemeBridge;

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = { BloggerThemeBridge, THEME_STORAGE_KEY };
  }
})(typeof window !== 'undefined' ? window : globalThis);

/* === MODULE: scripts/search-controller.js === */
/**
 * @fileoverview Arama cubuguna yazilan girdileri dinleyerek canli, erisilebilir ve klavye destekli
 * bir acilir liste kutusu (Listbox / Combobox) uretip yoneten moduler arama denetleyicisi (SearchController).
 * W3C WAI-ARIA Combobox standartlarina, Turkce karakter normalizasyonuna ve otomatik DEBUG loglamasina tam uyumludur.
 */

(function (globalScope) {
  'use strict';

  /**
   * HTML karakterlerini XSS guvenligi icin kacis dizilerine donusturur.
   * @param {string} str - Temizlenecek metin.
   * @returns {string} Guvenli HTML metni.
   */
  function escapeHtml(str) {
    return String(str || '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  /**
   * Turkce karakterleri kucuk harfe donusturup aksanlardan arindirarak arama icin normallestirir.
   * @param {string} str - Ham metin.
   * @returns {string} Normallestirilmis kucuk harfli metin.
   */
  function normalizeSearchText(str) {
    return String(str || '')
      .toLocaleLowerCase('tr')
      .replace(/ı/g, 'i')
      .replace(/ğ/g, 'g')
      .replace(/ü/g, 'u')
      .replace(/ş/g, 's')
      .replace(/ö/g, 'o')
      .replace(/ç/g, 'c')
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .trim();
  }

  /**
   * Karakteri arama normalizasyonu icin 1'e 1 karsiligina donusturur.
   * @param {string} ch - Tek bir karakter.
   * @returns {string} Normallestirilmis tek karakter.
   */
  function toNormalizedChar(ch) {
    const lower = String(ch || '').toLocaleLowerCase('tr');
    const map = {
      'ı': 'i', 'i': 'i',
      'ğ': 'g', 'g': 'g',
      'ü': 'u', 'u': 'u',
      'ş': 's', 's': 's',
      'ö': 'o', 'o': 'o',
      'ç': 'c', 'c': 'c',
      'â': 'a', 'î': 'i', 'û': 'u',
      'é': 'e', 'è': 'e'
    };
    return map[lower] || lower;
  }

  /**
   * Metin icinde sorgu ile eslesen kisimlari guvenli sekilde <mark class="search-highlight"> ile sarar.
   * Orijinal harf buyuklugunu ve ozel karakterleri (XSS) korur.
   * @param {string} text - Orijinal kaynak metin.
   * @param {string} query - Arama sorgusu.
   * @returns {string} Vurgulanmis HTML dizgesi.
   */
  function highlightMatch(text, query) {
    if (!text) return '';
    const cleanText = String(text);
    const cleanQuery = normalizeSearchText(query);
    if (!cleanQuery) return escapeHtml(cleanText);

    let normText = '';
    for (let i = 0; i < cleanText.length; i++) {
      normText += toNormalizedChar(cleanText[i]);
    }

    const matchIdx = normText.indexOf(cleanQuery);
    if (matchIdx === -1) {
      return escapeHtml(cleanText);
    }

    const before = cleanText.slice(0, matchIdx);
    const matched = cleanText.slice(matchIdx, matchIdx + cleanQuery.length);
    const after = cleanText.slice(matchIdx + cleanQuery.length);

    return `${escapeHtml(before)}<mark class="search-highlight">${escapeHtml(matched)}</mark>${highlightMatch(after, query)}`;
  }

  /**
   * Arama sonuclari acilir liste kutusunu yoneten sinif.
   */
  class SearchController {
    /**
     * SearchController nesnesini yapilandirir.
     * @param {Object} [options={}] - Yapilandirma ayarlari.
     * @param {HTMLInputElement|string} [options.input='input-search'] - Arama input ogesi veya id degeri.
     * @param {HTMLElement|string} [options.listbox='search-results-listbox'] - Listbox kapsayici ogesi veya id degeri.
     * @param {HTMLElement|string} [options.container='header-search-box'] - Ust arama kapsayici ogesi veya id degeri.
     * @param {Function} [options.getSeriesList] - Katalogdaki serileri donduren fonksiyon.
     * @param {Function} [options.onSelect] - Bir seri secildiginde calisacak geri cagirim.
     * @param {Function} [options.onViewAll] - Tum sonuclar goruntulenmek istendiginde calisacak geri cagirim.
     * @param {Object} [options.logger=null] - Loglama nesnesi.
     * @param {number} [options.maxResults=8] - Acilir listede gosterilecek azami seri sayisi.
     * @param {number} [options.minQueryLength=1] - Aramanin tetiklenmesi icin gereken asgari karakter sayisi.
     */
    constructor(options = {}) {
      this.options = options;
      this.logger = options.logger || globalScope.ManowaLogger || null;
      this.getSeriesList =
        typeof options.getSeriesList === 'function' ? options.getSeriesList : () => [];
      this.onSelect = typeof options.onSelect === 'function' ? options.onSelect : null;
      this.onViewAll = typeof options.onViewAll === 'function' ? options.onViewAll : null;
      this.maxResults = typeof options.maxResults === 'number' ? options.maxResults : 8;
      this.minQueryLength =
        typeof options.minQueryLength === 'number' ? options.minQueryLength : 1;

      this.inputEl = null;
      this.listboxEl = null;
      this.containerEl = null;

      this.isOpen = false;
      this.activeIndex = -1;
      this.currentResults = [];
      this.currentQuery = '';

      this._boundInput = this._handleInput.bind(this);
      this._boundKeyDown = this._handleKeyDown.bind(this);
      this._boundFocus = this._handleFocus.bind(this);
      this._boundDocumentClick = this._handleDocumentClick.bind(this);
      this._boundListboxClick = this._handleListboxClick.bind(this);

      this._initElements();
      this._log('debug', 'SearchController baslatildi.', {
        maxResults: this.maxResults,
        minQueryLength: this.minQueryLength
      });
    }

    /**
     * Ic loglama yardimcisi.
     * @param {'debug'|'info'|'warn'|'error'} level - Log seviyesi.
     * @param {string} msg - Mesaj.
     * @param {Object|null} [meta=null] - Ek veri nesnesi.
     * @returns {void}
     */
    _log(level, msg, meta = null) {
      if (this.logger && typeof this.logger[level] === 'function') {
        this.logger[level](msg, meta);
      }
    }

    /**
     * DOM ogelerini cozumler ve baglantilari kurar.
     * @returns {boolean} Ogeler basariyla baglandiysa true.
     */
    _initElements() {
      const resolveEl = (elOrId) => {
        if (!elOrId) return null;
        if (typeof elOrId === 'string') {
          if (typeof document !== 'undefined' && typeof document.getElementById === 'function') {
            return document.getElementById(elOrId);
          }
          return null;
        }
        if (typeof elOrId === 'object') return elOrId;
        return null;
      };

      this.inputEl = resolveEl(this.options.input || 'input-search');
      this.listboxEl = resolveEl(this.options.listbox || 'search-results-listbox');
      this.containerEl = resolveEl(this.options.container || 'header-search-box');

      if (!this.listboxEl && this.containerEl && typeof document !== 'undefined' && typeof document.createElement === 'function') {
        // Listbox DOM'da yoksa dinamik olarak olustur
        this.listboxEl = document.createElement('div');
        this.listboxEl.id = 'search-results-listbox';
        this.listboxEl.className = 'search-results-listbox hidden';
        this.listboxEl.setAttribute('role', 'listbox');
        this.listboxEl.setAttribute('aria-label', 'Arama Sonuçları');
        this.containerEl.appendChild(this.listboxEl);
      }

      if (this.inputEl) {
        if (typeof this.inputEl.setAttribute === 'function') {
          this.inputEl.setAttribute('role', 'combobox');
          this.inputEl.setAttribute('aria-autocomplete', 'list');
          this.inputEl.setAttribute('aria-expanded', 'false');
          this.inputEl.setAttribute('autocomplete', 'off');
          if (this.listboxEl && this.listboxEl.id) {
            this.inputEl.setAttribute('aria-controls', this.listboxEl.id);
          }
        }

        if (typeof this.inputEl.removeEventListener === 'function') {
          this.inputEl.removeEventListener('input', this._boundInput);
          this.inputEl.removeEventListener('keydown', this._boundKeyDown);
          this.inputEl.removeEventListener('focus', this._boundFocus);
        }

        if (typeof this.inputEl.addEventListener === 'function') {
          this.inputEl.addEventListener('input', this._boundInput);
          this.inputEl.addEventListener('keydown', this._boundKeyDown);
          this.inputEl.addEventListener('focus', this._boundFocus);
        }
      }

      if (this.listboxEl) {
        if (typeof this.listboxEl.removeEventListener === 'function') {
          this.listboxEl.removeEventListener('click', this._boundListboxClick);
        }
        if (typeof this.listboxEl.addEventListener === 'function') {
          this.listboxEl.addEventListener('click', this._boundListboxClick);
        }
      }

      if (typeof document !== 'undefined' && typeof document.addEventListener === 'function') {
        document.removeEventListener('pointerdown', this._boundDocumentClick);
        document.addEventListener('pointerdown', this._boundDocumentClick);
      }

      return Boolean(this.inputEl && this.listboxEl);
    }

    /**
     * Verilen sorguya gore serileri filtreler ve uygunluk sirasina gore dizer.
     * @param {string} query - Arama sorgusu.
     * @returns {Array<Object>} Filtrelenmis ve puanlanmis seri listesi.
     */
    searchSeries(query) {
      const clean = normalizeSearchText(query);
      if (!clean) return [];

      const list = this.getSeriesList();
      if (!Array.isArray(list) || list.length === 0) return [];

      const matches = [];

      for (let i = 0; i < list.length; i++) {
        const item = list[i];
        const titleNorm = normalizeSearchText(item.title);
        const altNorm = normalizeSearchText(item.altTitle);
        const typeNorm = normalizeSearchText(item.type);
        const statusNorm = normalizeSearchText(item.status);
        const genresNorm = normalizeSearchText((item.genres || []).join(' '));

        let score = 0;

        if (titleNorm === clean) {
          score = 100;
        } else if (titleNorm.startsWith(clean)) {
          score = 80;
        } else if (titleNorm.includes(clean)) {
          score = 60;
        } else if (altNorm && (altNorm.startsWith(clean) || altNorm.includes(clean))) {
          score = 40;
        } else if (genresNorm.includes(clean)) {
          score = 30;
        } else if (typeNorm.includes(clean) || statusNorm.includes(clean)) {
          score = 20;
        }

        if (score > 0) {
          matches.push({ item, score });
        }
      }

      matches.sort((a, b) => {
        if (b.score !== a.score) return b.score - a.score;
        return String(a.item.title || '').localeCompare(String(b.item.title || ''), 'tr');
      });

      return matches.map((m) => m.item);
    }

    /**
     * Arama girdi olayini (input) isler.
     * @param {Event} e - Girdi olayi.
     * @returns {void}
     */
    _handleInput(e) {
      const val = e && e.target ? e.target.value : '';
      this.executeSearch(val);
    }

    /**
     * Arama islemini baslatir ve listbox bilesenini gunceller.
     * @param {string} query - Arama sorgusu.
     * @returns {void}
     */
    executeSearch(query) {
      this.currentQuery = String(query || '').trim();

      if (this.currentQuery.length < this.minQueryLength) {
        this.close();
        this.currentResults = [];
        return;
      }

      this.currentResults = this.searchSeries(this.currentQuery);
      this._log('debug', 'Canli arama calistirildi.', {
        query: this.currentQuery,
        foundCount: this.currentResults.length
      });

      this.render();
      this.open();
    }

    /**
     * Odaklanma (focus) olayini isler.
     * @returns {void}
     */
    _handleFocus() {
      if (this.inputEl && this.inputEl.value.trim().length >= this.minQueryLength) {
        this.executeSearch(this.inputEl.value);
      }
    }

    /**
     * Klavye tuslarini (ArrowDown, ArrowUp, Enter, Escape) dinler ve yonetir.
     * @param {KeyboardEvent} e - Klavye olayi.
     * @returns {void}
     */
    _handleKeyDown(e) {
      if (!this.isOpen && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) {
        if (this.inputEl && this.inputEl.value.trim().length >= this.minQueryLength) {
          e.preventDefault();
          this.executeSearch(this.inputEl.value);
          return;
        }
      }

      if (!this.isOpen) return;

      const totalItems = this._getTotalInteractiveItemsCount();
      if (totalItems === 0 && e.key !== 'Escape') return;

      switch (e.key) {
        case 'ArrowDown':
          e.preventDefault();
          this.setActiveIndex(this.activeIndex < totalItems - 1 ? this.activeIndex + 1 : 0);
          break;
        case 'ArrowUp':
          e.preventDefault();
          this.setActiveIndex(this.activeIndex > 0 ? this.activeIndex - 1 : totalItems - 1);
          break;
        case 'Enter':
          e.preventDefault();
          this._selectCurrentActive();
          break;
        case 'Escape':
          e.preventDefault();
          this.close();
          break;
        case 'Tab':
          this.close();
          break;
        default:
          break;
      }
    }

    /**
     * Etkilesimli secenek sayisini (sonuclar + varsa "tumunu gor" satiri) dondurur.
     * @returns {number} Toplam etkilesimli secenek sayisi.
     */
    _getTotalInteractiveItemsCount() {
      if (!this.currentResults || this.currentResults.length === 0) return 0;
      const count = Math.min(this.currentResults.length, this.maxResults);
      // Sonuclar varsa en altta "Tum sonuclari katalogda gor" butonu da 1 secenektir
      return count + 1;
    }

    /**
     * Aktif secenek indeksini gunceller ve ekranda odaklanmasini saglar.
     * @param {number} newIndex - Yeni aktif indeks.
     * @returns {void}
     */
    setActiveIndex(newIndex) {
      this.activeIndex = newIndex;
      if (!this.listboxEl) return;

      const items = this.listboxEl.querySelectorAll('[role="option"]');
      items.forEach((item, idx) => {
        const isActive = idx === this.activeIndex;
        item.classList.toggle('is-active', isActive);
        item.setAttribute('aria-selected', isActive ? 'true' : 'false');
        if (isActive) {
          if (this.inputEl) {
            this.inputEl.setAttribute('aria-activedescendant', item.id);
          }
          if (typeof item.scrollIntoView === 'function') {
            item.scrollIntoView({ block: 'nearest' });
          }
        }
      });

      if (this.activeIndex === -1 && this.inputEl) {
        this.inputEl.removeAttribute('aria-activedescendant');
      }
    }

    /**
     * O an aktif olan secenegi calistirir.
     * @returns {void}
     */
    _selectCurrentActive() {
      if (this.activeIndex === -1) {
        // Hicbir oge secilmemisse ilk ogeyi sec veya tumunu gor calistir
        if (this.currentResults.length > 0) {
          this.selectSeries(this.currentResults[0].id);
        } else if (this.onViewAll) {
          this.triggerViewAll();
        }
        return;
      }

      const totalResults = Math.min(this.currentResults.length, this.maxResults);
      if (this.activeIndex < totalResults) {
        const chosen = this.currentResults[this.activeIndex];
        if (chosen) {
          this.selectSeries(chosen.id);
        }
      } else {
        // En alttaki "Tum sonuclari katalogda gor" satiri secildi
        this.triggerViewAll();
      }
    }

    /**
     * Bir seriyi secer, ayrinti sayfasina yonlendirir ve listbox'i kapatir.
     * @param {string} seriesId - Seri kimligi.
     * @returns {void}
     */
    selectSeries(seriesId) {
      this._log('info', 'Listbox uzerinden seri secildi.', { seriesId });
      const targetSeries = (this.getSeriesList() || []).find((s) => s.id === seriesId);
      this.close();

      if (this.inputEl) {
        this.inputEl.value = '';
      }

      if (typeof this.onSelect === 'function') {
        this.onSelect(seriesId, targetSeries);
      }
    }

    /**
     * "Tum sonuclari katalogda gor" aksiyonunu tetikler.
     * @returns {void}
     */
    triggerViewAll() {
      const q = this.currentQuery;
      this._log('info', 'Tum sonuclari katalogda gor secildi.', { query: q });
      this.close();

      if (typeof this.onViewAll === 'function') {
        this.onViewAll(q, this.currentResults.length);
      }
    }

    /**
     * Listbox ici tiklamalari delegasyon ile dinler.
     * @param {MouseEvent} e - Tiklama olayi.
     * @returns {void}
     */
    _handleListboxClick(e) {
      if (!e || !e.target) return;

      const viewAllBtn = e.target.closest('[data-action="view-all"]');
      if (viewAllBtn) {
        e.preventDefault();
        this.triggerViewAll();
        return;
      }

      const itemEl = e.target.closest('[data-series-id]');
      if (itemEl) {
        e.preventDefault();
        const id = itemEl.getAttribute('data-series-id');
        if (id) {
          this.selectSeries(id);
        }
      }
    }

    /**
     * Arama kutusu disina tiklandiginda listbox'i kapatir.
     * @param {PointerEvent|MouseEvent} e - Tiklama olayi.
     * @returns {void}
     */
    _handleDocumentClick(e) {
      if (!this.isOpen) return;
